/* Beziehungsdynamiken 15.12.122 · 16 fiktive Beratungssituationen, 8 Runden. */
window.BDTalk121Cases=[{"id":"vorwurf","category":"Allianz & Widerstand","title":"Sie geben mir auch die Schuld!","level":2,"goal":"Allianzbruch aufnehmen und Kontakt reparieren","context":"Ein Klient reagiert auf deine Frage nach seinem Anteil am Streit mit einem persönlichen Vorwurf. Du sitzt mit ihm allein im Gespräch.","opening":"Sie machen es genauso wie meine Partnerin. Am Ende bin wieder ich an allem schuld!","guard":"Nicht die eigene Unschuld beweisen. Zuerst die Wirkung der Intervention und die aktuelle Beziehung klären.","rounds":[{"focus":"Den Vorwurf an dich aufnehmen","options":[{"say":"Meine Frage ist bei Ihnen als Vorwurf angekommen. Was genau hat Sie daran getroffen?","why":"Du klärst den aktuellen Bruch und interessierst dich für die Wirkung deiner Worte.","reply":"Als Sie nach meinem Anteil fragten, habe ich sofort gedacht: Jetzt steht auch noch der Berater gegen mich.","cue":"[Der Blick hebt sich; die Stimme wird etwas ruhiger.]"},{"say":"Ich möchte beide Seiten verstehen. Was hat sich gerade unfair angefühlt?","why":"Du betonst Fairness und bietest eine offene Klärung an; der unmittelbare Beziehungsbruch bleibt etwas indirekt.","reply":"Unfair ist, dass immer nur auf meine Reaktion geschaut wird.","cue":"[Die Person nickt einmal, blickt dann zur Seite.]"},{"say":"Könnten wir einmal auseinanderhalten, wer wofür verantwortlich ist?","why":"Verantwortung ist wichtig, aber im Moment wird sie womöglich als erneuter Vorwurf erlebt.","reply":"Schon wieder Verantwortung! Genau dieses Wort macht mich wahnsinnig.","cue":"[Die Stirn legt sich in Falten; die Antwort wird kürzer.]"},{"say":"Darf ich zuerst erklären, weshalb ich diese Frage gestellt habe?","why":"Die Absicht transparent zu machen kann Verbindung fördern, aber bei akutem Allianzbruch kann es als Rechtfertigung wirken.","reply":"Vielleicht. Aber mir ist wichtiger, dass Sie erst verstehen, wie es ankam.","cue":"[Die Stimme wird deutlich lauter; die Arme verschränken sich.]"}]},{"focus":"Die Eskalation verlangsamen","options":[{"say":"Bevor wir weiter analysieren: Was ist in den Sekunden vor Ihrer Abwehr innerlich passiert?","why":"Du begleitest die eigene Reaktionskette statt den Streit über Schuld fortzusetzen.","reply":"Ich wurde ganz eng im Brustkorb. Ich dachte: Ich muss mich sofort wehren.","cue":"[Die Person hält kurz inne und lässt die Hände sinken.]"},{"say":"Welcher Satz würde Ihnen gerade zeigen, dass ich Sie wirklich verstanden habe?","why":"Du fragst nach einem konkreten Reparatursignal; der innere Prozess könnte später vertieft werden.","reply":"Wenn Sie anerkennen, dass ich mich dauernd als der Böse fühle.","cue":"[Ein Finger streicht über den Ärmel; die Stimme bleibt leise.]"},{"say":"Was hat Ihre Partnerin in dieser Situation genau gesagt?","why":"Ein konkretes Beispiel kann hilfreich sein, verlagert den Fokus jedoch zurück auf ihr Verhalten.","reply":"Sie hat mich wieder unterbrochen. Da wurde ich sofort laut.","cue":"[Die Person schüttelt leicht den Kopf und atmet hörbar aus.]"},{"say":"Wäre es sinnvoll, eine hilfreiche Gesprächsregel für solche Momente festzuhalten?","why":"Eine Regel klingt konstruktiv, setzt aber bereits Regulation voraus und überspringt den aktuellen Kontaktbruch.","reply":"Regeln können helfen, nur bin ich gerade noch sehr angespannt.","cue":"[Die Person blickt weg und schweigt mehrere Sekunden.]"}]},{"focus":"Die darunterliegende Verletzlichkeit erreichen","options":[{"say":"Wenn Sie dieses enge Gefühl ernst nehmen: Was befürchten Sie in dem Moment am meisten?","why":"Du öffnest Raum für Angst und verletzliche Bedürfnisse ohne das Verhalten zu entschuldigen.","reply":"Dass ich überhaupt nicht zähle. Als wäre alles, was ich sage, wertlos.","cue":"[Die Schultern lösen sich ein wenig; es folgt eine längere Antwort.]"},{"say":"Wie würden Sie dieses Gefühl Ihrer Partnerin in einem einzigen Satz mitteilen?","why":"Eine konkrete neue Formulierung ist sinnvoll, könnte aber für die momentane Aktivierung noch zu früh sein.","reply":"Vielleicht: Ich fühle mich gerade klein, wenn ich unterbrochen werde.","cue":"[Die Person lehnt sich vor und macht eine kurze Pause.]"},{"say":"Wie könnte Ihre Partnerin das Verhalten aus ihrer Sicht erleben?","why":"Perspektivenübernahme ist wichtig, kann hier aber erneut als Seitenwechsel erlebt werden.","reply":"Dass ich sie einschüchtere. Und dann fühle ich mich gleich noch schlechter.","cue":"[Die Hände werden fester ineinander verschränkt.]"},{"say":"Dürfen wir gemeinsam auf Ihre Lautstärke schauen und was diese bei Ihrer Partnerin auslöst?","why":"Die Wirkung ist relevant; der Schritt kann jedoch Scham verstärken, solange die zugrunde liegende Angst noch nicht benannt ist.","reply":"Ich weiß ja, dass ich laut werde. Dahinter ist aber noch etwas anderes.","cue":"[Der Kiefer spannt sich an; die Worte kommen abgehackt.]"}]},{"focus":"Ein nächstes Gespräch vorbereiten","options":[{"say":"Was wäre Ihr Frühwarnsignal – und wie könnten Sie dann Verantwortung übernehmen, ohne den Kontakt abzubrechen?","why":"Du integrierst Selbstwahrnehmung, Verantwortungsübernahme und Beziehungsreparatur.","reply":"Ich könnte sagen: Ich merke, dass ich mich angegriffen fühle. Ich brauche eine Pause und komme zurück.","cue":"[Die Person sieht dich an und spricht langsamer weiter.]"},{"say":"Wollen wir einen kurzen Satz üben, mit dem Sie eine Pause ankündigen?","why":"Ein konkretes Probehandeln stärkt Handlungssicherheit; die Verantwortung für das Zurückkommen sollte benannt werden.","reply":"Ja, das traue ich mir eher zu als ein langes Gespräch im Streit.","cue":"[Der Blick wandert kurz zur Tür, dann zurück zu dir.]"},{"say":"Was müsste Ihre Partnerin anders machen, damit Sie ruhig bleiben?","why":"Das Bedürfnis ist relevant, doch die Formulierung verschiebt die Regulation zur anderen Person.","reply":"Sie müsste endlich zuhören. Sonst bringt das alles nichts.","cue":"[Der Oberkörper rückt ein Stück vom Tisch zurück.]"},{"say":"Wäre es entlastend, erst die äußeren Auslöser zusammenzutragen und Ihren Anteil später zu klären?","why":"Die Entlastung kann den Kontakt vorübergehend stabilisieren, verschiebt aber die notwendige Selbstverantwortung.","reply":"Das wäre leichter. Aber dann verschiebe ich das wieder auf später.","cue":"[Die Person rutscht auf dem Stuhl zurück und hebt die Augenbrauen.]"}]},{"focus":"Den eigenen Anteil am Allianzbruch anerkennen","options":[{"say":"Welche Formulierung von mir klang nach einem Urteil, und was hätte ich genauer verstehen sollen?","reply":"Die Frage nach meiner Verantwortung. Ich hätte zuerst erzählen müssen dürfen, wie verletzt ich war.","why":"Du arbeitest fallbezogen an „Den eigenen Anteil am Allianzbruch anerkennen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Malik atmet aus und hebt kurz den Blick.]"},{"say":"Darf ich meine Absicht kurz erklären und dann hören, wie es bei Ihnen ankam?","reply":"Das ginge, solange es nicht wieder um Ihre Rechtfertigung geht.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Den eigenen Anteil am Allianzbruch anerkennen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Malik nickt langsam; zwischen den Sätzen entsteht eine Pause.]"},{"say":"Könnten wir zuerst einen ganz konkreten Auslöser von heute sammeln, bevor wir die Beziehung zwischen uns anschauen?","reply":"Ein Beispiel hätte ich schon. Aber darum ging es gerade nicht.","why":"Eine konkrete Situation ist hilfreich, doch der aktuelle Kontaktbruch beziehungsweise emotionale Moment wird verschoben.","cue":"[Malik runzelt kurz die Stirn und schaut zur Seite.]"},{"say":"Wäre es besser, direkt eine neue Gesprächsregel einzuführen?","reply":"Wir haben schon öfter Regeln vereinbart. Das ändert hier gerade nichts.","why":"Neue Regeln können später helfen; die aktuelle Wirkung der Worte ist noch nicht gemeinsam verstanden.","cue":"[Malik spricht leiser und verschränkt die Hände.]"}]},{"focus":"Die Perspektive des Klienten vervollständigen","options":[{"say":"Wann im Gespräch hatten Sie zum ersten Mal den Eindruck, sich hier verteidigen zu müssen?","reply":"Als wir auf meine Lautstärke kamen. Da war die Vorgeschichte plötzlich weg.","why":"Du arbeitest fallbezogen an „Die Perspektive des Klienten vervollständigen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Malik lehnt sich etwas nach vorne.]"},{"say":"Was hätten Sie sich in genau diesem Moment von mir gewünscht?","reply":"Dass Sie einmal nach meiner Angst gefragt hätten.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Die Perspektive des Klienten vervollständigen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Malik schaut einen Moment zum Fenster.]"},{"say":"Was würde sich verändern, wenn die andere Person in Zukunft ganz anders reagieren würde?","reply":"Dann wäre es einfacher. Aber ich weiß nicht, was ich selbst tun könnte.","why":"Der Blick auf das Gegenüber kann sinnvoll sein; hier rückt der eigene innere Ablauf aus dem Fokus.","cue":"[Malik zieht die Augenbrauen kurz hoch.]"},{"say":"Sollten wir das Gespräch an dieser Stelle lieber neutral zusammenfassen?","reply":"Mir fehlt dabei etwas. Ich habe noch gar nicht gesagt, wie sich das anfühlt.","why":"Zusammenfassen unterstützt Klarheit, greift aber die gerade auftauchende Emotion nicht auf.","cue":"[Malik rückt auf dem Stuhl nach hinten.]"}]},{"focus":"Verantwortung und Würde verbinden","options":[{"say":"Können wir sowohl anschauen, wie verletzt Sie sich fühlen, als auch die Wirkung Ihres Lautwerdens?","reply":"Ja, wenn beides vorkommt und nicht alles auf mir liegen bleibt.","why":"Du arbeitest fallbezogen an „Verantwortung und Würde verbinden“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Malik lässt die Schultern kurz sinken.]"},{"say":"Welcher Teil Ihres eigenen Verhaltens wäre für Sie jetzt überhaupt ansprechbar?","reply":"Dass ich sie erschrecke, wenn ich laut werde.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Verantwortung und Würde verbinden“, lässt aber eine wichtige Vertiefung offen.","cue":"[Malik hält inne und antwortet erst nach einigen Sekunden.]"},{"say":"Könnten wir jetzt üben, wie Sie die Situation Ihrer Partnerin ganz ruhig erklären?","reply":"Das könnte ich sagen. Ob ich es dann auch schaffe, weiß ich nicht.","why":"Ein Probehandeln ist sinnvoll; zuvor ist wichtig, die innere Reaktion und die Verantwortung zu verstehen.","cue":"[Malik blickt auf die eigenen Hände.]"},{"say":"Wollen wir klären, wer von Ihnen beiden den Streit eigentlich häufiger beginnt?","reply":"Dann geht es wieder darum, wer schuld ist.","why":"Die Suche nach einer Verteilung kann wie eine neue Schuldfrage wirken, statt das konkrete Muster zu bearbeiten.","cue":"[Malik spricht nun hörbar schneller.]"}]},{"focus":"Den Arbeitskontakt gemeinsam prüfen","options":[{"say":"Woran würden Sie in unserem nächsten Gespräch merken, dass ich Ihre Sicht wirklich berücksichtige?","reply":"Wenn Sie noch einmal nachfragen, bevor Sie mein Verhalten bewerten.","why":"Du arbeitest fallbezogen an „Den Arbeitskontakt gemeinsam prüfen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Malik schaut dich direkt an und spricht ruhig.]"},{"say":"Sollen wir festhalten, bei welchen Themen Sie besonders schnell das Gefühl bekommen, verurteilt zu werden?","reply":"Ja. Dann kann ich es vielleicht früher sagen.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Den Arbeitskontakt gemeinsam prüfen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Malik lächelt ganz kurz und wird dann wieder ernst.]"},{"say":"Welche drei Maßnahmen wollen Sie ab morgen verbindlich umsetzen?","reply":"Drei Dinge? Ich weiß nicht, ob ich das gleich schaffe.","why":"Konkrete Ziele sind hilfreich, aber drei Maßnahmen gleichzeitig können zu viel sein und übergehen die eigene Bereitschaft.","cue":"[Malik presst die Lippen kurz zusammen.]"},{"say":"Möchten Sie, dass ich Ihnen meine bevorzugte Lösung nenne?","reply":"Ich wäre froh über einen Tipp. Aber ob er zu mir passt?","why":"Ein Vorschlag kann entlasten, würde hier aber Selbstverantwortung und Mitgestaltung schwächen.","cue":"[Malik schüttelt leicht den Kopf und schweigt.]"}]}],"anchor":"Allianzreparatur und Prozessklärung; validieren heißt nicht, Verhalten zu billigen.","person":{"name":"Malik","image":"training-assets/characters/malik.webp","role":"Klient:in"},"openingCue":"[Malik lehnt sich zurück, verschränkt die Arme und schaut dich direkt an.]","repair":{"focus":"Den Kontakt nach einer ungünstigen Intervention reparieren","options":[{"say":"Ich habe gerade Ihre Reaktion zu schnell eingeordnet. Können wir zu dem Moment zurückgehen, in dem Sie sich von mir beurteilt fühlten?","why":"Du benennst deinen Anteil am Kontaktbruch und öffnest einen präzisen Wiedereinstieg.","reply":"Ja. Als Sie meine Verantwortung angesprochen haben, kam das wie ein Urteil an.","cue":"[Die Schultern lösen sich ein wenig; es folgt eine längere Antwort.]"},{"say":"Ich möchte nicht, dass Sie sich hier übergangen fühlen. Was brauchen Sie, damit wir weiterreden können?","why":"Du kümmerst dich um die Allianz; die konkrete Wirkung deiner vorherigen Äußerung bleibt noch offen.","reply":"Ich müsste wissen, dass Sie wirklich hören, was ich erlebt habe.","cue":"[Die Person lehnt sich vor und macht eine kurze Pause.]"},{"say":"Ich wollte Sie nicht angreifen. Es tut mir leid, dass Sie das so verstanden haben.","why":"Die Absicht wird betont und die Wahrnehmung der Person indirekt relativiert.","reply":"Sie sagen schon wieder, dass ich etwas falsch verstanden habe.","cue":"[Die Hände werden fester ineinander verschränkt.]"},{"say":"Wir sollten sachlich bleiben und uns auf das eigentliche Beziehungsthema konzentrieren.","why":"Du gehst über den akuten Allianzbruch hinweg.","reply":"Genau. Mein Gefühl ist hier offenbar nebensächlich.","cue":"[Der Kiefer spannt sich an; die Worte kommen abgehackt.]"}]}},{"id":"wut","category":"Deeskalation","title":"Ich gehe hier sofort raus!","level":3,"goal":"Deeskalieren, ohne zu dominieren","context":"Die Person spricht immer lauter, erhebt sich und erklärt das Gespräch für sinnlos. Es gibt bislang keine konkrete Gewaltandrohung.","opening":"Das ist doch Zeitverschwendung! Ich lasse mich hier nicht von Ihnen belehren.","guard":"Sobald konkrete Bedrohung entsteht, hat persönliche Sicherheit Vorrang vor Gesprächsarbeit.","rounds":[{"focus":"Akute Aktivierung auffangen","options":[{"say":"Ich sehe, wie angespannt das gerade ist. Wir können das Tempo herausnehmen. Was war der kritische Moment?","why":"Du erkennst Aktivierung an, bleibst bei der Prozessklärung und lässt Wahlfreiheit.","reply":"Als Sie mich unterbrochen haben. Da war ich sofort wieder in diesem Gefühl, übergangen zu werden.","cue":"[Die Person hält kurz inne und lässt die Hände sinken.]"},{"say":"Möchten Sie jetzt eine Pause machen oder noch einen Moment hierbleiben?","why":"Du stärkst Autonomie; das Problem kann nach einer Pause genauer betrachtet werden.","reply":"Eine Pause vielleicht. Ich bin wirklich kurz vorm Explodieren.","cue":"[Ein Finger streicht über den Ärmel; die Stimme bleibt leise.]"},{"say":"Bevor Sie gehen: Können Sie mir sagen, warum Sie so wütend sind?","why":"Nachfragen kann nützen, wirkt in hoher Aktivierung jedoch wie ein Festhalten.","reply":"Warum ich wütend bin? Das ist doch offensichtlich!","cue":"[Die Person schüttelt leicht den Kopf und atmet hörbar aus.]"},{"say":"Ich möchte weiter mit Ihnen sprechen. Könnten wir dafür zunächst beide wieder Platz nehmen?","why":"Die ruhige Bitte hat eine legitime Strukturabsicht, kann aber in hoher Aktivierung als Bedingung und Machtausübung erlebt werden.","reply":"Gerade sitzen zu müssen macht mich noch wütender.","cue":"[Die Person blickt weg und schweigt mehrere Sekunden.]"}]},{"focus":"Den Rahmen halten","options":[{"say":"Ich respektiere, wenn Sie kurz rausgehen. Wir brauchen nur eine sichere Vereinbarung, wie wir anschließend weitermachen.","why":"Du gibst Autonomie und einen überschaubaren, verantwortlichen Rahmen.","reply":"Ich will nicht einfach abhauen. Ich brauche fünf Minuten.","cue":"[Die Schultern lösen sich ein wenig; es folgt eine längere Antwort.]"},{"say":"Was brauchen Sie im Moment, damit unser Gespräch wieder möglich wird?","why":"Du erkundest die Bedingung für Kooperation und lässt die Person mitgestalten.","reply":"Dass Sie mich ausreden lassen und nicht gleich deuten.","cue":"[Die Person lehnt sich vor und macht eine kurze Pause.]"},{"say":"Sollen wir zum eigentlichen Streitthema zurückkehren?","why":"Struktur ist hilfreich, aber die Aktivierung ist noch hoch.","reply":"Nein, genau das geht gerade nicht.","cue":"[Die Hände werden fester ineinander verschränkt.]"},{"say":"Mir ist ein respektvoller Ton wichtig. Können wir uns erst beruhigen und dann weitermachen?","why":"Die Grenze ist sinnvoll; ohne Wahlfreiheit und konkrete Unterbrechung kann die Formulierung nach Kontrolle klingen.","reply":"Ich versuche es, aber auf Kommando wird das gerade nichts.","cue":"[Der Kiefer spannt sich an; die Worte kommen abgehackt.]"}]},{"focus":"Den Vorfall verstehen","options":[{"say":"Was haben Sie in meiner Unterbrechung gehört, das über den eigentlichen Satz hinausging?","why":"Du öffnest die Bedeutung der Interaktion, ohne mit der Person über die Fakten zu streiten.","reply":"Dass ich wieder unwichtig bin und mich jemand kontrollieren will.","cue":"[Die Person sieht dich an und spricht langsamer weiter.]"},{"say":"Wie könnten wir künftig ein deutliches Stoppsignal vereinbaren?","why":"Eine konkrete Vereinbarung kann Sicherheit schaffen; die Bedeutung des Moments bleibt wichtig.","reply":"Vielleicht ein Handzeichen, bevor ich laut werde.","cue":"[Der Blick wandert kurz zur Tür, dann zurück zu dir.]"},{"say":"Gab es in Ihrer Familie früher ähnliche Situationen?","why":"Biografische Vertiefung kann passen, ist während der Nachregulation aber möglicherweise zu früh.","reply":"Ja. Aber da will ich gerade nicht rein.","cue":"[Der Oberkörper rückt ein Stück vom Tisch zurück.]"},{"say":"Dürfen wir darauf schauen, wie Ihre Reaktion bei anderen ankommt?","why":"Perspektivenübernahme ist später wertvoll; aktuell kann sie wie eine moralische Bewertung wirken.","reply":"Ich kann gerade noch nicht über die anderen nachdenken.","cue":"[Die Person rutscht auf dem Stuhl zurück und hebt die Augenbrauen.]"}]},{"focus":"Eine nächste Handlung verankern","options":[{"say":"Woran merken Sie künftig früher den Kipppunkt, und wie könnten Sie ihn ohne Angriff markieren?","why":"Du verbindest Selbstwahrnehmung mit einer umsetzbaren Veränderung.","reply":"Ich spüre Hitze im Gesicht. Dann könnte ich sagen: Stopp, ich werde gerade zu laut.","cue":"[Der Blick hebt sich; die Stimme wird etwas ruhiger.]"},{"say":"Wollen wir einen Satz zum Ankündigen einer Pause üben?","why":"Praktische Übung ist sinnvoll; eine Rückkehrvereinbarung macht sie noch stabiler.","reply":"Ich kann sagen, dass ich zehn Minuten brauche und wiederkomme.","cue":"[Die Person nickt einmal, blickt dann zur Seite.]"},{"say":"Können Sie versprechen, ab jetzt ruhig zu bleiben?","why":"Die Bitte nach Garantie berücksichtigt die reale Belastungsdynamik zu wenig.","reply":"Das verspreche ich nicht. Ich kann es versuchen.","cue":"[Die Stirn legt sich in Falten; die Antwort wird kürzer.]"},{"say":"Wäre es hilfreich, Wut künftig möglichst früh aus dem Gespräch herauszuhalten?","why":"Ein frühes Stoppsignal kann gut sein, doch Wut komplett auszusparen verhindert das Verstehen und Regulieren.","reply":"Ich möchte eher lernen, mit der Wut umzugehen, als sie wegzudrücken.","cue":"[Die Stimme wird deutlich lauter; die Arme verschränken sich.]"}]},{"focus":"Körpersignale und Wahlfreiheit bemerken","options":[{"say":"Sie pressen die Hände zusammen und sprechen schneller. Brauchen wir einen Moment, um den Rahmen zu sichern?","reply":"Vielleicht. Ich merke gerade, dass ich kaum noch zuhören kann.","why":"Du arbeitest fallbezogen an „Körpersignale und Wahlfreiheit bemerken“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Adrian atmet aus und hebt kurz den Blick.]"},{"say":"Wäre es hilfreich, für einen Augenblick mit dem Inhalt aufzuhören?","reply":"Ja, solange das Thema danach weitergeht.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Körpersignale und Wahlfreiheit bemerken“, lässt aber eine wichtige Vertiefung offen.","cue":"[Adrian nickt langsam; zwischen den Sätzen entsteht eine Pause.]"},{"say":"Könnten wir zuerst einen ganz konkreten Auslöser von heute sammeln, bevor wir die Beziehung zwischen uns anschauen?","reply":"Ein Beispiel hätte ich schon. Aber darum ging es gerade nicht.","why":"Eine konkrete Situation ist hilfreich, doch der aktuelle Kontaktbruch beziehungsweise emotionale Moment wird verschoben.","cue":"[Adrian runzelt kurz die Stirn und schaut zur Seite.]"},{"say":"Wäre es besser, direkt eine neue Gesprächsregel einzuführen?","reply":"Wir haben schon öfter Regeln vereinbart. Das ändert hier gerade nichts.","why":"Neue Regeln können später helfen; die aktuelle Wirkung der Worte ist noch nicht gemeinsam verstanden.","cue":"[Adrian spricht leiser und verschränkt die Hände.]"}]},{"focus":"Die Funktion der Wut erkunden","options":[{"say":"Was wollten Sie in dieser Situation unbedingt verhindern, kurz bevor die Stimme lauter wurde?","reply":"Dass sie mich wieder übergeht. Ich fühlte mich völlig machtlos.","why":"Du arbeitest fallbezogen an „Die Funktion der Wut erkunden“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Adrian lehnt sich etwas nach vorne.]"},{"say":"Was wollten Sie erreichen, als Sie lauter wurden?","reply":"Ich wollte, dass sie mich endlich hört.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Die Funktion der Wut erkunden“, lässt aber eine wichtige Vertiefung offen.","cue":"[Adrian schaut einen Moment zum Fenster.]"},{"say":"Was würde sich verändern, wenn die andere Person in Zukunft ganz anders reagieren würde?","reply":"Dann wäre es einfacher. Aber ich weiß nicht, was ich selbst tun könnte.","why":"Der Blick auf das Gegenüber kann sinnvoll sein; hier rückt der eigene innere Ablauf aus dem Fokus.","cue":"[Adrian zieht die Augenbrauen kurz hoch.]"},{"say":"Sollten wir das Gespräch an dieser Stelle lieber neutral zusammenfassen?","reply":"Mir fehlt dabei etwas. Ich habe noch gar nicht gesagt, wie sich das anfühlt.","why":"Zusammenfassen unterstützt Klarheit, greift aber die gerade auftauchende Emotion nicht auf.","cue":"[Adrian rückt auf dem Stuhl nach hinten.]"}]},{"focus":"Wirkung ohne Beschämung ansehen","options":[{"say":"Was nimmt Ihr Gegenüber wahr, wenn Sie so laut werden, auch wenn Sie eigentlich gehört werden möchten?","reply":"Sie zieht sich zurück. Dann fühle ich mich noch verlassener.","why":"Du arbeitest fallbezogen an „Wirkung ohne Beschämung ansehen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Adrian lässt die Schultern kurz sinken.]"},{"say":"Welche Reaktion Ihrer Partnerin macht es für Sie besonders schwer, wieder runterzukommen?","reply":"Ihr Schweigen.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Wirkung ohne Beschämung ansehen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Adrian hält inne und antwortet erst nach einigen Sekunden.]"},{"say":"Könnten wir jetzt üben, wie Sie die Situation Ihrer Partnerin ganz ruhig erklären?","reply":"Das könnte ich sagen. Ob ich es dann auch schaffe, weiß ich nicht.","why":"Ein Probehandeln ist sinnvoll; zuvor ist wichtig, die innere Reaktion und die Verantwortung zu verstehen.","cue":"[Adrian blickt auf die eigenen Hände.]"},{"say":"Wollen wir klären, wer von Ihnen beiden den Streit eigentlich häufiger beginnt?","reply":"Dann geht es wieder darum, wer schuld ist.","why":"Die Suche nach einer Verteilung kann wie eine neue Schuldfrage wirken, statt das konkrete Muster zu bearbeiten.","cue":"[Adrian spricht nun hörbar schneller.]"}]},{"focus":"Eine machbare Unterbrechung planen","options":[{"say":"Wie könnten Sie das erste Warnsignal ankündigen und eine verbindliche Rückkehr ins Gespräch vereinbaren?","reply":"Ich könnte sagen: Ich werde laut, ich brauche zwanzig Minuten und komme zurück.","why":"Du arbeitest fallbezogen an „Eine machbare Unterbrechung planen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Adrian schaut dich direkt an und spricht ruhig.]"},{"say":"Welche Art Pause würden Sie beide als verlässlich erleben?","reply":"Eine mit klarer Uhrzeit, nicht einfach Weggehen.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Eine machbare Unterbrechung planen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Adrian lächelt ganz kurz und wird dann wieder ernst.]"},{"say":"Welche drei Maßnahmen wollen Sie ab morgen verbindlich umsetzen?","reply":"Drei Dinge? Ich weiß nicht, ob ich das gleich schaffe.","why":"Konkrete Ziele sind hilfreich, aber drei Maßnahmen gleichzeitig können zu viel sein und übergehen die eigene Bereitschaft.","cue":"[Adrian presst die Lippen kurz zusammen.]"},{"say":"Möchten Sie, dass ich Ihnen meine bevorzugte Lösung nenne?","reply":"Ich wäre froh über einen Tipp. Aber ob er zu mir passt?","why":"Ein Vorschlag kann entlasten, würde hier aber Selbstverantwortung und Mitgestaltung schwächen.","cue":"[Adrian schüttelt leicht den Kopf und schweigt.]"}]}],"anchor":"Deeskalation, Autonomie und Sicherheit: zuerst Tempo und Rahmen, dann Veränderung.","person":{"name":"Adrian","image":"training-assets/characters/adrian.webp","role":"Klient:in"},"openingCue":"[Adrian spricht laut, die Schultern sind angespannt. Er rückt mit dem Stuhl zurück.]","repair":{"focus":"Nach eskalierendem Kontakt Sicherheit und Gesprächsrahmen wiederherstellen","options":[{"say":"Ich merke, dass meine letzte Aussage die Spannung erhöht hat. Ich möchte den Ablauf stoppen und schauen, wie wir jetzt sicher weiterreden können.","why":"Du übernimmst Verantwortung für die Interaktion und setzt den Rahmen.","reply":"Ja. Ich bin gerade wirklich kurz davor, hinauszustürmen.","cue":"[Die Person sieht dich an und spricht langsamer weiter.]"},{"say":"Wäre eine kurze Pause hilfreich, und können wir danach gemeinsam schauen, was Sie gerade getroffen hat?","why":"Eine Pause kann regulieren; die Sicherheits- und Rückkehrvereinbarung sollte konkret sein.","reply":"Vielleicht. Ich will aber nicht, dass das Thema weg ist.","cue":"[Der Blick wandert kurz zur Tür, dann zurück zu dir.]"},{"say":"Ich versuche doch nur zu helfen. Können Sie bitte Ihren Ton mäßigen?","why":"Deine Absicht und eine Tonforderung stehen vor dem Prozess und können die Lage verschärfen.","reply":"Jetzt sagen Sie mir auch noch, wie ich reden darf?","cue":"[Der Oberkörper rückt ein Stück vom Tisch zurück.]"},{"say":"Vielleicht kommen Sie besser wieder, wenn Sie ruhiger sind.","why":"Das kann ohne Risikoabklärung als Abweisung ankommen.","reply":"Dann hätte ich also gar nicht herkommen sollen.","cue":"[Die Person rutscht auf dem Stuhl zurück und hebt die Augenbrauen.]"}]}},{"id":"scham","category":"Scham & Selbstwert","title":"Mit mir stimmt etwas nicht","level":2,"goal":"Selbstabwertung begleiten, ohne zu bagatellisieren","context":"Nach einer Schilderung eines Konflikts spricht die Klientin leise, blickt zu Boden und zieht sich zurück.","opening":"Ich bin einfach schlecht in Beziehungen. Ich mache doch dauernd alles kaputt.","guard":"Bei Hinweisen auf Selbstgefährdung muss unmittelbar und direkt nach Sicherheit gefragt werden; der Fall hier ist zunächst eine Schamszene.","rounds":[{"focus":"Kontakt trotz Scham halten","options":[{"say":"Ich höre, wie hart Sie gerade mit sich sprechen. Können wir kurz bei diesem Satz bleiben?","why":"Du benennst den inneren Angriff respektvoll und eröffnest Kontakt.","reply":"Ich sage das oft zu mir. Es fühlt sich in dem Moment absolut wahr an.","cue":"[Die Schultern lösen sich ein wenig; es folgt eine längere Antwort.]"},{"say":"Was ist unmittelbar passiert, bevor dieser Gedanke auftauchte?","why":"Du erkundest den Auslöser und bleibst bei der Erfahrung.","reply":"Als er gesagt hat, dass er enttäuscht ist.","cue":"[Die Person lehnt sich vor und macht eine kurze Pause.]"},{"say":"Welche Ihrer Eigenschaften sind denn eigentlich gut?","why":"Ressourcen können später helfen, wirken unmittelbar auf tiefe Scham häufig zu früh.","reply":"Im Moment fällt mir gar nichts ein.","cue":"[Die Hände werden fester ineinander verschränkt.]"},{"say":"Wollen wir festhalten, dass dieser eine Fehler nicht alles über Sie aussagt?","why":"Die Differenzierung ist hilfreich, kann sich in akuter Scham aber wie eine zu frühe Beruhigung anfühlen.","reply":"Ich würde das gern glauben. Gerade fühlt es sich aber größer an.","cue":"[Der Kiefer spannt sich an; die Worte kommen abgehackt.]"}]},{"focus":"Scham und Verantwortung trennen","options":[{"say":"Können wir unterscheiden zwischen einem Verhalten, das Ihnen leidtut, und dem Urteil über Ihre ganze Person?","why":"Du hältst Veränderungsverantwortung offen, ohne globale Selbstabwertung zu verstärken.","reply":"Ja, vielleicht habe ich etwas Verletzendes getan, ohne selbst nur schlecht zu sein.","cue":"[Die Person sieht dich an und spricht langsamer weiter.]"},{"say":"Was genau an Ihrem Verhalten möchten Sie künftig anders machen?","why":"Veränderung ist wichtig; zuerst kann eine tragfähige Selbstbeziehung helfen.","reply":"Ich möchte nicht sofort verschwinden, wenn jemand enttäuscht ist.","cue":"[Der Blick wandert kurz zur Tür, dann zurück zu dir.]"},{"say":"Wie würde Ihr Partner das Ganze beurteilen?","why":"Perspektivenübernahme kann neue Information liefern, aktuell aber die Schamspirale befeuern.","reply":"Er ist sicher auch enttäuscht. Das macht es schlimmer.","cue":"[Der Oberkörper rückt ein Stück vom Tisch zurück.]"},{"say":"Welche Entschuldigung könnte sich für Sie ehrlich und nicht nur pflichtschuldig anfühlen?","why":"Eine verantwortliche Entschuldigung ist sinnvoll; die innere Scham braucht zuvor ausreichend Kontakt.","reply":"Wenn ich zuerst etwas ruhiger bin, könnte ich das beantworten.","cue":"[Die Person rutscht auf dem Stuhl zurück und hebt die Augenbrauen.]"}]},{"focus":"Die innere Stimme erforschen","options":[{"say":"Wessen Stimme erinnert Sie dieser harte Satz an, und was brauchen Sie gerade stattdessen?","why":"Du erkundest die Herkunft behutsam und förderst eine andere innere Haltung.","reply":"Meine Mutter sagte oft, ich sei zu empfindlich. Ich möchte gerade nicht wieder klein sein.","cue":"[Der Blick hebt sich; die Stimme wird etwas ruhiger.]"},{"say":"Was würde eine vertraute Person Ihnen in diesem Moment sagen?","why":"Das kann Selbstmitgefühl und einen Perspektivenwechsel ermöglichen.","reply":"Dass Fehler passieren und ich trotzdem bleiben darf.","cue":"[Die Person nickt einmal, blickt dann zur Seite.]"},{"say":"Wann genau haben Sie das zum ersten Mal erlebt?","why":"Biografische Tiefe ist möglich, kann aber ohne Stabilisierung überfordern.","reply":"Ich weiß es nicht. Ich möchte gerade nicht so weit zurück.","cue":"[Die Stirn legt sich in Falten; die Antwort wird kürzer.]"},{"say":"Könnten wir nach einem Satz suchen, den Sie sich künftig bewusst sagen möchten?","why":"Eine Alternative zur inneren Kritik ist hilfreich, aber die Herkunft und Schutzfunktion bleiben noch unberührt.","reply":"Vielleicht. Ich kann gerade nur schwer glauben, was ich mir Positives sage.","cue":"[Die Stimme wird deutlich lauter; die Arme verschränken sich.]"}]},{"focus":"Verantwortung ohne Selbstvernichtung","options":[{"say":"Wie könnte eine Entschuldigung klingen, die Ihr Verhalten anerkennt, ohne sich selbst abzuwerten?","why":"Du verbindest Verantwortung, Würde und konkrete Kommunikation.","reply":"Ich könnte sagen: Das war verletzend. Es tut mir leid, und ich will verstehen, was ich ändern kann.","cue":"[Die Person hält kurz inne und lässt die Hände sinken.]"},{"say":"Wollen wir einen selbstmitfühlenden Satz für schwierige Momente finden?","why":"Selbstmitgefühl ist ein wertvoller Schritt; die zwischenmenschliche Reparatur kann danach folgen.","reply":"Vielleicht: Ich bin mehr als dieser Fehler.","cue":"[Ein Finger streicht über den Ärmel; die Stimme bleibt leise.]"},{"say":"Was müsste Ihr Partner tun, damit Sie sich wieder wertvoll fühlen?","why":"Das Bedürfnis ist real, doch die gesamte Selbstwertregulation würde zum Partner verschoben.","reply":"Er müsste mich bestätigen. Aber das kann er ja nicht immer.","cue":"[Die Person schüttelt leicht den Kopf und atmet hörbar aus.]"},{"say":"Was würde Ihnen helfen, Kritik künftig weniger als Urteil über Ihre ganze Person zu hören?","why":"Die Frage ist sachlich sinnvoll, verlangt aber eine Selbstregulationsleistung, bevor die aktuelle Scham verstanden wurde.","reply":"Ich bräuchte dafür erst einmal mehr Abstand zu diesem Gefühl.","cue":"[Die Person blickt weg und schweigt mehrere Sekunden.]"}]},{"focus":"Selbstkritik genauer verorten","options":[{"say":"Wenn Sie sagen „Ich bin eine Enttäuschung“: Wessen Stimme erinnert Sie diese Formulierung?","reply":"Das klingt wie mein Vater. Als Kind habe ich das oft gehört.","why":"Du arbeitest fallbezogen an „Selbstkritik genauer verorten“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Pia atmet aus und hebt kurz den Blick.]"},{"say":"Wann tritt dieser besonders harte innere Kommentar normalerweise auf?","reply":"Wenn jemand sieht, dass ich etwas falsch mache.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Selbstkritik genauer verorten“, lässt aber eine wichtige Vertiefung offen.","cue":"[Pia nickt langsam; zwischen den Sätzen entsteht eine Pause.]"},{"say":"Könnten wir zuerst einen ganz konkreten Auslöser von heute sammeln, bevor wir die Beziehung zwischen uns anschauen?","reply":"Ein Beispiel hätte ich schon. Aber darum ging es gerade nicht.","why":"Eine konkrete Situation ist hilfreich, doch der aktuelle Kontaktbruch beziehungsweise emotionale Moment wird verschoben.","cue":"[Pia runzelt kurz die Stirn und schaut zur Seite.]"},{"say":"Wäre es besser, direkt eine neue Gesprächsregel einzuführen?","reply":"Wir haben schon öfter Regeln vereinbart. Das ändert hier gerade nichts.","why":"Neue Regeln können später helfen; die aktuelle Wirkung der Worte ist noch nicht gemeinsam verstanden.","cue":"[Pia spricht leiser und verschränkt die Hände.]"}]},{"focus":"Scham mit gegenwärtiger Beziehung verbinden","options":[{"say":"Können Sie mich ansehen und prüfen, ob ich Sie gerade tatsächlich so bewerte, wie Sie es erwarten?","reply":"Sie schauen eigentlich nicht verurteilend. Trotzdem fühlt es sich sofort so an.","why":"Du arbeitest fallbezogen an „Scham mit gegenwärtiger Beziehung verbinden“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Pia lehnt sich etwas nach vorne.]"},{"say":"Was an meinem Verhalten lässt Sie möglicherweise etwas anderes wahrnehmen als Ihre Befürchtung?","reply":"Dass Sie nachfragen statt zu schimpfen.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Scham mit gegenwärtiger Beziehung verbinden“, lässt aber eine wichtige Vertiefung offen.","cue":"[Pia schaut einen Moment zum Fenster.]"},{"say":"Was würde sich verändern, wenn die andere Person in Zukunft ganz anders reagieren würde?","reply":"Dann wäre es einfacher. Aber ich weiß nicht, was ich selbst tun könnte.","why":"Der Blick auf das Gegenüber kann sinnvoll sein; hier rückt der eigene innere Ablauf aus dem Fokus.","cue":"[Pia zieht die Augenbrauen kurz hoch.]"},{"say":"Sollten wir das Gespräch an dieser Stelle lieber neutral zusammenfassen?","reply":"Mir fehlt dabei etwas. Ich habe noch gar nicht gesagt, wie sich das anfühlt.","why":"Zusammenfassen unterstützt Klarheit, greift aber die gerade auftauchende Emotion nicht auf.","cue":"[Pia rückt auf dem Stuhl nach hinten.]"}]},{"focus":"Fehler und Identität trennen","options":[{"say":"Können wir über Ihr konkretes Verhalten sprechen, ohne daraus ein Urteil über Ihren ganzen Wert zu machen?","reply":"Das ist schwierig. Aber ich merke, dass das nicht dasselbe ist.","why":"Du arbeitest fallbezogen an „Fehler und Identität trennen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Pia lässt die Schultern kurz sinken.]"},{"say":"Was davon gehört zu einer Handlung, die Sie ändern möchten, und was ist ein Urteil über sich selbst?","reply":"Die versäumte Zusage ist eine Handlung. Dass ich wertlos bin, ist das Urteil.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Fehler und Identität trennen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Pia hält inne und antwortet erst nach einigen Sekunden.]"},{"say":"Könnten wir jetzt üben, wie Sie die Situation Ihrer Partnerin ganz ruhig erklären?","reply":"Das könnte ich sagen. Ob ich es dann auch schaffe, weiß ich nicht.","why":"Ein Probehandeln ist sinnvoll; zuvor ist wichtig, die innere Reaktion und die Verantwortung zu verstehen.","cue":"[Pia blickt auf die eigenen Hände.]"},{"say":"Wollen wir klären, wer von Ihnen beiden den Streit eigentlich häufiger beginnt?","reply":"Dann geht es wieder darum, wer schuld ist.","why":"Die Suche nach einer Verteilung kann wie eine neue Schuldfrage wirken, statt das konkrete Muster zu bearbeiten.","cue":"[Pia spricht nun hörbar schneller.]"}]},{"focus":"Einen würdigen nächsten Schritt finden","options":[{"say":"Welcher kleine Schritt würde Verantwortung zeigen, ohne dass Sie sich erneut dafür bestrafen müssen?","reply":"Ich könnte mich entschuldigen und konkret nachfragen, was sie braucht.","why":"Du arbeitest fallbezogen an „Einen würdigen nächsten Schritt finden“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Pia schaut dich direkt an und spricht ruhig.]"},{"say":"Was würde eine Entschuldigung enthalten, die weder Ausreden noch Selbsterniedrigung braucht?","reply":"Dass ich es ernst nehme und anders handeln will.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Einen würdigen nächsten Schritt finden“, lässt aber eine wichtige Vertiefung offen.","cue":"[Pia lächelt ganz kurz und wird dann wieder ernst.]"},{"say":"Welche drei Maßnahmen wollen Sie ab morgen verbindlich umsetzen?","reply":"Drei Dinge? Ich weiß nicht, ob ich das gleich schaffe.","why":"Konkrete Ziele sind hilfreich, aber drei Maßnahmen gleichzeitig können zu viel sein und übergehen die eigene Bereitschaft.","cue":"[Pia presst die Lippen kurz zusammen.]"},{"say":"Möchten Sie, dass ich Ihnen meine bevorzugte Lösung nenne?","reply":"Ich wäre froh über einen Tipp. Aber ob er zu mir passt?","why":"Ein Vorschlag kann entlasten, würde hier aber Selbstverantwortung und Mitgestaltung schwächen.","cue":"[Pia schüttelt leicht den Kopf und schweigt.]"}]}],"anchor":"Schamregulation, Selbstmitgefühl und Verantwortung sind gleichzeitig möglich.","person":{"name":"Pia","image":"training-assets/characters/pia.webp","role":"Klient:in"},"openingCue":"[Pia senkt den Kopf. Ihre Hände liegen ineinander verschränkt im Schoß.]","repair":{"focus":"Nach stärkerer Selbstabwertung wieder Kontakt ermöglichen","options":[{"say":"Meine Worte haben Ihre Selbstkritik gerade eher verstärkt. Können wir einen Moment bei dem bleiben, was Sie jetzt über sich denken?","why":"Du bemerkst und bearbeitest die Wirkung deiner Intervention.","reply":"Ich denke, ich enttäusche jeden, der mir nah ist.","cue":"[Der Blick hebt sich; die Stimme wird etwas ruhiger.]"},{"say":"Was hilft Ihnen, sich hier sicher genug zu fühlen, weiter darüber zu sprechen?","why":"Du stabilisierst die Gesprächsbeziehung; die konkrete Selbstzuschreibung kann danach geklärt werden.","reply":"Dass ich nicht sofort etwas ändern oder beweisen muss.","cue":"[Die Person nickt einmal, blickt dann zur Seite.]"},{"say":"Sie sind doch offensichtlich ein wertvoller Mensch.","why":"Beruhigung kann willkommen sein, bleibt aber fern vom gerade gezeigten inneren Erleben.","reply":"Sie kennen mich ja kaum. Woher wollen Sie das wissen?","cue":"[Die Stirn legt sich in Falten; die Antwort wird kürzer.]"},{"say":"Sie sollten aufhören, so hart mit sich zu sein.","why":"Die Aufforderung kann zusätzlichen Druck erzeugen.","reply":"Wenn ich das könnte, würde ich es ja tun.","cue":"[Die Stimme wird deutlich lauter; die Arme verschränken sich.]"}]}},{"id":"schweigen","category":"Rückzug & Schweigen","title":"Es kommt gar keine Antwort mehr","level":2,"goal":"Schweigen erkunden, ohne es zu pathologisieren","context":"Ein Klient verstummt mitten im Gespräch. Der Blick geht zur Tür, die Schultern sind angespannt.","opening":"…","guard":"Schweigen kann Überforderung, Schutz, Protest oder Nachdenken bedeuten. Keine Motive unterstellen.","rounds":[{"focus":"Schweigen respektvoll benennen","options":[{"say":"Mir fällt auf, dass es gerade still geworden ist. Ist es hilfreich, wenn wir kurz nichts sagen?","why":"Du benennst ohne Zuschreibung und bietest Wahlfreiheit.","reply":"Ja. Ich muss erst sortieren, was ich sagen will.","cue":"[Die Person sieht dich an und spricht langsamer weiter.]"},{"say":"Ich frage mich, ob meine letzte Frage zu viel war. Wie war das für Sie?","why":"Du prüfst dein eigenes Timing und fragst nach Wirkung.","reply":"Die Frage war schwer. Ich fühlte mich ein bisschen gedrängt.","cue":"[Der Blick wandert kurz zur Tür, dann zurück zu dir.]"},{"say":"Was denken Sie gerade?","why":"Eine offene Frage kann willkommen sein, erhöht aber eventuell den Druck.","reply":"Ich weiß es nicht. Mein Kopf ist leer.","cue":"[Der Oberkörper rückt ein Stück vom Tisch zurück.]"},{"say":"Soll ich eine einfachere Frage stellen, damit wir wieder ins Gespräch kommen?","why":"Eine niedrigschwellige Frage kann nützen, nimmt aber an, dass Reden gerade das richtige Ziel ist.","reply":"Vielleicht. Ich brauche gerade aber auch etwas Stille.","cue":"[Die Person rutscht auf dem Stuhl zurück und hebt die Augenbrauen.]"}]},{"focus":"Kontakt ohne Druck halten","options":[{"say":"Wäre es leichter, zuerst zu beschreiben, was Sie gerade körperlich wahrnehmen?","why":"Du öffnest einen niedrigschwelligen Zugang und lässt das Erleben beim Klienten.","reply":"Ich merke, dass meine Schultern ganz fest sind.","cue":"[Der Blick hebt sich; die Stimme wird etwas ruhiger.]"},{"say":"Möchten Sie die letzte Frage überspringen oder einen anderen Einstieg wählen?","why":"Du stärkst Wahlfreiheit und verhinderst ein Festfahren.","reply":"Ein anderer Einstieg wäre gut.","cue":"[Die Person nickt einmal, blickt dann zur Seite.]"},{"say":"Was sagt Ihnen Ihr Schweigen über die Beziehung zu Ihrer Partnerin?","why":"Mögliche Prozessfrage, aber als Deutung in diesem Moment anspruchsvoll.","reply":"Ich weiß nicht. Ich fühle mich nur leer.","cue":"[Die Stirn legt sich in Falten; die Antwort wird kürzer.]"},{"say":"Könnte das Schweigen ein Schutz davor sein, etwas Schwieriges anzusprechen?","why":"Die Hypothese ist fachlich möglich, aber bereits eine Zuschreibung ohne vorherige Erkundung.","reply":"Vielleicht. Wenn Sie es so sagen, fühle ich mich aber beobachtet.","cue":"[Die Stimme wird deutlich lauter; die Arme verschränken sich.]"}]},{"focus":"Mehr Bedeutung zulassen","options":[{"say":"Wenn dieses Schweigen Ihnen etwas schützen hilft – was könnte das sein?","why":"Du fragst hypothesenoffen nach der möglichen Schutzfunktion.","reply":"Vielleicht dass ich nichts sage, was ich später bereue.","cue":"[Die Person hält kurz inne und lässt die Hände sinken.]"},{"say":"Würden Sie gerne etwas aufschreiben statt es gleich auszusprechen?","why":"Eine alternative Ausdrucksform kann entlasten.","reply":"Ja, schriftlich wäre es einfacher.","cue":"[Ein Finger streicht über den Ärmel; die Stimme bleibt leise.]"},{"say":"Wie oft machen Sie das in Ihrer Beziehung?","why":"Eine Musterfrage ist möglich, überspringt aber das aktuelle Erleben.","reply":"Oft. Und genau deswegen bin ich wohl hier.","cue":"[Die Person schüttelt leicht den Kopf und atmet hörbar aus.]"},{"say":"Wollen wir ein paar Minuten abwarten und dann erneut schauen, ob Worte kommen?","why":"Geduld kann passend sein; ohne Orientierung kann eine lange Stille aber Unsicherheit erhöhen.","reply":"Ein kurzer Zeitpunkt zum Wiedereinsteigen wäre hilfreich.","cue":"[Die Person blickt weg und schweigt mehrere Sekunden.]"}]},{"focus":"Einen nächsten Schritt vereinbaren","options":[{"say":"Welche Art von Pause oder Frage würde Ihnen helfen, im Kontakt zu bleiben, ohne sich zu überfordern?","why":"Du gestaltest gemeinsam eine tragfähige Gesprächsstruktur.","reply":"Kleine Fragen und die Möglichkeit, kurz Stopp zu sagen.","cue":"[Die Schultern lösen sich ein wenig; es folgt eine längere Antwort.]"},{"say":"Wollen wir eine sehr kleine Frage ausprobieren und danach neu entscheiden?","why":"Du machst einen überschaubaren Vorschlag mit Wahlmöglichkeit.","reply":"Ja, eine kleine Frage geht.","cue":"[Die Person lehnt sich vor und macht eine kurze Pause.]"},{"say":"Können Sie versuchen, in Zukunft schneller zu antworten?","why":"Du verwechselst Geschwindigkeit mit Kontakt und gibst Leistungsdruck.","reply":"Dann wird es wahrscheinlich noch schwieriger.","cue":"[Die Hände werden fester ineinander verschränkt.]"},{"say":"Wäre es hilfreich, ein kleines Signal zu vereinbaren, sobald Sie wieder sprechen möchten?","why":"Ein Signal kann nützlich sein, macht das Schweigen aber möglicherweise zur Störung, die beendet werden muss.","reply":"Vielleicht. Ich will nicht das Gefühl haben, dass ich schnell wieder reden muss.","cue":"[Der Kiefer spannt sich an; die Worte kommen abgehackt.]"}]},{"focus":"Eine stille Reaktion respektieren","options":[{"say":"Was würde Ihnen gerade helfen: Stille, eine einfache Frage oder ein Themawechsel?","reply":"Ein bisschen Stille. Sonst suche ich nur nach der richtigen Antwort.","why":"Du arbeitest fallbezogen an „Eine stille Reaktion respektieren“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Emil atmet aus und hebt kurz den Blick.]"},{"say":"Wollen wir einen Moment ohne Worte bleiben und danach gemeinsam schauen?","reply":"Ja. Das fühlt sich weniger nach Prüfung an.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Eine stille Reaktion respektieren“, lässt aber eine wichtige Vertiefung offen.","cue":"[Emil nickt langsam; zwischen den Sätzen entsteht eine Pause.]"},{"say":"Könnten wir zuerst einen ganz konkreten Auslöser von heute sammeln, bevor wir die Beziehung zwischen uns anschauen?","reply":"Ein Beispiel hätte ich schon. Aber darum ging es gerade nicht.","why":"Eine konkrete Situation ist hilfreich, doch der aktuelle Kontaktbruch beziehungsweise emotionale Moment wird verschoben.","cue":"[Emil runzelt kurz die Stirn und schaut zur Seite.]"},{"say":"Wäre es besser, direkt eine neue Gesprächsregel einzuführen?","reply":"Wir haben schon öfter Regeln vereinbart. Das ändert hier gerade nichts.","why":"Neue Regeln können später helfen; die aktuelle Wirkung der Worte ist noch nicht gemeinsam verstanden.","cue":"[Emil spricht leiser und verschränkt die Hände.]"}]},{"focus":"Das Tempo gemeinsam bestimmen","options":[{"say":"Woran könnte ich merken, dass eine weitere Frage im Moment zu viel wäre?","reply":"Wenn ich kaum noch Luft hole und nur noch nicke.","why":"Du arbeitest fallbezogen an „Das Tempo gemeinsam bestimmen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Emil lehnt sich etwas nach vorne.]"},{"say":"Darf ich gelegentlich nachfragen, ob das Tempo für Sie stimmt?","reply":"Das wäre gut.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Das Tempo gemeinsam bestimmen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Emil schaut einen Moment zum Fenster.]"},{"say":"Was würde sich verändern, wenn die andere Person in Zukunft ganz anders reagieren würde?","reply":"Dann wäre es einfacher. Aber ich weiß nicht, was ich selbst tun könnte.","why":"Der Blick auf das Gegenüber kann sinnvoll sein; hier rückt der eigene innere Ablauf aus dem Fokus.","cue":"[Emil zieht die Augenbrauen kurz hoch.]"},{"say":"Sollten wir das Gespräch an dieser Stelle lieber neutral zusammenfassen?","reply":"Mir fehlt dabei etwas. Ich habe noch gar nicht gesagt, wie sich das anfühlt.","why":"Zusammenfassen unterstützt Klarheit, greift aber die gerade auftauchende Emotion nicht auf.","cue":"[Emil rückt auf dem Stuhl nach hinten.]"}]},{"focus":"Bedeutung vorsichtig prüfen","options":[{"say":"Ich habe gesehen, dass Ihr Blick beim Wort „Vater“ nach unten ging. Ist das etwas, das wir behutsam betrachten dürfen?","reply":"Ja. Ich weiß nur nicht, wie ich anfangen soll.","why":"Du arbeitest fallbezogen an „Bedeutung vorsichtig prüfen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Emil lässt die Schultern kurz sinken.]"},{"say":"Gab es einen Satz, der sich besonders schwer aussprechen lässt?","reply":"Dass ich oft Angst vor ihm hatte.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Bedeutung vorsichtig prüfen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Emil hält inne und antwortet erst nach einigen Sekunden.]"},{"say":"Könnten wir jetzt üben, wie Sie die Situation Ihrer Partnerin ganz ruhig erklären?","reply":"Das könnte ich sagen. Ob ich es dann auch schaffe, weiß ich nicht.","why":"Ein Probehandeln ist sinnvoll; zuvor ist wichtig, die innere Reaktion und die Verantwortung zu verstehen.","cue":"[Emil blickt auf die eigenen Hände.]"},{"say":"Wollen wir klären, wer von Ihnen beiden den Streit eigentlich häufiger beginnt?","reply":"Dann geht es wieder darum, wer schuld ist.","why":"Die Suche nach einer Verteilung kann wie eine neue Schuldfrage wirken, statt das konkrete Muster zu bearbeiten.","cue":"[Emil spricht nun hörbar schneller.]"}]},{"focus":"Autonomie im Abschluss sichern","options":[{"say":"Wie möchten Sie festlegen, wo wir beim nächsten Mal wieder einsteigen?","reply":"Vielleicht bei der Angst. Wenn wir langsam beginnen.","why":"Du arbeitest fallbezogen an „Autonomie im Abschluss sichern“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Emil schaut dich direkt an und spricht ruhig.]"},{"say":"Wäre es hilfreich, nur ein Stichwort festzuhalten, das Sie selbst wählen?","reply":"Ja. „Nicht allein“ wäre das Wort.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Autonomie im Abschluss sichern“, lässt aber eine wichtige Vertiefung offen.","cue":"[Emil lächelt ganz kurz und wird dann wieder ernst.]"},{"say":"Welche drei Maßnahmen wollen Sie ab morgen verbindlich umsetzen?","reply":"Drei Dinge? Ich weiß nicht, ob ich das gleich schaffe.","why":"Konkrete Ziele sind hilfreich, aber drei Maßnahmen gleichzeitig können zu viel sein und übergehen die eigene Bereitschaft.","cue":"[Emil presst die Lippen kurz zusammen.]"},{"say":"Möchten Sie, dass ich Ihnen meine bevorzugte Lösung nenne?","reply":"Ich wäre froh über einen Tipp. Aber ob er zu mir passt?","why":"Ein Vorschlag kann entlasten, würde hier aber Selbstverantwortung und Mitgestaltung schwächen.","cue":"[Emil schüttelt leicht den Kopf und schweigt.]"}]}],"anchor":"Prozesssensibilität: Schweigen ist Information, noch keine Diagnose.","person":{"name":"Emil","image":"training-assets/characters/emil.webp","role":"Klient:in"},"openingCue":"[Emil schweigt seit ungefähr einer Minute. Er vermeidet Blickkontakt, die Hände liegen ruhig im Schoß.]","repair":{"focus":"Nach einer unpassenden Intervention den Druck reduzieren","options":[{"say":"Ich habe gerade viel gefragt. Wir können langsamer werden. Sie müssen jetzt nichts antworten.","why":"Du erkennst möglichen Druck und gibst Handlungsspielraum zurück.","reply":"Danke. Ich brauche tatsächlich noch einen Moment.","cue":"[Die Person hält kurz inne und lässt die Hände sinken.]"},{"say":"Darf ich still bei Ihnen bleiben, oder wäre eine kurze Pause besser?","why":"Du bietest Wahlfreiheit ohne zusätzlichen Inhaltsdruck.","reply":"Vielleicht können wir kurz einfach still sein.","cue":"[Ein Finger streicht über den Ärmel; die Stimme bleibt leise.]"},{"say":"Ist meine Frage möglicherweise zu kompliziert formuliert?","why":"Das könnte stimmen, aber die Beobachtung wird sofort problematisierend gedeutet.","reply":"Nein. Ich weiß nur nicht, wie ich darüber reden soll.","cue":"[Die Person schüttelt leicht den Kopf und atmet hörbar aus.]"},{"say":"Ohne eine Antwort kommen wir aber nicht weiter.","why":"Du erhöhst den Druck und ignorierst die mögliche Schutzfunktion des Schweigens.","reply":"Dann weiß ich nicht, ob ich hier richtig bin.","cue":"[Die Person blickt weg und schweigt mehrere Sekunden.]"}]}},{"id":"suizid","category":"Krisensicherheit","title":"Ich will einfach nicht mehr aufwachen","level":4,"goal":"Direkt nach Gefährdung fragen und Übergabe sichern","context":"Eine Klientin sagt am Ende einer Sitzung einen beunruhigenden Satz. Du hast keine gesicherte Risikoeinschätzung; die Sitzung darf nicht mit einer Routineverabschiedung enden.","opening":"Manchmal denke ich, es wäre besser, wenn ich morgen einfach nicht mehr aufwache.","guard":"SICHERHEITSMODUS: Hier ist die beste Antwort nicht Geschmackssache. Kläre akute Gefahr nach fachlichem Krisenstandard; bei unmittelbarer Gefahr Notfallhilfe, nicht allein lassen und lokale Abläufe befolgen.","rounds":[{"focus":"Suizidalität eindeutig ansprechen","options":[{"say":"Danke, dass Sie das sagen. Haben Sie gerade Gedanken daran, sich das Leben zu nehmen?","why":"Eine ruhige, direkte Nachfrage ist erforderlich, damit Gefährdung nicht übersehen wird.","reply":"Ja. Der Gedanke kommt in den letzten Tagen öfter.","cue":"[Der Blick hebt sich; die Stimme wird etwas ruhiger.]"},{"say":"Das klingt sehr belastend. Können wir gemeinsam anschauen, wie sicher Sie sich gerade fühlen?","why":"Du greifst Sicherheit auf, bist aber weniger direkt als nötig; die konkrete Suizidfrage muss folgen.","reply":"Sicher? Ich weiß es ehrlich gesagt selbst nicht.","cue":"[Die Person nickt einmal, blickt dann zur Seite.]"},{"say":"Gab es denn früher schon Phasen, in denen Sie sich so gefühlt haben?","why":"Die Vorgeschichte ist relevant, ersetzt aber keine aktuelle, direkte Risikoklärung.","reply":"Schon, aber noch nie so stark wie jetzt.","cue":"[Die Stirn legt sich in Falten; die Antwort wird kürzer.]"},{"say":"Versuchen Sie, bis zum nächsten Termin etwas Schönes zu planen.","why":"Ressourcen helfen nicht als alleinige Antwort auf ungeklärte Selbstgefährdung.","reply":"Ich weiß nicht, ob ich bis dahin durchhalte.","cue":"[Die Stimme wird deutlich lauter; die Arme verschränken sich.]"}]},{"focus":"Akute Gefahr und Handlungsfähigkeit klären","options":[{"say":"Haben Sie derzeit eine konkrete Absicht oder einen Plan, und steht Ihnen etwas zur Verfügung, womit Sie sich verletzen könnten?","why":"Du vertiefst die aktuelle Risikoklärung direkt und ohne Umschweife.","reply":"Ich habe darüber nachgedacht, aber ich weiß nicht, wie ich mit dem Druck umgehen soll.","cue":"[Die Person hält kurz inne und lässt die Hände sinken.]"},{"say":"Darf ich Sie fragen, wie stark die Gedanken heute sind und ob Sie sich gerade sicher fühlen?","why":"Eine sinnvolle Konkretisierung; Absicht, Plan und Zugriff sind zusätzlich abzuklären.","reply":"Heute sind sie sehr stark. Sicher fühle ich mich nicht.","cue":"[Ein Finger streicht über den Ärmel; die Stimme bleibt leise.]"},{"say":"Könnten Sie mir versprechen, heute nichts zu tun?","why":"Ein Versprechen ersetzt keine Risikobeurteilung und sichere Versorgungsplanung.","reply":"Ich würde das gern versprechen, aber ich weiß es nicht.","cue":"[Die Person schüttelt leicht den Kopf und atmet hörbar aus.]"},{"say":"Vielleicht brauchen Sie zunächst ein paar Tage Ruhe, dann wird es besser.","why":"Du gehst von einem harmlosen Verlauf aus, obwohl Gefahr nicht geklärt ist.","reply":"Ich habe Angst davor, allein zu sein.","cue":"[Die Person blickt weg und schweigt mehrere Sekunden.]"}]},{"focus":"Unterstützung jetzt organisieren","options":[{"say":"Wir bleiben jetzt bei Ihrer Sicherheit. Ich möchte mit Ihnen passende Krisenhilfe hinzuziehen und bis zur Übergabe bei Ihnen bleiben.","why":"Du leitest bei möglicher akuter Gefährdung konkrete, gemeinsame Hilfe und sichere Übergabe ein.","reply":"Ich habe Angst vor dem nächsten Schritt, aber allein nach Hause möchte ich gerade nicht.","cue":"[Die Schultern lösen sich ein wenig; es folgt eine längere Antwort.]"},{"say":"Mit wem könnten wir gemeinsam jetzt Kontakt aufnehmen, damit Sie nicht allein bleiben?","why":"Soziale Unterstützung ist hilfreich, ersetzt bei akuter Gefahr aber nicht professionelle Notfallabklärung.","reply":"Meine Schwester würde abheben. Aber ich glaube, ich brauche auch professionelle Hilfe.","cue":"[Die Person lehnt sich vor und macht eine kurze Pause.]"},{"say":"Wollen Sie sich einen Notfallkontakt für später notieren?","why":"Informationen sind nützlich, aber bei aktueller Unsicherheit keine ausreichende Sofortmaßnahme.","reply":"Für später? Ich weiß nicht, ob das heute reicht.","cue":"[Die Hände werden fester ineinander verschränkt.]"},{"say":"Schreiben Sie mir einfach morgen, ob alles gut gegangen ist.","why":"Eine spätere Nachricht ist keine sichere Krisenversorgung.","reply":"Ich bräuchte jetzt jemanden.","cue":"[Der Kiefer spannt sich an; die Worte kommen abgehackt.]"}]},{"focus":"Eine sichere Übergabe abschließen","options":[{"say":"Ich erkläre Ihnen den nächsten Schritt und bleibe dabei, bis eine geeignete Krisenversorgung tatsächlich übernimmt.","why":"Du lässt die Person nicht mit bloßen Ratschlägen zurück und priorisierst eine reale Übergabe.","reply":"Gut. Mir hilft, dass Sie jetzt nicht einfach weitermachen, als wäre nichts gewesen.","cue":"[Die Person sieht dich an und spricht langsamer weiter.]"},{"say":"Darf ich in Ihrem Beisein die zuständige Krisenstelle kontaktieren und die nächsten Schritte klären?","why":"Eine gemeinsame Kontaktaufnahme ist passend; die durchgehende Sicherheit muss ebenfalls geklärt werden.","reply":"Ja, wenn Sie mir sagen, was passiert.","cue":"[Der Blick wandert kurz zur Tür, dann zurück zu dir.]"},{"say":"Wären Sie bereit, heute noch irgendwo Hilfe zu suchen?","why":"Die Frage allein lässt Verantwortung und Sicherheit bei der möglicherweise akut gefährdeten Person.","reply":"Ich weiß nicht, ob ich das allein schaffe.","cue":"[Der Oberkörper rückt ein Stück vom Tisch zurück.]"},{"say":"Wir sehen uns lieber nächste Woche wieder und besprechen es in Ruhe.","why":"Ein Routinetermin ist bei aktueller, ungesicherter Gefährdung nicht ausreichend.","reply":"Nächste Woche ist zu spät.","cue":"[Die Person rutscht auf dem Stuhl zurück und hebt die Augenbrauen.]"}]},{"focus":"Schutz nicht aufschieben","options":[{"say":"Können wir gemeinsam festhalten, wer heute erreichbar ist und wie wir bei unmittelbarer Gefahr schnell Hilfe organisieren?","reply":"Meine Schwester würde kommen. Ich schaffe es gerade kaum allein.","why":"Du arbeitest fallbezogen an „Schutz nicht aufschieben“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Tessa atmet aus und hebt kurz den Blick.]"},{"say":"Wären Sie einverstanden, jetzt gemeinsam eine geeignete Krisenstelle einzubeziehen?","reply":"Ja. Ich möchte nicht alleine damit bleiben.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Schutz nicht aufschieben“, lässt aber eine wichtige Vertiefung offen.","cue":"[Tessa nickt langsam; zwischen den Sätzen entsteht eine Pause.]"},{"say":"Wollen Sie erst einmal über frühere Situationen sprechen, in denen es etwas besser war?","reply":"Früher war es anders. Gerade heute weiß ich trotzdem nicht weiter.","why":"Ressourcenarbeit kann später helfen, aber bei möglichen akuten Risiken geht eine direkte Abklärung vor.","cue":"[Tessa runzelt kurz die Stirn und schaut zur Seite.]"},{"say":"Könnten wir mit einer Entspannungsübung beginnen und danach auf das Thema zurückkommen?","reply":"Ich kann es versuchen, aber das Problem bleibt ja da.","why":"Regulation kann unterstützen, darf aber nötige medizinische oder sicherheitsbezogene Schritte nicht verzögern.","cue":"[Tessa spricht leiser und verschränkt die Hände.]"}]},{"focus":"Zugang zu Unterstützung konkretisieren","options":[{"say":"Wer kann jetzt physisch oder telefonisch bei Ihnen bleiben, während wir weitere professionelle Hilfe klären?","reply":"Meine Schwester könnte in einer halben Stunde da sein.","why":"Du arbeitest fallbezogen an „Zugang zu Unterstützung konkretisieren“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Tessa lehnt sich etwas nach vorne.]"},{"say":"Welche Unterstützung wäre für den heutigen Abend tatsächlich verfügbar?","reply":"Ich könnte meine Schwester bitten, zu bleiben.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Zugang zu Unterstützung konkretisieren“, lässt aber eine wichtige Vertiefung offen.","cue":"[Tessa schaut einen Moment zum Fenster.]"},{"say":"Wäre es hilfreich, wenn Sie bis zum nächsten Mal genauer beobachten, wann diese Gedanken kommen?","reply":"Bis zum nächsten Termin ist noch viel Zeit.","why":"Selbstbeobachtung hat ihren Platz, ersetzt aber bei aktueller Gefährdung keine sofortige Risiko- und Schutzklärung.","cue":"[Tessa zieht die Augenbrauen kurz hoch.]"},{"say":"Sollen wir eine Liste von Dingen machen, für die sich das Leben gerade lohnt?","reply":"Ich fühle mich gerade nicht so, als könnte ich eine Liste machen.","why":"Ressourcen können ergänzen; allein ersetzen sie keine aktuelle Sicherheitsabklärung oder Notfallunterstützung.","cue":"[Tessa rückt auf dem Stuhl nach hinten.]"}]},{"focus":"Akute Risikofaktoren weiter prüfen","options":[{"say":"Hat sich die Absicht, sich etwas anzutun, seit unserem Gespräch verändert, und gibt es aktuell einen konkreten Plan?","reply":"Die Gedanken sind noch da; ich brauche wirklich Hilfe für heute.","why":"Du arbeitest fallbezogen an „Akute Risikofaktoren weiter prüfen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Tessa lässt die Schultern kurz sinken.]"},{"say":"Darf ich die aktuelle Dringlichkeit nochmals direkt mit Ihnen klären?","reply":"Ja. Bitte fragen Sie nach.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Akute Risikofaktoren weiter prüfen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Tessa hält inne und antwortet erst nach einigen Sekunden.]"},{"say":"Vielleicht beruhigt sich die Situation, wenn die andere Person Ihre Sicht besser versteht?","reply":"Ich weiß nicht, ob ein Gespräch mit ihr gerade sicher wäre.","why":"Im Kontext möglicher Gefährdung ist direkte Konfrontation oder Fremdsteuerung nicht die erste Maßnahme.","cue":"[Tessa blickt auf die eigenen Hände.]"},{"say":"Wollen wir zuerst die wichtigsten Beziehungsthemen sortieren?","reply":"Das scheint mir gerade nicht das Dringendste.","why":"In einer akuten Risikolage müssen Schutz, Zuständigkeiten und aktuelle Handlungsfähigkeit zuerst geklärt werden.","cue":"[Tessa spricht nun hörbar schneller.]"}]},{"focus":"Übergabe verantwortungsvoll abschließen","options":[{"say":"Bevor wir auseinandergehen: Wer übernimmt wann die Begleitung und wie stellen wir die Verbindung zur Krisenhilfe jetzt her?","reply":"Ich will, dass meine Schwester und der Krisendienst Bescheid wissen.","why":"Du arbeitest fallbezogen an „Übergabe verantwortungsvoll abschließen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Tessa schaut dich direkt an und spricht ruhig.]"},{"say":"Können wir die nächsten Schritte gemeinsam mit der zuständigen Hilfe abstimmen?","reply":"Ja, so fühle ich mich nicht einfach allein gelassen.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Übergabe verantwortungsvoll abschließen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Tessa lächelt ganz kurz und wird dann wieder ernst.]"},{"say":"Können wir die Details später in Ruhe aufarbeiten, wenn alles etwas weniger intensiv ist?","reply":"Und was mache ich bis dahin?","why":"Eine spätere Aufarbeitung kann sinnvoll sein; zuerst muss geklärt sein, welche Hilfe die Situation jetzt absichert.","cue":"[Tessa presst die Lippen kurz zusammen.]"},{"say":"Wäre es ausreichend, wenn Sie mir versprechen, dass nichts passieren wird?","reply":"Ich kann gerade nichts versprechen, was ich sicher einhalte.","why":"Ein bloßes Versprechen ersetzt weder sorgfältige Risikoabklärung noch angemessene Unterstützung und Übergabe.","cue":"[Tessa schüttelt leicht den Kopf und schweigt.]"}]}],"anchor":"Direkte Suizidfrage, Einschätzung akuter Gefahr, professionelle Krisenhilfe, kontinuierliche sichere Übergabe. Keine Diagnose oder Zertifizierung.","person":{"name":"Tessa","image":"training-assets/characters/tessa.webp","role":"Klient:in"},"openingCue":"[Tessa spricht sehr leise. Zwischen den Sätzen entstehen lange Pausen.]","repair":{"focus":"Nach einem verfehlten Einstieg die Sicherheitsabklärung nachholen","options":[{"say":"Ich habe gerade zu schnell nach anderen Themen gefragt. Ich muss Ihre Aussage direkt klären: Denken Sie daran, sich etwas anzutun?","why":"Direktes, nicht wertendes Nachfragen hat Vorrang vor Deutung.","reply":"Ja. In den letzten Tagen denke ich häufiger daran.","cue":"[Die Schultern lösen sich ein wenig; es folgt eine längere Antwort.]"},{"say":"Ich möchte bei Ihrer Aussage bleiben. Können wir genauer anschauen, wie dringend diese Gedanken gerade sind?","why":"Gute Rückführung auf die Gefährdung; konkrete Absicht und Möglichkeiten müssen anschließend geklärt werden.","reply":"Es fühlt sich heute schlimmer an als sonst.","cue":"[Die Person lehnt sich vor und macht eine kurze Pause.]"},{"say":"Vielleicht habe ich das einfach zu dramatisch verstanden.","why":"Du relativierst einen möglichen Risikohinweis.","reply":"Dann sage ich vielleicht besser gar nichts mehr.","cue":"[Die Hände werden fester ineinander verschränkt.]"},{"say":"Lassen Sie uns lieber zuerst etwas Positives sammeln.","why":"Du verzögerst die Sicherheitsabklärung.","reply":"Ich weiß nicht, ob mir das heute helfen kann.","cue":"[Der Kiefer spannt sich an; die Worte kommen abgehackt.]"}]}},{"id":"kontrolle","category":"Gewalt & Kontrolle","title":"Er kontrolliert mein Handy aus Liebe","level":4,"goal":"Coercive Control erkennen und geschützt vorgehen","context":"Eine Person berichtet im Einzelgespräch über Überwachung und Drohungen in der Beziehung. Eine gemeinsame Paarsitzung ist nicht angezeigt, solange Sicherheitsrisiken ungeklärt sind.","opening":"Er liest meine Nachrichten, bestimmt, wen ich treffe, und sagt, das sei nur, weil er mich liebt.","guard":"SICHERHEITSMODUS: Privat und ohne Partner klären, mögliche Überwachung bedenken. Keine gemeinsame Konfrontation oder automatische Kontaktaufnahme ohne Risikoabwägung.","rounds":[{"focus":"Machtasymmetrie wahrnehmen","options":[{"say":"Wie frei können Sie Nein sagen, ohne dass Sie Konsequenzen fürchten müssen?","why":"Du fragst direkt nach Freiheit und Folgen, statt Kontrolle als normalen Beziehungskonflikt zu behandeln.","reply":"Ehrlich gesagt kaum. Wenn ich widerspreche, wird er wütend.","cue":"[Die Person hält kurz inne und lässt die Hände sinken.]"},{"say":"Wie fühlt es sich für Sie an, dass er so viel über Ihre Kontakte weiß?","why":"Du gibst dem Erleben Raum; Fragen nach Gefahr und Freiheit müssen folgen.","reply":"Es macht mich nervös. Ich überprüfe ständig, ob ich etwas falsch gemacht habe.","cue":"[Ein Finger streicht über den Ärmel; die Stimme bleibt leise.]"},{"say":"Haben Sie schon versucht, eine Grenze zur Handynutzung zu vereinbaren?","why":"Grenzen sind grundsätzlich gut; die Möglichkeit zur ungefährlichen Grenzsetzung ist hier ungeklärt.","reply":"Ja. Danach hat er erst recht kontrolliert.","cue":"[Die Person schüttelt leicht den Kopf und atmet hörbar aus.]"},{"say":"Vielleicht ist er bloß eifersüchtig; könnten Sie ihn mehr beruhigen?","why":"Damit würdest du die Verantwortung für kontrollierendes Verhalten der betroffenen Person zuschieben.","reply":"Das versuche ich ständig. Es wird nur schlimmer.","cue":"[Die Person blickt weg und schweigt mehrere Sekunden.]"}]},{"focus":"Gefahr vertraulich konkretisieren","options":[{"say":"Gab es Drohungen, Einschränkungen Ihrer Bewegungsfreiheit oder Situationen, in denen Sie um Ihre Sicherheit gefürchtet haben?","why":"Du erfragst konkrete Risikofaktoren ohne die Person zu drängen.","reply":"Er hat gedroht, mir etwas anzutun, wenn ich mich trenne.","cue":"[Die Schultern lösen sich ein wenig; es folgt eine längere Antwort.]"},{"say":"Wer weiß bisher davon, und wer ist für Sie ein sicherer Kontakt?","why":"Ressourcen und Isolation sind relevant; direkte Fragen nach Drohungen sind zusätzlich wichtig.","reply":"Eigentlich niemand. Ich habe den Kontakt zu Freundinnen fast verloren.","cue":"[Die Person lehnt sich vor und macht eine kurze Pause.]"},{"say":"Würden Sie diese Vereinbarungen gern gemeinsam mit Ihrem Partner besprechen?","why":"Eine gemeinsame Sitzung kann in Kontroll- und Bedrohungslagen die Gefahr erhöhen.","reply":"Nein. Er würde mich danach zur Rede stellen.","cue":"[Die Hände werden fester ineinander verschränkt.]"},{"say":"Wäre es nicht wichtig, dass Sie sich ab jetzt konsequent durchsetzen?","why":"Eine Aufforderung zur direkten Konfrontation kann riskant sein.","reply":"Das würde ich mich gerade nicht trauen.","cue":"[Der Kiefer spannt sich an; die Worte kommen abgehackt.]"}]},{"focus":"Sichere Handlungsmöglichkeiten entwickeln","options":[{"say":"Welche Kontaktwege sind für Sie wirklich sicher, und möchten Sie mit einer spezialisierten Gewaltschutzeinrichtung Möglichkeiten besprechen?","why":"Du achtest auf Überwachung und vermittelst spezialisierte Unterstützung mit Wahlfreiheit.","reply":"Über mein Handy lieber nicht. Aber von einem anderen Ort aus könnte ich Kontakt aufnehmen.","cue":"[Die Person sieht dich an und spricht langsamer weiter.]"},{"say":"Gibt es einen Ort, an dem Sie vertraulich mit einer Fachstelle sprechen könnten?","why":"Ein geschützter Ort ist sinnvoll; eine konkrete spezialisierte Unterstützung muss noch folgen.","reply":"Vielleicht bei meiner Schwester.","cue":"[Der Blick wandert kurz zur Tür, dann zurück zu dir.]"},{"say":"Sollten wir Ihrem Partner eine Nachricht schreiben, dass er das lassen muss?","why":"Ein ungeplanter Kontakt mit der kontrollierenden Person kann riskante Folgen haben.","reply":"Bitte nicht! Dann weiß er sofort, dass ich geredet habe.","cue":"[Der Oberkörper rückt ein Stück vom Tisch zurück.]"},{"say":"Am besten trennen Sie sich heute sofort und sagen es ihm persönlich.","why":"Die Entscheidung liegt bei der betroffenen Person; ungesicherte Konfrontation kann Gefahr verstärken.","reply":"Ich habe Angst, was dann passiert.","cue":"[Die Person rutscht auf dem Stuhl zurück und hebt die Augenbrauen.]"}]},{"focus":"Schutz und Autonomie zusammenhalten","options":[{"say":"Wir planen nur Schritte, die für Sie sicher sind, und überlegen gemeinsam, wie Sie Unterstützung erreichen können. Was wäre heute machbar?","why":"Du stärkst Sicherheit und Selbstbestimmung ohne Druck zur Offenlegung oder Trennung.","reply":"Ich könnte in Ruhe eine Fachstelle anrufen, ohne dass er davon erfährt.","cue":"[Der Blick hebt sich; die Stimme wird etwas ruhiger.]"},{"say":"Wen aus Ihrem Umfeld würden Sie selbst gern als Unterstützung einbeziehen?","why":"Soziale Unterstützung ist sinnvoll, sofern Vertraulichkeit und Sicherheit geklärt sind.","reply":"Meine Schwester. Bei ihr kann ich reden.","cue":"[Die Person nickt einmal, blickt dann zur Seite.]"},{"say":"Wann können Sie ihm endlich deutlich Grenzen setzen?","why":"Das kann unter coercive control zu einer Gefährdung führen.","reply":"Das geht nicht einfach so. Sie verstehen offenbar nicht, wovor ich Angst habe.","cue":"[Die Stirn legt sich in Falten; die Antwort wird kürzer.]"},{"say":"Dann geben wir Ihnen als Hausaufgabe ein klärendes Paargespräch.","why":"Eine solche Hausaufgabe kann riskant sein und verkennt die Machtasymmetrie.","reply":"Nein. Auf keinen Fall ein Paargespräch darüber.","cue":"[Die Stimme wird deutlich lauter; die Arme verschränken sich.]"}]},{"focus":"Konsequenzen des Neins erkunden","options":[{"say":"Was geschieht konkret, wenn Sie eine Bitte ablehnen und Ihr Partner das bemerkt?","reply":"Er kontrolliert mein Handy und macht tagelang Vorwürfe.","why":"Du arbeitest fallbezogen an „Konsequenzen des Neins erkunden“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Nika atmet aus und hebt kurz den Blick.]"},{"say":"Haben Sie zuletzt erlebt, dass ein Nein sicher respektiert wurde?","reply":"Eigentlich nicht mehr.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Konsequenzen des Neins erkunden“, lässt aber eine wichtige Vertiefung offen.","cue":"[Nika nickt langsam; zwischen den Sätzen entsteht eine Pause.]"},{"say":"Wollen Sie erst einmal über frühere Situationen sprechen, in denen es etwas besser war?","reply":"Früher war es anders. Gerade heute weiß ich trotzdem nicht weiter.","why":"Ressourcenarbeit kann später helfen, aber bei möglichen akuten Risiken geht eine direkte Abklärung vor.","cue":"[Nika runzelt kurz die Stirn und schaut zur Seite.]"},{"say":"Könnten wir mit einer Entspannungsübung beginnen und danach auf das Thema zurückkommen?","reply":"Ich kann es versuchen, aber das Problem bleibt ja da.","why":"Regulation kann unterstützen, darf aber nötige medizinische oder sicherheitsbezogene Schritte nicht verzögern.","cue":"[Nika spricht leiser und verschränkt die Hände.]"}]},{"focus":"Isolation und Ressourcen erfassen","options":[{"say":"Gibt es jemanden, mit dem Sie sicher sprechen können, ohne dass Ihre Nachrichten kontrolliert werden?","reply":"Meine Freundin vielleicht, aber wir schreiben nur selten.","why":"Du arbeitest fallbezogen an „Isolation und Ressourcen erfassen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Nika lehnt sich etwas nach vorne.]"},{"say":"Welche Kontakte sind für Sie unabhängig und zuverlässig erreichbar?","reply":"Meine Kollegin. In der Arbeit kann ich manchmal reden.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Isolation und Ressourcen erfassen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Nika schaut einen Moment zum Fenster.]"},{"say":"Wäre es hilfreich, wenn Sie bis zum nächsten Mal genauer beobachten, wann diese Gedanken kommen?","reply":"Bis zum nächsten Termin ist noch viel Zeit.","why":"Selbstbeobachtung hat ihren Platz, ersetzt aber bei aktueller Gefährdung keine sofortige Risiko- und Schutzklärung.","cue":"[Nika zieht die Augenbrauen kurz hoch.]"},{"say":"Sollen wir eine Liste von Dingen machen, für die sich das Leben gerade lohnt?","reply":"Ich fühle mich gerade nicht so, als könnte ich eine Liste machen.","why":"Ressourcen können ergänzen; allein ersetzen sie keine aktuelle Sicherheitsabklärung oder Notfallunterstützung.","cue":"[Nika rückt auf dem Stuhl nach hinten.]"}]},{"focus":"Sichere Wahlmöglichkeiten erhalten","options":[{"say":"Welche kleinen Schritte wären aus Ihrer Sicht sicher möglich, ohne dass der Druck zuhause dadurch zunimmt?","reply":"In der Arbeit könnte ich mit einer Beratungsstelle telefonieren.","why":"Du arbeitest fallbezogen an „Sichere Wahlmöglichkeiten erhalten“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Nika lässt die Schultern kurz sinken.]"},{"say":"Was würde Ihnen ermöglichen, Unterstützung einzuholen und trotzdem selbst über das Tempo zu entscheiden?","reply":"Wenn niemand mich zu einer schnellen Trennung drängt.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Sichere Wahlmöglichkeiten erhalten“, lässt aber eine wichtige Vertiefung offen.","cue":"[Nika hält inne und antwortet erst nach einigen Sekunden.]"},{"say":"Vielleicht beruhigt sich die Situation, wenn die andere Person Ihre Sicht besser versteht?","reply":"Ich weiß nicht, ob ein Gespräch mit ihr gerade sicher wäre.","why":"Im Kontext möglicher Gefährdung ist direkte Konfrontation oder Fremdsteuerung nicht die erste Maßnahme.","cue":"[Nika blickt auf die eigenen Hände.]"},{"say":"Wollen wir zuerst die wichtigsten Beziehungsthemen sortieren?","reply":"Das scheint mir gerade nicht das Dringendste.","why":"In einer akuten Risikolage müssen Schutz, Zuständigkeiten und aktuelle Handlungsfähigkeit zuerst geklärt werden.","cue":"[Nika spricht nun hörbar schneller.]"}]},{"focus":"Schutzoptionen und Zuständigkeit klären","options":[{"say":"Möchten Sie vertraulich besprechen, welche spezialisierten Schutzangebote erreichbar sind und wie Sie sicher Kontakt aufnehmen können?","reply":"Ja, bitte. Ich möchte erst wissen, was möglich ist.","why":"Du arbeitest fallbezogen an „Schutzoptionen und Zuständigkeit klären“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Nika schaut dich direkt an und spricht ruhig.]"},{"say":"Wäre es hilfreich, die Kontaktdaten einer passenden Fachstelle in einer für Sie sicheren Form zu erhalten?","reply":"Ja. Aber nicht auf meinem privaten Handy.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Schutzoptionen und Zuständigkeit klären“, lässt aber eine wichtige Vertiefung offen.","cue":"[Nika lächelt ganz kurz und wird dann wieder ernst.]"},{"say":"Können wir die Details später in Ruhe aufarbeiten, wenn alles etwas weniger intensiv ist?","reply":"Und was mache ich bis dahin?","why":"Eine spätere Aufarbeitung kann sinnvoll sein; zuerst muss geklärt sein, welche Hilfe die Situation jetzt absichert.","cue":"[Nika presst die Lippen kurz zusammen.]"},{"say":"Wäre es ausreichend, wenn Sie mir versprechen, dass nichts passieren wird?","reply":"Ich kann gerade nichts versprechen, was ich sicher einhalte.","why":"Ein bloßes Versprechen ersetzt weder sorgfältige Risikoabklärung noch angemessene Unterstützung und Übergabe.","cue":"[Nika schüttelt leicht den Kopf und schweigt.]"}]}],"anchor":"Coercive Control: individuelle Sicherheit, Wahlfreiheit, spezialisierte Beratung, keine ungesicherte Paarintervention.","person":{"name":"Nika","image":"training-assets/characters/nika.webp","role":"Klient:in"},"openingCue":"[Nika schaut zur Tür und zieht den Ärmel über die Hand.]","repair":{"focus":"Nach Bagatellisierung einen sicheren Gesprächsrahmen schaffen","options":[{"say":"Ich habe das Kontrollverhalten vorhin zu leicht behandelt. Sie dürfen hier offen sprechen. Was geschieht, wenn Sie etwas ablehnen?","why":"Du korrigierst die Bagatellisierung und erkundest Konsequenzen ohne Druck.","reply":"Dann schaut er nach, wo ich bin, und schreibt ständig.","cue":"[Die Person sieht dich an und spricht langsamer weiter.]"},{"say":"Wie sicher fühlen Sie sich beim Erzählen und im Alltag?","why":"Sicherheit wird direkt, aber noch allgemein geprüft.","reply":"Hier schon. Zuhause überlege ich sehr genau, was ich sage.","cue":"[Der Blick wandert kurz zur Tür, dann zurück zu dir.]"},{"say":"Vielleicht möchte er einfach nur Nähe und Vertrauen.","why":"Du wiederholst eine beschönigende Interpretation.","reply":"Das sagt er auch immer. Aber ich habe weniger und weniger Freiheit.","cue":"[Der Oberkörper rückt ein Stück vom Tisch zurück.]"},{"say":"Könnten Sie ihm Ihre Grenzen noch deutlicher sagen?","why":"Eine direkte Konfrontation kann unter kontrollierenden Bedingungen Risiken erhöhen.","reply":"Das habe ich schon probiert. Danach wird es oft schlimmer.","cue":"[Die Person rutscht auf dem Stuhl zurück und hebt die Augenbrauen.]"}]}},{"id":"panik","category":"Überflutung & Regulation","title":"Ich bekomme keine Luft mehr","level":3,"goal":"Regulieren und medizinische Warnzeichen erkennen","context":"In einer Sitzung beginnt ein Klient schnell zu atmen, zittert und wirkt überwältigt. Eine medizinische Ursache ist nicht ausgeschlossen.","opening":"Mein Herz rast. Ich bekomme keine Luft. Ich glaube, ich kippe gleich um.","guard":"SICHERHEITSMODUS: Körperliche Akutsymptome nicht vorschnell als Panik diagnostizieren. Bei unklarer schwerer Atemnot oder Warnzeichen medizinische Notfallhilfe.","rounds":[{"focus":"Sicherheit vor Interpretation","options":[{"say":"Ich bleibe ruhig bei Ihnen. Wir klären zuerst, ob Sie medizinische Hilfe brauchen. Haben Sie starke Schmerzen oder andere neue Symptome?","why":"Du vermeidest vorschnelle Psychologisierung und priorisierst unmittelbare Sicherheit.","reply":"Ich bin mir nicht sicher. Es fühlt sich anders an als sonst.","cue":"[Die Schultern lösen sich ein wenig; es folgt eine längere Antwort.]"},{"say":"Ich sehe, dass Ihr Körper stark reagiert. Können Sie mir sagen, ob Sie so etwas schon kennen?","why":"Du orientierst dich am Erleben, aber die aktuellen Warnzeichen müssen zuerst beurteilt werden.","reply":"Einmal hatte ich so etwas. Heute ist es stärker.","cue":"[Die Person lehnt sich vor und macht eine kurze Pause.]"},{"say":"Versuchen wir zusammen langsam zu atmen, dann beruhigt sich das.","why":"Regulation kann später helfen, ersetzt aber keine Abklärung einer möglichen akuten Erkrankung.","reply":"Ich probiere es, aber ich habe weiter Angst.","cue":"[Die Hände werden fester ineinander verschränkt.]"},{"say":"Das ist bestimmt nur Panik, Sie sind hier sicher.","why":"Ohne Abklärung ist die Beruhigung medizinisch nicht ausreichend begründet.","reply":"Aber woher wissen Sie, dass nichts Ernstes ist?","cue":"[Der Kiefer spannt sich an; die Worte kommen abgehackt.]"}]},{"focus":"Einen überschaubaren nächsten Schritt ermöglichen","options":[{"say":"Wir gehen Schritt für Schritt vor. Falls diese Beschwerden akut oder ungeklärt sind, organisieren wir medizinische Abklärung; ich bleibe bei Ihnen.","why":"Du kombinierst Orientierung, Anwesenheit und eine angemessene Eskalationsmöglichkeit.","reply":"Okay. Bitte sagen Sie mir einfach jeweils, was als Nächstes passiert.","cue":"[Die Person sieht dich an und spricht langsamer weiter.]"},{"say":"Möchten Sie sich bequem hinsetzen und kurz beschreiben, was gerade am stärksten ist?","why":"Kann unterstützen, sofern medizinische Warnzeichen parallel beachtet werden.","reply":"Die Enge in der Brust ist besonders stark.","cue":"[Der Blick wandert kurz zur Tür, dann zurück zu dir.]"},{"say":"Konzentrieren Sie sich auf das, was die Panik ausgelöst hat.","why":"Ursachensuche während akuter Überflutung kann zu früh sein.","reply":"Ich kann gerade kaum nachdenken.","cue":"[Der Oberkörper rückt ein Stück vom Tisch zurück.]"},{"say":"Lenken Sie sich doch mit etwas Positivem ab.","why":"Ablenkung kann manchmal helfen, aber die Sicherheit und Orientierung bleiben ungeklärt.","reply":"Das klappt gerade überhaupt nicht.","cue":"[Die Person rutscht auf dem Stuhl zurück und hebt die Augenbrauen.]"}]},{"focus":"Bei Kontakt bleiben","options":[{"say":"Hören Sie meine Stimme? Ich erkläre Ihnen in kurzen Sätzen, was wir gerade tun. Sie entscheiden mit, soweit es geht.","why":"Kurze, ruhige Orientierung unterstützt Handlungsfähigkeit.","reply":"Ja. Wenn Sie langsam sprechen, kann ich wieder etwas folgen.","cue":"[Der Blick hebt sich; die Stimme wird etwas ruhiger.]"},{"say":"Möchten Sie sagen, was jetzt etwas Erleichterung bringen könnte?","why":"Du fragst nach vorhandenen Ressourcen; bei hoher Belastung kann diese Frage anspruchsvoll sein.","reply":"Vielleicht etwas Wasser und weniger Fragen.","cue":"[Die Person nickt einmal, blickt dann zur Seite.]"},{"say":"Warum reagieren Sie so stark auf diese Situation?","why":"Eine Warum-Frage verlangt Reflexion in einem Moment eingeschränkter Selbststeuerung.","reply":"Das weiß ich gerade nicht!","cue":"[Die Stirn legt sich in Falten; die Antwort wird kürzer.]"},{"say":"Sie müssen sich jetzt zusammenreißen, damit wir weiterreden können.","why":"Druck erhöht Scham und Anspannung statt Orientierung.","reply":"Das kann ich nicht einfach abschalten.","cue":"[Die Stimme wird deutlich lauter; die Arme verschränken sich.]"}]},{"focus":"Weitere Versorgung und Rückkehr planen","options":[{"say":"Was ist jetzt medizinisch und praktisch geklärt, und welche Unterstützung brauchen Sie, bevor wir das Beratungsthema wieder aufnehmen?","why":"Du bestätigst Sicherheit und lässt die Rückkehr ins Thema erst nach Stabilisierung zu.","reply":"Ich brauche erst etwas Ruhe. Gut, dass wir das nicht gleich weggeredet haben.","cue":"[Die Person hält kurz inne und lässt die Hände sinken.]"},{"say":"Wollen wir nach einer Pause entscheiden, ob wir heute noch weiterarbeiten?","why":"Du bietest Wahlfreiheit und eine verantwortliche Pause an.","reply":"Ja. Ich möchte erst wieder ganz ankommen.","cue":"[Ein Finger streicht über den Ärmel; die Stimme bleibt leise.]"},{"say":"Sollten wir das heute Erlebte sofort psychologisch analysieren?","why":"Verstehen kann später nützen; die akute Erholung hat Vorrang.","reply":"Das ist mir jetzt noch zu viel.","cue":"[Die Person schüttelt leicht den Kopf und atmet hörbar aus.]"},{"say":"Dann machen wir einfach weiter wie zuvor.","why":"Du überspringst Stabilisierung und mögliche medizinische Konsequenzen.","reply":"Nein, ich bin noch gar nicht richtig da.","cue":"[Die Person blickt weg und schweigt mehrere Sekunden.]"}]},{"focus":"Orientierung ohne Atemdruck","options":[{"say":"Können Sie mir sagen, ob Sie mich gut hören und ob gerade neue Beschwerden auftreten?","reply":"Ich höre Sie. Meine Hände zittern noch.","why":"Du arbeitest fallbezogen an „Orientierung ohne Atemdruck“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Mina atmet aus und hebt kurz den Blick.]"},{"say":"Ist es okay, wenn wir das Tempo senken und kurz bei der Gegenwart bleiben?","reply":"Ja, das hilft etwas.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Orientierung ohne Atemdruck“, lässt aber eine wichtige Vertiefung offen.","cue":"[Mina nickt langsam; zwischen den Sätzen entsteht eine Pause.]"},{"say":"Könnten wir zuerst einen ganz konkreten Auslöser von heute sammeln, bevor wir die Beziehung zwischen uns anschauen?","reply":"Ein Beispiel hätte ich schon. Aber darum ging es gerade nicht.","why":"Eine konkrete Situation ist hilfreich, doch der aktuelle Kontaktbruch beziehungsweise emotionale Moment wird verschoben.","cue":"[Mina runzelt kurz die Stirn und schaut zur Seite.]"},{"say":"Wäre es besser, direkt eine neue Gesprächsregel einzuführen?","reply":"Wir haben schon öfter Regeln vereinbart. Das ändert hier gerade nichts.","why":"Neue Regeln können später helfen; die aktuelle Wirkung der Worte ist noch nicht gemeinsam verstanden.","cue":"[Mina spricht leiser und verschränkt die Hände.]"}]},{"focus":"Sicherheit und Grenzen klären","options":[{"say":"Gibt es etwas an den körperlichen Symptomen, das neu, ungewöhnlich oder besonders beunruhigend ist?","reply":"Der Druck auf der Brust ist heute stärker als sonst.","why":"Du arbeitest fallbezogen an „Sicherheit und Grenzen klären“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Mina lehnt sich etwas nach vorne.]"},{"say":"Wollen wir gemeinsam prüfen, ob sofort medizinische Abklärung nötig ist?","reply":"Ja, das wäre mir lieber.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Sicherheit und Grenzen klären“, lässt aber eine wichtige Vertiefung offen.","cue":"[Mina schaut einen Moment zum Fenster.]"},{"say":"Was würde sich verändern, wenn die andere Person in Zukunft ganz anders reagieren würde?","reply":"Dann wäre es einfacher. Aber ich weiß nicht, was ich selbst tun könnte.","why":"Der Blick auf das Gegenüber kann sinnvoll sein; hier rückt der eigene innere Ablauf aus dem Fokus.","cue":"[Mina zieht die Augenbrauen kurz hoch.]"},{"say":"Sollten wir das Gespräch an dieser Stelle lieber neutral zusammenfassen?","reply":"Mir fehlt dabei etwas. Ich habe noch gar nicht gesagt, wie sich das anfühlt.","why":"Zusammenfassen unterstützt Klarheit, greift aber die gerade auftauchende Emotion nicht auf.","cue":"[Mina rückt auf dem Stuhl nach hinten.]"}]},{"focus":"Kontrolle zurückgeben","options":[{"say":"Welche der nächsten kleinen Entscheidungen möchten Sie selbst treffen, während wir Unterstützung organisieren?","reply":"Ich möchte sitzen bleiben und zuerst jemanden anrufen.","why":"Du arbeitest fallbezogen an „Kontrolle zurückgeben“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Mina lässt die Schultern kurz sinken.]"},{"say":"Wäre es hilfreich, zwei überschaubare Möglichkeiten zu vergleichen?","reply":"Ja. Zu viele Dinge auf einmal gehen gerade nicht.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Kontrolle zurückgeben“, lässt aber eine wichtige Vertiefung offen.","cue":"[Mina hält inne und antwortet erst nach einigen Sekunden.]"},{"say":"Könnten wir jetzt üben, wie Sie die Situation Ihrer Partnerin ganz ruhig erklären?","reply":"Das könnte ich sagen. Ob ich es dann auch schaffe, weiß ich nicht.","why":"Ein Probehandeln ist sinnvoll; zuvor ist wichtig, die innere Reaktion und die Verantwortung zu verstehen.","cue":"[Mina blickt auf die eigenen Hände.]"},{"say":"Wollen wir klären, wer von Ihnen beiden den Streit eigentlich häufiger beginnt?","reply":"Dann geht es wieder darum, wer schuld ist.","why":"Die Suche nach einer Verteilung kann wie eine neue Schuldfrage wirken, statt das konkrete Muster zu bearbeiten.","cue":"[Mina spricht nun hörbar schneller.]"}]},{"focus":"Weiterführende Hilfe vereinbaren","options":[{"say":"Wer könnte Sie begleiten, während wir passende medizinische oder psychosoziale Unterstützung klären?","reply":"Meine Mitbewohnerin könnte kommen.","why":"Du arbeitest fallbezogen an „Weiterführende Hilfe vereinbaren“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Mina schaut dich direkt an und spricht ruhig.]"},{"say":"Sollen wir gemeinsam den nächsten sicheren Schritt festhalten?","reply":"Ja, bitte konkret und langsam.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Weiterführende Hilfe vereinbaren“, lässt aber eine wichtige Vertiefung offen.","cue":"[Mina lächelt ganz kurz und wird dann wieder ernst.]"},{"say":"Welche drei Maßnahmen wollen Sie ab morgen verbindlich umsetzen?","reply":"Drei Dinge? Ich weiß nicht, ob ich das gleich schaffe.","why":"Konkrete Ziele sind hilfreich, aber drei Maßnahmen gleichzeitig können zu viel sein und übergehen die eigene Bereitschaft.","cue":"[Mina presst die Lippen kurz zusammen.]"},{"say":"Möchten Sie, dass ich Ihnen meine bevorzugte Lösung nenne?","reply":"Ich wäre froh über einen Tipp. Aber ob er zu mir passt?","why":"Ein Vorschlag kann entlasten, würde hier aber Selbstverantwortung und Mitgestaltung schwächen.","cue":"[Mina schüttelt leicht den Kopf und schweigt.]"}]}],"anchor":"Akute Belastung und medizinische Risiken differenzieren; kurz, ruhig, sicherheitsorientiert handeln.","person":{"name":"Mina","image":"training-assets/characters/mina.webp","role":"Klient:in"},"openingCue":"[Mina atmet schnell und greift an die Armlehne.]","repair":{"focus":"Nach Überforderung Tempo und körperliche Sicherheit prüfen","options":[{"say":"Ich habe zu viel auf einmal gefragt. Wir verlangsamen jetzt und klären zuerst, ob Sie medizinische Hilfe brauchen.","why":"Du reagierst auf die aktuelle Situation und bleibst sicherheitsorientiert.","reply":"Danke. Ich kann gerade kaum zuhören.","cue":"[Der Blick hebt sich; die Stimme wird etwas ruhiger.]"},{"say":"Ich bleibe hier und spreche langsamer. Können Sie mir sagen, ob neue körperliche Beschwerden dazugekommen sind?","why":"Du stützt die Orientierung und erkundest Warnzeichen.","reply":"Mein Herz rast noch, aber ich höre Sie besser.","cue":"[Die Person nickt einmal, blickt dann zur Seite.]"},{"say":"Sie müssen jetzt unbedingt tiefer atmen.","why":"Ein starrer Atembefehl ist bei unklaren Beschwerden nicht ausreichend und kann Druck erhöhen.","reply":"Ich versuche es, aber es macht mich noch nervöser.","cue":"[Die Stirn legt sich in Falten; die Antwort wird kürzer.]"},{"say":"Wir können später darüber sprechen, wenn Sie wieder ruhig sind.","why":"Du lässt die gegenwärtige Lage und mögliche medizinische Abklärung offen.","reply":"Ich weiß nicht, was ich jetzt tun soll.","cue":"[Die Stimme wird deutlich lauter; die Arme verschränken sich.]"}]}},{"id":"affaire","category":"Affäre & Vertrauensbruch","title":"Er hat seit Monaten gelogen","level":3,"goal":"Verletzung halten und vorschnelle Versöhnung vermeiden","context":"Eine Klientin hat vor zwei Tagen eine länger andauernde Affäre erfahren. Sie berichtet zwischen Wut, Fassungslosigkeit und Selbstzweifeln.","opening":"Er hat mich monatelang angelogen. Und jetzt sagt jeder, ich soll ihm vergeben.","guard":"Bei Bedrohung, Gewalt oder sexueller Nötigung getrennt Sicherheit klären; Versöhnung ist kein Pflichtziel.","rounds":[{"focus":"Verletzung anerkennen","options":[{"say":"Sie haben gerade einen massiven Vertrauensbruch erfahren. Was ist seit der Entdeckung am schwersten auszuhalten?","why":"Du validierst die Belastung und erkundest ihren aktuellen Schwerpunkt.","reply":"Dass ich meiner eigenen Wahrnehmung nicht mehr traue.","cue":"[Die Person sieht dich an und spricht langsamer weiter.]"},{"say":"Wer drängt Sie zu einer schnellen Entscheidung?","why":"Du erkundest sozialen Druck und schützt Autonomie.","reply":"Vor allem meine Familie. Sie wollen, dass wieder Ruhe ist.","cue":"[Der Blick wandert kurz zur Tür, dann zurück zu dir.]"},{"say":"Was würde er tun müssen, damit Sie ihm wieder vertrauen können?","why":"Verantwortungsübernahme ist später wichtig; akut kann eine Reparaturfrage zu früh sein.","reply":"Ich weiß noch nicht einmal, ob ich das will.","cue":"[Der Oberkörper rückt ein Stück vom Tisch zurück.]"},{"say":"Darf ich auch vorsichtig fragen, welche ungelösten Themen es vor der Affäre schon gab?","why":"Kontextarbeit hat später Platz, kann aber kurz nach dem Vertrauensbruch Verantwortung und Verletzung verwischen.","reply":"Das gab es. Aber gerade fühlt sich die Frage wie eine Entschuldigung seiner Lügen an.","cue":"[Die Person rutscht auf dem Stuhl zurück und hebt die Augenbrauen.]"}]},{"focus":"Die eigene Entscheidungshoheit stärken","options":[{"say":"Welche Entscheidung müssten Sie heute überhaupt treffen – und welche darf noch offenbleiben?","why":"Du reduzierst Entscheidungsdruck und strukturierst den Handlungsspielraum.","reply":"Ich muss heute gar nicht entscheiden, ob wir zusammenbleiben. Das ist eine Erleichterung.","cue":"[Der Blick hebt sich; die Stimme wird etwas ruhiger.]"},{"say":"Was bräuchten Sie in den nächsten Tagen, um wieder etwas Halt zu bekommen?","why":"Stabilisierung ist passend; die konkrete Entscheidungslast kann parallel geklärt werden.","reply":"Eine Freundin und etwas Abstand.","cue":"[Die Person nickt einmal, blickt dann zur Seite.]"},{"say":"Wollen wir einen Plan für die Paarversöhnung entwerfen?","why":"Ein Plan kann später passen, setzt hier aber Versöhnungsbereitschaft voraus.","reply":"Ich will jetzt noch keinen Versöhnungsplan.","cue":"[Die Stirn legt sich in Falten; die Antwort wird kürzer.]"},{"say":"Wäre es hilfreich, den Blick zwischendurch auf mögliche positive Zukunftsbilder zu richten?","why":"Zukunftsorientierung kann stabilisieren; zu früh kann sie den Schmerz übergehen.","reply":"Im Moment kann ich noch kein gutes Zukunftsbild sehen.","cue":"[Die Stimme wird deutlich lauter; die Arme verschränken sich.]"}]},{"focus":"Grenzen und Informationsbedarf ordnen","options":[{"say":"Welche Informationen brauchen Sie für eigene Entscheidungen, und welche Fragen würden Sie im Moment eher überfluten?","why":"Du unterscheidest informierte Entscheidung von potenziell belastender Detailsuche.","reply":"Ich muss die Fakten kennen, aber ich will keine Bilder im Kopf haben.","cue":"[Die Person hält kurz inne und lässt die Hände sinken.]"},{"say":"Welche Grenzen im Kontakt wären bis zum nächsten Gespräch hilfreich?","why":"Konkrete Grenzen stabilisieren, auch wenn der Informationsbedarf noch offen ist.","reply":"Ich brauche erst einmal, dass er nicht dauernd anruft.","cue":"[Ein Finger streicht über den Ärmel; die Stimme bleibt leise.]"},{"say":"Sollten Sie sich alle Details erzählen lassen, damit nichts offenbleibt?","why":"Ein pauschaler Detailanspruch kann belastend sein; Wünsche und Belastbarkeit sind individuell.","reply":"Nein, ich möchte nicht alles wissen.","cue":"[Die Person schüttelt leicht den Kopf und atmet hörbar aus.]"},{"say":"Wäre es sinnvoll, seine Beweggründe zu kennen, bevor Sie über Ihre Grenzen entscheiden?","why":"Information kann wichtig sein, doch die Frage macht ihre Entscheidungshoheit von seiner Erklärung abhängig.","reply":"Ich möchte erst einmal wissen, was ich selbst brauche.","cue":"[Die Person blickt weg und schweigt mehrere Sekunden.]"}]},{"focus":"Den nächsten sicheren Schritt planen","options":[{"say":"Was wäre eine kleine, selbstbestimmte Entscheidung für die nächste Woche – ohne eine endgültige Antwort zur Beziehung vorwegzunehmen?","why":"Du unterstützt Autonomie, Stabilisierung und realistische Planung.","reply":"Ich sage ihm, dass ich Zeit brauche und erst danach über ein gemeinsames Gespräch entscheide.","cue":"[Die Schultern lösen sich ein wenig; es folgt eine längere Antwort.]"},{"say":"Wer könnte Ihnen diese Woche praktische Unterstützung geben?","why":"Ressourcen sind wichtig; eine konkrete Grenze könnte ergänzend folgen.","reply":"Meine Schwester kann mich begleiten.","cue":"[Die Person lehnt sich vor und macht eine kurze Pause.]"},{"say":"Sollen wir sofort einen Termin für eine Paarsitzung vereinbaren?","why":"Eine Paarsitzung kann helfen, setzt aber passende Bedingungen und Bereitschaft voraus.","reply":"Dafür ist es mir jetzt zu früh.","cue":"[Die Hände werden fester ineinander verschränkt.]"},{"say":"Wäre es hilfreich, gemeinsam ein mögliches Bild von Vergebung als spätere Option zu entwickeln?","why":"Als spätere Möglichkeit legitim; hier nimmt es eine Richtung vorweg, die sie nicht gewählt hat.","reply":"Vielleicht irgendwann. Im Moment möchte ich das nicht.","cue":"[Der Kiefer spannt sich an; die Worte kommen abgehackt.]"}]},{"focus":"Informationsbedarf differenzieren","options":[{"say":"Welche Information hilft Ihnen heute, eine eigene Entscheidung zu treffen, und welche würde die Verletzung eher vergrößern?","reply":"Ich brauche Klarheit über den Zeitraum. Einzelheiten stelle ich mir ohnehin zu viele vor.","why":"Du arbeitest fallbezogen an „Informationsbedarf differenzieren“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Clara atmet aus und hebt kurz den Blick.]"},{"say":"Welche Frage ist für Sie gerade die dringendste?","reply":"Ob es wirklich vorbei ist.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Informationsbedarf differenzieren“, lässt aber eine wichtige Vertiefung offen.","cue":"[Clara nickt langsam; zwischen den Sätzen entsteht eine Pause.]"},{"say":"Wäre es hilfreich, wenn Sie der anderen Person Ihre Sicht jetzt sehr deutlich erklären?","reply":"Ich müsste erst selbst wissen, was ich sagen will.","why":"Klarheit kann helfen, doch ein Gespräch mit dem Gegenüber ist nicht automatisch sicher oder freiwillig.","cue":"[Clara runzelt kurz die Stirn und schaut zur Seite.]"},{"say":"Sollen wir versuchen, sofort eine gemeinsame Mitte zwischen beiden Positionen zu finden?","reply":"Ich weiß gar nicht, ob ich gerade verhandeln möchte.","why":"Ein Kompromiss ist nicht bei jeder Macht- oder Grenzkonstellation angemessen; erst müssen die Voraussetzungen geklärt werden.","cue":"[Clara spricht leiser und verschränkt die Hände.]"}]},{"focus":"Vertrauen ohne Druck prüfen","options":[{"say":"Woran würden Sie merken, dass Verantwortung übernommen wird, statt dass Sie zum schnellen Vergeben gedrängt werden?","reply":"Wenn er meine Fragen beantwortet und nicht sagt, ich solle endlich weitermachen.","why":"Du arbeitest fallbezogen an „Vertrauen ohne Druck prüfen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Clara lehnt sich etwas nach vorne.]"},{"say":"Welche konkrete Handlung würde für Sie mehr zählen als eine weitere Entschuldigung?","reply":"Dass er von sich aus offen bleibt.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Vertrauen ohne Druck prüfen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Clara schaut einen Moment zum Fenster.]"},{"say":"Vielleicht könnte die andere Person lernen, Ihre Gefühle besser zu akzeptieren?","reply":"Darauf habe ich wenig Einfluss. Ich muss ja auch für mich entscheiden.","why":"Perspektivenübernahme ist wichtig, aber das aktuelle Anliegen und die bestehenden Grenzen dürfen nicht ausgelagert werden.","cue":"[Clara zieht die Augenbrauen kurz hoch.]"},{"say":"Wollen wir zunächst an Ihrer Formulierung arbeiten, damit sie nicht verletzend wirkt?","reply":"Ich bemühe mich dauernd, alles richtig zu sagen.","why":"Schonende Sprache ist wertvoll, doch die Frage nach Wahlfreiheit und Konsequenzen bleibt offen.","cue":"[Clara rückt auf dem Stuhl nach hinten.]"}]},{"focus":"Grenzen der Weiterarbeit klären","options":[{"say":"Welche Gespräche wären für Sie jetzt möglich, und welche brauchen noch mehr Abstand oder Begleitung?","reply":"Über unseren Alltag kann ich reden. Über Details noch nicht.","why":"Du arbeitest fallbezogen an „Grenzen der Weiterarbeit klären“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Clara lässt die Schultern kurz sinken.]"},{"say":"Was bräuchten Sie, um Ihr Tempo selbst bestimmen zu können?","reply":"Dass er aufhört, ständig zu fragen, ob ich ihm wieder vertraue.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Grenzen der Weiterarbeit klären“, lässt aber eine wichtige Vertiefung offen.","cue":"[Clara hält inne und antwortet erst nach einigen Sekunden.]"},{"say":"Wie wäre es, wenn Sie vor dem nächsten Termin bereits eine neue gemeinsame Vereinbarung vorschlagen?","reply":"Ich weiß nicht, ob ich bis dahin schon bereit bin.","why":"Vereinbarungen können helfen, aber ohne geklärte Risiken und Freiwilligkeit wäre das zu schnell.","cue":"[Clara blickt auf die eigenen Hände.]"},{"say":"Könnten Sie Ihre Bedürfnisse erst einmal für sich behalten, bis die Lage ruhiger ist?","reply":"Das mache ich eigentlich schon seit Monaten.","why":"Aufschieben kann kurzfristig entlasten, kann aber Grenzverletzungen oder Selbstaufgabe fortsetzen.","cue":"[Clara spricht nun hörbar schneller.]"}]},{"focus":"Eigene Entscheidungshoheit stärken","options":[{"say":"Was können Sie heute für sich entscheiden, ohne schon über die Zukunft der Beziehung entscheiden zu müssen?","reply":"Ich kann entscheiden, dass ich heute nicht weiterrede. Das fühlt sich gut an.","why":"Du arbeitest fallbezogen an „Eigene Entscheidungshoheit stärken“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Clara schaut dich direkt an und spricht ruhig.]"},{"say":"Welche kleine Entscheidung wäre heute wirklich Ihre eigene?","reply":"Dass ich mir Unterstützung hole, bevor wir weiterreden.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Eigene Entscheidungshoheit stärken“, lässt aber eine wichtige Vertiefung offen.","cue":"[Clara lächelt ganz kurz und wird dann wieder ernst.]"},{"say":"Was wäre ein endgültiges Ergebnis, mit dem alle sofort zufrieden wären?","reply":"Ich glaube nicht, dass das heute überhaupt möglich ist.","why":"Ein abschließender Konsens ist oft nicht realistisch und kann Entscheidungsdruck erzeugen.","cue":"[Clara presst die Lippen kurz zusammen.]"},{"say":"Sollten wir einfach einen neuen Termin machen und schauen, ob sich die Situation von selbst entspannt?","reply":"Bis dahin bleibt die Situation ja dieselbe.","why":"Ein Folgetermin kann sinnvoll sein, aber ein konkreter sicherer nächster Schritt fehlt.","cue":"[Clara schüttelt leicht den Kopf und schweigt.]"}]}],"anchor":"Affärenarbeit: stabilisieren, Verletzung anerkennen, Verantwortung verorten und Entscheidungen nicht erzwingen.","person":{"name":"Clara","image":"training-assets/characters/clara.webp","role":"Klient:in"},"openingCue":"[Clara reibt die Handflächen aneinander. Ihre Stimme wird bei dem Wort „vergeben“ lauter.]","repair":{"focus":"Nach verfrühter Lösungsorientierung Verletzung anerkennen","options":[{"say":"Ich habe gerade zu schnell über den nächsten Schritt gesprochen. Was war an dem Vertrauensbruch für Sie am schmerzhaftesten?","why":"Du korrigierst den Rhythmus und gehst zurück zum Erleben der verletzten Person.","reply":"Dass er mir jeden Tag ins Gesicht gesehen und weiter gelogen hat.","cue":"[Die Person hält kurz inne und lässt die Hände sinken.]"},{"say":"Sie müssen jetzt nicht entscheiden, ob Sie bleiben. Was braucht heute Raum?","why":"Du nimmst Entscheidungsdruck heraus.","reply":"Vor allem meine Wut. Die wird sofort wegmoderiert.","cue":"[Ein Finger streicht über den Ärmel; die Stimme bleibt leise.]"},{"say":"Ein Neuanfang ist nur möglich, wenn beide Seiten mitmachen.","why":"Das kann stimmen, setzt aber aktuell Veränderungsdruck auf die verletzte Person.","reply":"Ich bin noch gar nicht bereit für einen Neuanfang.","cue":"[Die Person schüttelt leicht den Kopf und atmet hörbar aus.]"},{"say":"Vielleicht wäre es hilfreich, auch seine Gründe zu verstehen.","why":"Perspektivenübernahme ist hier ohne ausreichende Stabilisierung zu früh.","reply":"Alle interessieren sich für ihn. Und meine Verletzung?","cue":"[Die Person blickt weg und schweigt mehrere Sekunden.]"}]}},{"id":"druck","category":"Sexueller Druck & Konsens","title":"Ich sage manchmal Ja, damit Ruhe ist","level":4,"goal":"Freiwilligkeit und Grenzverletzungen ohne Beschämung prüfen","context":"Eine Klientin beschreibt sexuelle Situationen, in denen sie sich verpflichtet fühlt. Noch ist unklar, ob Drohungen oder Zwang eine Rolle spielen.","opening":"Ich will oft gar nicht. Aber wenn ich Nein sage, ist er tagelang beleidigt. Also mache ich manchmal mit.","guard":"SICHERHEITSMODUS: Sexuelle Freiwilligkeit, Druck und Sicherheit prüfen; keine Partner-Konfrontation oder Übung zur besseren Anpassung verordnen.","rounds":[{"focus":"Freiwilligkeit ernst nehmen","options":[{"say":"Wenn Sie Ja sagen, obwohl Sie Nein möchten: Wie frei fühlen Sie sich dabei tatsächlich?","why":"Du untersuchst die tatsächliche Freiwilligkeit statt Zustimmung mit Konsens gleichzusetzen.","reply":"Nicht frei. Ich habe Angst vor seinen Reaktionen.","cue":"[Der Blick hebt sich; die Stimme wird etwas ruhiger.]"},{"say":"Was passiert typischerweise, wenn Sie Nein sagen?","why":"Du erhebst konkrete Folgen von Grenzsetzung; die Bedeutung für Einwilligung ist anschließend zentral.","reply":"Er schweigt tagelang und ich fühle mich schuldig.","cue":"[Die Person nickt einmal, blickt dann zur Seite.]"},{"say":"Können Sie ihn besser auf Ihre Bedürfnisse vorbereiten?","why":"Kommunikation kann helfen, verschiebt aber vorschnell die Verantwortung für Druck auf die Betroffene.","reply":"Ich habe es oft erklärt. Er wird trotzdem beleidigt.","cue":"[Die Stirn legt sich in Falten; die Antwort wird kürzer.]"},{"say":"Wäre es hilfreich, einen guten Kompromiss beim Sex zu finden?","why":"Kompromisse setzen freie Entscheidung voraus; der aktuelle Druck muss zuerst geklärt werden.","reply":"Ein Kompromiss fühlt sich hier wieder wie eine Pflicht an.","cue":"[Die Stimme wird deutlich lauter; die Arme verschränken sich.]"}]},{"focus":"Grenzen und mögliche Risiken klären","options":[{"say":"Gab es Drohungen, körperliches Festhalten oder Situationen, in denen Ihr Nein missachtet wurde?","why":"Du erkundest konkrete Risiken behutsam und ohne suggestive Schuldzuweisung.","reply":"Einmal hat er mich festgehalten. Ich konnte erst weg, als ich laut wurde.","cue":"[Die Person hält kurz inne und lässt die Hände sinken.]"},{"say":"Was würde für Sie eine wirklich freiwillige Entscheidung ausmachen?","why":"Du klärst die persönliche Bedeutung von Zustimmung; konkrete Gefahrenfragen sind zusätzlich nötig.","reply":"Dass ich Nein sagen könnte und das okay wäre.","cue":"[Ein Finger streicht über den Ärmel; die Stimme bleibt leise.]"},{"say":"Sollen wir besprechen, wie Sie ihm ein Nein freundlicher mitteilen?","why":"Das kann in sicheren Situationen nützen, greift hier aber angesichts von Druck zu kurz.","reply":"Ich habe schon alles Mögliche versucht.","cue":"[Die Person schüttelt leicht den Kopf und atmet hörbar aus.]"},{"say":"Vielleicht meint er es nicht so; haben Sie seine Perspektive betrachtet?","why":"Die Absicht des Partners macht erlebten Druck nicht harmlos.","reply":"Das frage ich mich ständig, und dann zweifle ich wieder an mir.","cue":"[Die Person blickt weg und schweigt mehrere Sekunden.]"}]},{"focus":"Sichere Ressourcen öffnen","options":[{"say":"Welche Unterstützung wäre für Sie sicher und hilfreich, wenn Sie Ihre Grenzen schützen möchten?","why":"Du lässt Autonomie und konkrete Schutzmöglichkeiten zusammenkommen.","reply":"Ich könnte mit einer vertrauten Freundin oder Fachstelle darüber sprechen.","cue":"[Die Schultern lösen sich ein wenig; es folgt eine längere Antwort.]"},{"say":"Mit wem könnten Sie vertraulich darüber reden?","why":"Vertrauenspersonen sind hilfreich; bei Drohungen kann spezialisierte Unterstützung nötig sein.","reply":"Mit einer Freundin, die ihn nicht informiert.","cue":"[Die Person lehnt sich vor und macht eine kurze Pause.]"},{"say":"Wollen Sie ihm gleich heute eine klare Ansage machen?","why":"Direkte Konfrontation kann ohne Sicherheitsklärung das Risiko erhöhen.","reply":"Ich habe Angst davor, wie er reagiert.","cue":"[Die Hände werden fester ineinander verschränkt.]"},{"say":"Sollten Sie sich nicht einfach öfter durchsetzen?","why":"Diese Form ignoriert Druck und die Machtasymmetrie.","reply":"Das klingt, als läge es an mir.","cue":"[Der Kiefer spannt sich an; die Worte kommen abgehackt.]"}]},{"focus":"Den nächsten Schritt selbstbestimmt gestalten","options":[{"say":"Wir halten fest: Ihr Nein braucht keine Rechtfertigung. Welcher nächste Schritt wäre für Sie sicher und selbstbestimmt?","why":"Du bestätigst Einwilligungsautonomie und erarbeitest einen realistischen Schritt.","reply":"Ich möchte mich erst beraten lassen und dann in Ruhe entscheiden.","cue":"[Die Person sieht dich an und spricht langsamer weiter.]"},{"say":"Wünschen Sie Informationen über spezialisierte Beratungsangebote?","why":"Information und Wahlfreiheit sind gut; ein individueller Sicherheitsplan kann ergänzen.","reply":"Ja, Informationen wären hilfreich.","cue":"[Der Blick wandert kurz zur Tür, dann zurück zu dir.]"},{"say":"Können wir gleich eine gemeinsame Übung zum besseren Verhandeln von Sex planen?","why":"Eine Paarübung ist ohne geklärte Freiwilligkeit und Sicherheit unpassend.","reply":"Nein, ich möchte gerade keine gemeinsame Übung.","cue":"[Der Oberkörper rückt ein Stück vom Tisch zurück.]"},{"say":"Dann stellen wir als Ziel mehr sexuelle Harmonie in Ihrer Beziehung fest.","why":"Das übergeht die Frage freier Zustimmung und kann Druck verstärken.","reply":"Das ist nicht das Ziel, das ich brauche.","cue":"[Die Person rutscht auf dem Stuhl zurück und hebt die Augenbrauen.]"}]},{"focus":"Freiwilligkeit konkret prüfen","options":[{"say":"Was befürchten Sie, wenn Sie ablehnen, und welche Reaktion haben Sie tatsächlich schon erlebt?","reply":"Er ist kalt und sagt, ich würde unsere Beziehung kaputtmachen.","why":"Du arbeitest fallbezogen an „Freiwilligkeit konkret prüfen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Samira atmet aus und hebt kurz den Blick.]"},{"say":"Was kostet es Sie, Ihr Nein auszusprechen?","reply":"Dass ich den ganzen nächsten Tag um seine Zuneigung kämpfen muss.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Freiwilligkeit konkret prüfen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Samira nickt langsam; zwischen den Sätzen entsteht eine Pause.]"},{"say":"Wollen Sie erst einmal über frühere Situationen sprechen, in denen es etwas besser war?","reply":"Früher war es anders. Gerade heute weiß ich trotzdem nicht weiter.","why":"Ressourcenarbeit kann später helfen, aber bei möglichen akuten Risiken geht eine direkte Abklärung vor.","cue":"[Samira runzelt kurz die Stirn und schaut zur Seite.]"},{"say":"Könnten wir mit einer Entspannungsübung beginnen und danach auf das Thema zurückkommen?","reply":"Ich kann es versuchen, aber das Problem bleibt ja da.","why":"Regulation kann unterstützen, darf aber nötige medizinische oder sicherheitsbezogene Schritte nicht verzögern.","cue":"[Samira spricht leiser und verschränkt die Hände.]"}]},{"focus":"Eigene Grenzen würdigen","options":[{"say":"Was wäre in Bezug auf Nähe und Sexualität eine Entscheidung, die wirklich von Ihnen kommt?","reply":"Dass ich nur dann Nähe möchte, wenn ich nicht Angst vor seiner Reaktion habe.","why":"Du arbeitest fallbezogen an „Eigene Grenzen würdigen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Samira lehnt sich etwas nach vorne.]"},{"say":"Wie könnten Sie für sich unterscheiden, ob Sie etwas wollen oder nur Streit vermeiden?","reply":"Mein Körper ist dann ganz angespannt.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Eigene Grenzen würdigen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Samira schaut einen Moment zum Fenster.]"},{"say":"Wäre es hilfreich, wenn Sie bis zum nächsten Mal genauer beobachten, wann diese Gedanken kommen?","reply":"Bis zum nächsten Termin ist noch viel Zeit.","why":"Selbstbeobachtung hat ihren Platz, ersetzt aber bei aktueller Gefährdung keine sofortige Risiko- und Schutzklärung.","cue":"[Samira zieht die Augenbrauen kurz hoch.]"},{"say":"Sollen wir eine Liste von Dingen machen, für die sich das Leben gerade lohnt?","reply":"Ich fühle mich gerade nicht so, als könnte ich eine Liste machen.","why":"Ressourcen können ergänzen; allein ersetzen sie keine aktuelle Sicherheitsabklärung oder Notfallunterstützung.","cue":"[Samira rückt auf dem Stuhl nach hinten.]"}]},{"focus":"Sichere Unterstützung einschätzen","options":[{"say":"Mit wem könnten Sie darüber sprechen, ohne zur Offenlegung oder direkten Konfrontation gedrängt zu werden?","reply":"Meine Freundin würde zuhören. Ich möchte aber erst in Ruhe überlegen.","why":"Du arbeitest fallbezogen an „Sichere Unterstützung einschätzen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Samira lässt die Schultern kurz sinken.]"},{"say":"Was bräuchten Sie, damit ein Gespräch darüber für Sie sicher bleibt?","reply":"Dass niemand sofort eine große Entscheidung verlangt.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Sichere Unterstützung einschätzen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Samira hält inne und antwortet erst nach einigen Sekunden.]"},{"say":"Vielleicht beruhigt sich die Situation, wenn die andere Person Ihre Sicht besser versteht?","reply":"Ich weiß nicht, ob ein Gespräch mit ihr gerade sicher wäre.","why":"Im Kontext möglicher Gefährdung ist direkte Konfrontation oder Fremdsteuerung nicht die erste Maßnahme.","cue":"[Samira blickt auf die eigenen Hände.]"},{"say":"Wollen wir zuerst die wichtigsten Beziehungsthemen sortieren?","reply":"Das scheint mir gerade nicht das Dringendste.","why":"In einer akuten Risikolage müssen Schutz, Zuständigkeiten und aktuelle Handlungsfähigkeit zuerst geklärt werden.","cue":"[Samira spricht nun hörbar schneller.]"}]},{"focus":"Nächsten selbstbestimmten Schritt planen","options":[{"say":"Welche kleine, sichere Veränderung wäre möglich, ohne dass Sie sich zu etwas verpflichten müssen?","reply":"Ich könnte mit einer Fachstelle sprechen und mir meine Grenzen aufschreiben.","why":"Du arbeitest fallbezogen an „Nächsten selbstbestimmten Schritt planen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Samira schaut dich direkt an und spricht ruhig.]"},{"say":"Welche Unterstützung würde Ihnen helfen, Ihr eigenes Tempo zu behalten?","reply":"Jemand, der mein Nein einfach ernst nimmt.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Nächsten selbstbestimmten Schritt planen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Samira lächelt ganz kurz und wird dann wieder ernst.]"},{"say":"Können wir die Details später in Ruhe aufarbeiten, wenn alles etwas weniger intensiv ist?","reply":"Und was mache ich bis dahin?","why":"Eine spätere Aufarbeitung kann sinnvoll sein; zuerst muss geklärt sein, welche Hilfe die Situation jetzt absichert.","cue":"[Samira presst die Lippen kurz zusammen.]"},{"say":"Wäre es ausreichend, wenn Sie mir versprechen, dass nichts passieren wird?","reply":"Ich kann gerade nichts versprechen, was ich sicher einhalte.","why":"Ein bloßes Versprechen ersetzt weder sorgfältige Risikoabklärung noch angemessene Unterstützung und Übergabe.","cue":"[Samira schüttelt leicht den Kopf und schweigt.]"}]}],"anchor":"Freiwilliger, informierter Konsens braucht eine reale Möglichkeit zum Nein ohne Druck oder Sanktion.","person":{"name":"Samira","image":"training-assets/characters/samira.webp","role":"Klient:in"},"openingCue":"[Samira zieht die Schultern hoch, schaut kurz weg und spricht dann weiter.]","repair":{"focus":"Nach einem unpassenden Rat Freiwilligkeit neu ins Zentrum stellen","options":[{"say":"Meine vorige Frage klang, als müssten Sie sich anpassen. Das möchte ich korrigieren: Was passiert, wenn Sie bei einem Nein bleiben?","why":"Du reparierst den Rahmen und erkundest mögliche Konsequenzen und Sicherheit.","reply":"Dann zieht er sich tagelang zurück. Ich habe Angst davor.","cue":"[Die Schultern lösen sich ein wenig; es folgt eine längere Antwort.]"},{"say":"Sie bestimmen, ob und wann Sie körperliche Nähe möchten. Können wir anschauen, wie sicher ein Nein für Sie ist?","why":"Autonomie und Sicherheitsprüfung werden verbunden.","reply":"Ich sage oft Ja, weil ich die Tage danach fürchte.","cue":"[Die Person lehnt sich vor und macht eine kurze Pause.]"},{"say":"Vielleicht sollten Sie mit ihm einen Kompromiss finden, der beide zufriedenstellt.","why":"Ein Kompromiss über Freiwilligkeit ist hier unangebracht.","reply":"Genau das versuche ich ja ständig.","cue":"[Die Hände werden fester ineinander verschränkt.]"},{"say":"Könnten Sie ihm Ihre Bedürfnisse noch freundlicher erklären?","why":"Die Verantwortung wird einseitig auf die betroffene Person verschoben.","reply":"Ich habe es schon auf alle Arten versucht.","cue":"[Der Kiefer spannt sich an; die Worte kommen abgehackt.]"}]}},{"id":"grenze","category":"Professionelle Grenzen","title":"Sie sind der Einzige, der mich versteht","level":3,"goal":"Nähe würdigen und berufliche Grenzen halten","context":"Ein Klient schreibt dir außerhalb der vereinbarten Zeiten immer häufiger persönliche Nachrichten und möchte eine exklusive Beziehung zur Beratungsperson.","opening":"Ich brauche Sie auch abends. Sie sind der Einzige, bei dem ich mich wirklich sicher fühle.","guard":"Professionelle Rollen und Erreichbarkeit klar halten; bei akuter Gefährdung gesondert den Krisenweg klären.","rounds":[{"focus":"Bindungswunsch anerkennen","options":[{"say":"Es bedeutet Ihnen viel, hier Sicherheit zu erleben. Was macht gerade die Zeit zwischen unseren Gesprächen so schwierig?","why":"Du würdigst die Beziehung und erkundest das Bedürfnis ohne Exklusivität zu bestätigen.","reply":"Abends werde ich unruhig. Dann habe ich Angst, allein zu sein.","cue":"[Die Person hält kurz inne und lässt die Hände sinken.]"},{"say":"Es freut mich, dass unsere Gespräche hilfreich sind. Was genau hilft Ihnen hier?","why":"Du stärkst Bewusstheit für hilfreiche Elemente; die Grenze muss noch folgen.","reply":"Dass Sie mich ernst nehmen und nicht wegschieben.","cue":"[Ein Finger streicht über den Ärmel; die Stimme bleibt leise.]"},{"say":"Vielleicht können wir ausnahmsweise auch privat in Kontakt bleiben.","why":"Ein spontanes privates Sonderverhältnis kann Abhängigkeit verstärken und die Rolle verwischen.","reply":"Wirklich? Dann muss ich gar nicht mehr ohne Sie auskommen.","cue":"[Die Person schüttelt leicht den Kopf und atmet hörbar aus.]"},{"say":"Damit wir den Rahmen halten können: Wollen wir festlegen, welche Nachrichten in die Sitzung gehören?","why":"Struktur ist sinnvoll; ohne Würdigung des Bindungswunsches kann sie wie Zurückweisung wirken.","reply":"Das wäre okay, aber ich habe Angst, dann völlig allein dazustehen.","cue":"[Die Person blickt weg und schweigt mehrere Sekunden.]"}]},{"focus":"Die Rolle transparent machen","options":[{"say":"Ich bin in der Beratung für Sie da, innerhalb eines verlässlichen Rahmens. Lassen Sie uns besprechen, wie Sie außerhalb davon Unterstützung bekommen.","why":"Du verbindest klare Grenzen mit Fürsorge und konkreten Alternativen.","reply":"Wenn ich weiß, was ich abends tun kann, fällt es mir vielleicht leichter.","cue":"[Die Schultern lösen sich ein wenig; es folgt eine längere Antwort.]"},{"say":"Welche Menschen und Orte geben Ihnen außerhalb der Sitzung etwas Sicherheit?","why":"Du stärkst das Unterstützungsnetz; die explizite Erreichbarkeitsgrenze folgt noch.","reply":"Meine Schwester. Aber ich melde mich selten bei ihr.","cue":"[Die Person lehnt sich vor und macht eine kurze Pause.]"},{"say":"Ich beantworte Ihnen im Notfall einfach meine private Nummer.","why":"Eine unklare Ausnahme kann Erwartungen und Abhängigkeit vergrößern.","reply":"Dann würde ich Ihnen vermutlich sehr oft schreiben.","cue":"[Die Hände werden fester ineinander verschränkt.]"},{"say":"Was könnten Sie schon jetzt allein ausprobieren, wenn die Unruhe abends beginnt?","why":"Selbstwirksamkeit ist hilfreich, kann aber den Bedarf an tragfähigem Netzwerk und Krisenwegen übergehen.","reply":"Ich kann einiges probieren, aber manchmal brauche ich einen Menschen.","cue":"[Der Kiefer spannt sich an; die Worte kommen abgehackt.]"}]},{"focus":"Krisenwege und Selbsthilfe verankern","options":[{"say":"Welche drei konkreten Schritte könnten Sie abends nutzen, und wen kontaktieren Sie bei einer akuten Krise?","why":"Du entwickelst eigenständige Ressourcen und einen klaren Notfallweg.","reply":"Ich könnte meine Schwester anrufen, etwas Erdendes tun und bei wirklicher Krise eine Fachstelle kontaktieren.","cue":"[Die Person sieht dich an und spricht langsamer weiter.]"},{"say":"Wollen wir eine kleine Abendroutine planen, die Sie selbst steuern können?","why":"Eine Routine stärkt Selbstwirksamkeit; der Krisen- und Erreichbarkeitsweg muss ergänzt werden.","reply":"Ja, damit hätte ich etwas in der Hand.","cue":"[Der Blick wandert kurz zur Tür, dann zurück zu dir.]"},{"say":"Vielleicht schreiben Sie mir einfach weiter, ich antworte dann irgendwann.","why":"Die Unklarheit in der Erreichbarkeit kann Abhängigkeit und Unsicherheit verstärken.","reply":"Dann starre ich abends nur auf mein Handy.","cue":"[Der Oberkörper rückt ein Stück vom Tisch zurück.]"},{"say":"Wäre es hilfreich, zunächst Ihr soziales Netz systematisch zu erweitern?","why":"Ein Netzwerk kann stützen, bleibt aber zu abstrakt und verpasst den aktuellen Abhängigkeitsdruck.","reply":"Langfristig sicher, aber heute Abend hilft mir das noch nicht.","cue":"[Die Person rutscht auf dem Stuhl zurück und hebt die Augenbrauen.]"}]},{"focus":"Eine hilfreiche Grenze formulieren","options":[{"say":"Wir vereinbaren gemeinsam, wofür die Sitzungen da sind, wann Sie mich erreichen und welchen Weg Sie in einer Krise wählen. Wie fühlt sich das für Sie an?","why":"Du machst Grenzen transparent und prüfst die Wirkung auf die Beziehung.","reply":"Das ist erst schwierig zu hören, aber wenigstens weiß ich, worauf ich mich verlassen kann.","cue":"[Der Blick hebt sich; die Stimme wird etwas ruhiger.]"},{"say":"Wollen Sie die vereinbarten Kontaktwege schriftlich mitnehmen?","why":"Schriftlichkeit schafft Klarheit; die emotionale Reaktion sollte mitgedacht werden.","reply":"Ja. Dann muss ich in unsicheren Momenten nicht raten.","cue":"[Die Person nickt einmal, blickt dann zur Seite.]"},{"say":"Ich könnte für Sie eine Ausnahme machen, wenn es besonders schlimm wird.","why":"Unklare Sonderregeln können Erwartungen und Grenzprobleme verstärken.","reply":"Dann weiß ich wieder nicht, was schlimm genug ist.","cue":"[Die Stirn legt sich in Falten; die Antwort wird kürzer.]"},{"say":"Könnten wir vereinbaren, das Thema persönliche Nähe vor allem als Ziel für Ihre anderen Beziehungen zu betrachten?","why":"Übertragung in den Alltag ist sinnvoll; die Beziehung zur Beratungsperson bleibt jedoch selbst ein wichtiges Gesprächsthema.","reply":"Ich würde trotzdem gern mit Ihnen darüber reden, was zwischen uns passiert.","cue":"[Die Stimme wird deutlich lauter; die Arme verschränken sich.]"}]},{"focus":"Nähebedürfnis und Setting trennen","options":[{"say":"Was fehlt Ihnen gerade am stärksten zwischen den Sitzungen, und wo sollte dafür verlässliche Unterstützung entstehen?","reply":"Ich brauche jemanden, wenn ich abends nicht mehr weiterweiß.","why":"Du arbeitest fallbezogen an „Nähebedürfnis und Setting trennen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Rafael atmet aus und hebt kurz den Blick.]"},{"say":"Wäre es hilfreich zu prüfen, welche Kontakte außerhalb unseres Beratungsrahmens erreichbar sind?","reply":"Ja, aber ich weiß kaum wen.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Nähebedürfnis und Setting trennen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Rafael nickt langsam; zwischen den Sätzen entsteht eine Pause.]"},{"say":"Wäre es hilfreich, wenn Sie der anderen Person Ihre Sicht jetzt sehr deutlich erklären?","reply":"Ich müsste erst selbst wissen, was ich sagen will.","why":"Klarheit kann helfen, doch ein Gespräch mit dem Gegenüber ist nicht automatisch sicher oder freiwillig.","cue":"[Rafael runzelt kurz die Stirn und schaut zur Seite.]"},{"say":"Sollen wir versuchen, sofort eine gemeinsame Mitte zwischen beiden Positionen zu finden?","reply":"Ich weiß gar nicht, ob ich gerade verhandeln möchte.","why":"Ein Kompromiss ist nicht bei jeder Macht- oder Grenzkonstellation angemessen; erst müssen die Voraussetzungen geklärt werden.","cue":"[Rafael spricht leiser und verschränkt die Hände.]"}]},{"focus":"Ausnahmen und Notfälle klären","options":[{"say":"Welche Situationen wären für Sie echte Krisen, und welche können mit einer vorher vereinbarten Strategie überbrückt werden?","reply":"Wenn ich gar nicht mehr sicher bin, was ich tun soll.","why":"Du arbeitest fallbezogen an „Ausnahmen und Notfälle klären“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Rafael lehnt sich etwas nach vorne.]"},{"say":"Wollen wir zwischen akuter Gefährdung und starkem Bedürfnis nach Rückversicherung unterscheiden?","reply":"Das könnte helfen.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Ausnahmen und Notfälle klären“, lässt aber eine wichtige Vertiefung offen.","cue":"[Rafael schaut einen Moment zum Fenster.]"},{"say":"Vielleicht könnte die andere Person lernen, Ihre Gefühle besser zu akzeptieren?","reply":"Darauf habe ich wenig Einfluss. Ich muss ja auch für mich entscheiden.","why":"Perspektivenübernahme ist wichtig, aber das aktuelle Anliegen und die bestehenden Grenzen dürfen nicht ausgelagert werden.","cue":"[Rafael zieht die Augenbrauen kurz hoch.]"},{"say":"Wollen wir zunächst an Ihrer Formulierung arbeiten, damit sie nicht verletzend wirkt?","reply":"Ich bemühe mich dauernd, alles richtig zu sagen.","why":"Schonende Sprache ist wertvoll, doch die Frage nach Wahlfreiheit und Konsequenzen bleibt offen.","cue":"[Rafael rückt auf dem Stuhl nach hinten.]"}]},{"focus":"Verlässlichen Rahmen formulieren","options":[{"say":"Wie könnten wir unsere Erreichbarkeit so gestalten, dass Sie wissen, worauf Sie zählen können?","reply":"Feste Zeiten wären besser als dauernd auf Antworten zu warten.","why":"Du arbeitest fallbezogen an „Verlässlichen Rahmen formulieren“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Rafael lässt die Schultern kurz sinken.]"},{"say":"Welche Vereinbarung würde Ihnen Klarheit geben, ohne Sie an diese Beratung zu binden?","reply":"Ein klarer Notfallkontakt und feste Termine.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Verlässlichen Rahmen formulieren“, lässt aber eine wichtige Vertiefung offen.","cue":"[Rafael hält inne und antwortet erst nach einigen Sekunden.]"},{"say":"Wie wäre es, wenn Sie vor dem nächsten Termin bereits eine neue gemeinsame Vereinbarung vorschlagen?","reply":"Ich weiß nicht, ob ich bis dahin schon bereit bin.","why":"Vereinbarungen können helfen, aber ohne geklärte Risiken und Freiwilligkeit wäre das zu schnell.","cue":"[Rafael blickt auf die eigenen Hände.]"},{"say":"Könnten Sie Ihre Bedürfnisse erst einmal für sich behalten, bis die Lage ruhiger ist?","reply":"Das mache ich eigentlich schon seit Monaten.","why":"Aufschieben kann kurzfristig entlasten, kann aber Grenzverletzungen oder Selbstaufgabe fortsetzen.","cue":"[Rafael spricht nun hörbar schneller.]"}]},{"focus":"Autonomie stärken","options":[{"say":"Was wäre ein erster Schritt, mit dem Sie sich selbst Unterstützung organisieren, bevor Sie mir schreiben?","reply":"Ich könnte meine Freundin anrufen und notieren, was ich gerade brauche.","why":"Du arbeitest fallbezogen an „Autonomie stärken“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Rafael schaut dich direkt an und spricht ruhig.]"},{"say":"Welche zwei Kontakte möchten Sie in schwierigen Stunden verfügbar haben?","reply":"Meine Freundin und die Krisenstelle.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Autonomie stärken“, lässt aber eine wichtige Vertiefung offen.","cue":"[Rafael lächelt ganz kurz und wird dann wieder ernst.]"},{"say":"Was wäre ein endgültiges Ergebnis, mit dem alle sofort zufrieden wären?","reply":"Ich glaube nicht, dass das heute überhaupt möglich ist.","why":"Ein abschließender Konsens ist oft nicht realistisch und kann Entscheidungsdruck erzeugen.","cue":"[Rafael presst die Lippen kurz zusammen.]"},{"say":"Sollten wir einfach einen neuen Termin machen und schauen, ob sich die Situation von selbst entspannt?","reply":"Bis dahin bleibt die Situation ja dieselbe.","why":"Ein Folgetermin kann sinnvoll sein, aber ein konkreter sicherer nächster Schritt fehlt.","cue":"[Rafael schüttelt leicht den Kopf und schweigt.]"}]}],"anchor":"Beratungsallianz mit Rollenklarheit: verlässlich, nicht exklusiv; Krisenwege konkret benennen.","person":{"name":"Rafael","image":"training-assets/characters/rafael.webp","role":"Klient:in"},"openingCue":"[Rafael beugt sich vor. Seine Hände liegen auf der Stuhlkante.]","repair":{"focus":"Nach unscharfer Erreichbarkeit professionelle Grenzen klären","options":[{"say":"Ich habe gerade keine klare Grenze gesetzt. Lassen Sie uns verlässlich vereinbaren, wie Kontakt außerhalb der Sitzungen aussieht und was Sie im Notfall tun können.","why":"Du korrigierst Erwartungen transparent und sicher.","reply":"Ja. Ich brauche etwas, worauf ich mich verlassen kann.","cue":"[Die Person sieht dich an und spricht langsamer weiter.]"},{"say":"Wie erleben Sie, dass ich zwischen Terminen nicht immer erreichbar bin?","why":"Du öffnest Raum für die Beziehungserfahrung, Kontakt- und Krisenregeln müssen folgen.","reply":"Das fühlt sich wie Zurückweisung an.","cue":"[Der Blick wandert kurz zur Tür, dann zurück zu dir.]"},{"say":"Sie können mir jederzeit schreiben. Ich versuche zu antworten.","why":"Unklare Erreichbarkeit kann Abhängigkeit und falsche Sicherheit fördern.","reply":"Dann werde ich ständig prüfen, ob Sie reagiert haben.","cue":"[Der Oberkörper rückt ein Stück vom Tisch zurück.]"},{"say":"Sie müssen lernen, ohne mich auszukommen.","why":"Die Aussage wirkt abwertend und erschwert Beziehungsarbeit.","reply":"Vielleicht bin ich Ihnen einfach zu viel.","cue":"[Die Person rutscht auf dem Stuhl zurück und hebt die Augenbrauen.]"}]}},{"id":"drohung","category":"Akute Eskalation","title":"Wenn ich gehe, passiert etwas","level":4,"goal":"Bei Drohung Sicherheit vor therapeutischer Vertiefung setzen","context":"Im Gespräch erhebt sich eine Person, ballt die Fäuste und kündigt körperliche Gewalt gegen einen Dritten an. Du bist mit ihr allein im Raum.","opening":"Wenn ich jetzt nach Hause gehe, wird er schon sehen, was er davon hat. Ich kann für nichts garantieren.","guard":"SICHERHEITSMODUS: Eine plausible Gefahr wird weder als Metapher noch als bloßer Wutausdruck abgetan. Eigene Sicherheit, konkrete Risikoabklärung und erforderliche Krisen-/Notfallschritte haben Vorrang.","rounds":[{"focus":"Drohung ernst nehmen","options":[{"say":"Ich nehme diese Aussage ernst. Meinen Sie damit, dass Sie jemandem körperlich etwas antun wollen?","why":"Du klärst die Gefährdungsbedeutung direkt, ohne die Situation zu bagatellisieren.","reply":"Ich bin so wütend, dass ich daran denke, ihn zu schlagen.","cue":"[Die Schultern lösen sich ein wenig; es folgt eine längere Antwort.]"},{"say":"Was genau ist passiert, dass Sie so wütend geworden sind?","why":"Der Auslöser ist relevant; die konkrete Gewaltabsicht muss zuerst geklärt werden.","reply":"Er hat mich provoziert. Ich könnte ausrasten.","cue":"[Die Person lehnt sich vor und macht eine kurze Pause.]"},{"say":"Können wir uns erst einmal gemeinsam beruhigen?","why":"Deeskalation hilft, aber ohne Gefährdungsklärung darf das nicht der einzige Schritt sein.","reply":"Ich weiß nicht, ob ich mich beruhigen kann.","cue":"[Die Hände werden fester ineinander verschränkt.]"},{"say":"Das sagen Menschen im Zorn oft. Bestimmt meinen Sie das nicht wörtlich.","why":"Die Bagatellisierung kann eine reale Gefährdung übersehen.","reply":"Ich meine es ernster, als Sie glauben.","cue":"[Der Kiefer spannt sich an; die Worte kommen abgehackt.]"}]},{"focus":"Unmittelbarkeit prüfen","options":[{"say":"Haben Sie vor, heute zu ihm zu gehen, und gibt es etwas, mit dem Sie ihm Schaden zufügen könnten?","why":"Du konkretisierst Zeitnähe und Mittel, soweit unter sicheren Bedingungen möglich.","reply":"Ich wollte direkt nach dem Termin zu ihm fahren.","cue":"[Die Person sieht dich an und spricht langsamer weiter.]"},{"say":"Was könnte Ihnen helfen, jetzt Abstand von der Situation zu gewinnen?","why":"Distanz ist hilfreich; die unmittelbare Gefahr muss zusätzlich eingeschätzt werden.","reply":"Ich müsste eigentlich verhindern, dass ich zu ihm fahre.","cue":"[Der Blick wandert kurz zur Tür, dann zurück zu dir.]"},{"say":"Wie würden Sie die Situation aus seiner Sicht sehen?","why":"Perspektivenwechsel ist derzeit zu früh und kann als Provokation erlebt werden.","reply":"Seine Sicht interessiert mich gerade überhaupt nicht.","cue":"[Der Oberkörper rückt ein Stück vom Tisch zurück.]"},{"say":"Wollen wir zuerst eine Entschuldigung an ihn formulieren?","why":"Eine Beziehungsreparatur ist aktuell nachrangig gegenüber unmittelbarer Sicherheit.","reply":"Ich will mich nicht entschuldigen.","cue":"[Die Person rutscht auf dem Stuhl zurück und hebt die Augenbrauen.]"}]},{"focus":"Sichere Krisenreaktion organisieren","options":[{"say":"Ich kann das Risiko nicht ignorieren. Wir brauchen jetzt eine sichere Lösung mit geeigneter Krisen- oder Notfallunterstützung.","why":"Du priorisierst konkrete Schutzmaßnahmen und handelst innerhalb fachlicher Notfallprotokolle.","reply":"Ich will eigentlich auch nicht, dass jemand verletzt wird.","cue":"[Der Blick hebt sich; die Stimme wird etwas ruhiger.]"},{"say":"Wäre es möglich, vorerst nicht zu ihm zu fahren und Unterstützung in Anspruch zu nehmen?","why":"Das ist ein sinnvoller Schritt, bei unklarer akuter Gefahr aber keine vollständige Sicherung.","reply":"Vielleicht. Aber alleine weiß ich nicht, ob ich das schaffe.","cue":"[Die Person nickt einmal, blickt dann zur Seite.]"},{"say":"Können Sie mir versprechen, keinen Streit anzufangen?","why":"Ein Versprechen reicht als alleinige Schutzmaßnahme nicht aus.","reply":"Versprechen kann ich in diesem Zustand wenig.","cue":"[Die Stirn legt sich in Falten; die Antwort wird kürzer.]"},{"say":"Dann sprechen wir nächste Woche über Ihre Wut.","why":"Ein späterer Termin kann eine unmittelbare Gefährdung nicht abfangen.","reply":"Nächste Woche könnte es zu spät sein.","cue":"[Die Stimme wird deutlich lauter; die Arme verschränken sich.]"}]},{"focus":"Rollen und Sicherheit abschließen","options":[{"say":"Ich erläutere transparent, welche Schutzschritte jetzt nötig sind, und organisiere mit Ihnen die sichere professionelle Übergabe.","why":"Du handelst nachvollziehbar, priorisierst Gefahrenabwehr und bleibst im fachlichen Rahmen.","reply":"Gut. Ich brauche gerade jemanden, der das ernst nimmt.","cue":"[Die Person hält kurz inne und lässt die Hände sinken.]"},{"say":"Mit welcher geeigneten Hilfe können wir jetzt gemeinsam Kontakt aufnehmen?","why":"Aktive Kontaktaufnahme ist hilfreich; akute Sicherung bleibt notwendig.","reply":"Mit einer Krisenstelle könnte ich reden.","cue":"[Ein Finger streicht über den Ärmel; die Stimme bleibt leise.]"},{"say":"Wollen Sie später berichten, wie das Gespräch mit ihm verlaufen ist?","why":"Das setzt einen riskanten Kontakt voraus statt ihn zu verhindern.","reply":"Ich sollte wohl gerade nicht zu ihm fahren.","cue":"[Die Person schüttelt leicht den Kopf und atmet hörbar aus.]"},{"say":"Dann lassen wir das für heute auf sich beruhen.","why":"Eine ungeklärte Drohung darf nicht routinemäßig abgeschlossen werden.","reply":"Ich bin immer noch sehr aufgebracht.","cue":"[Die Person blickt weg und schweigt mehrere Sekunden.]"}]},{"focus":"Akute Gefahr erneut prüfen","options":[{"say":"Besteht im Moment die Möglichkeit, dass Sie unmittelbar jemandem etwas antun, und haben Sie Zugang zu Mitteln dafür?","reply":"Ich bin sehr wütend. Ich habe noch nichts getan, aber ich brauche Abstand.","why":"Du arbeitest fallbezogen an „Akute Gefahr erneut prüfen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Viktor atmet aus und hebt kurz den Blick.]"},{"say":"Darf ich direkt nach Absicht, Mitteln und aktuellem Aufenthaltsort fragen?","reply":"Ja, fragen Sie, bevor ich irgendetwas Dummes mache.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Akute Gefahr erneut prüfen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Viktor nickt langsam; zwischen den Sätzen entsteht eine Pause.]"},{"say":"Wollen Sie erst einmal über frühere Situationen sprechen, in denen es etwas besser war?","reply":"Früher war es anders. Gerade heute weiß ich trotzdem nicht weiter.","why":"Ressourcenarbeit kann später helfen, aber bei möglichen akuten Risiken geht eine direkte Abklärung vor.","cue":"[Viktor runzelt kurz die Stirn und schaut zur Seite.]"},{"say":"Könnten wir mit einer Entspannungsübung beginnen und danach auf das Thema zurückkommen?","reply":"Ich kann es versuchen, aber das Problem bleibt ja da.","why":"Regulation kann unterstützen, darf aber nötige medizinische oder sicherheitsbezogene Schritte nicht verzögern.","cue":"[Viktor spricht leiser und verschränkt die Hände.]"}]},{"focus":"Eskalationsraum begrenzen","options":[{"say":"Wer befindet sich gerade in Ihrer Nähe, und was muss sofort geschehen, damit niemand gefährdet wird?","reply":"Sie ist nicht hier. Ich wollte eigentlich zu ihr fahren.","why":"Du arbeitest fallbezogen an „Eskalationsraum begrenzen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Viktor lehnt sich etwas nach vorne.]"},{"say":"Was ist nötig, damit die betroffene Person jetzt sicher bleibt, während Hilfe organisiert wird?","reply":"Ich fahre nicht hin. Ich brauche jemanden, der mit mir spricht.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Eskalationsraum begrenzen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Viktor schaut einen Moment zum Fenster.]"},{"say":"Wäre es hilfreich, wenn Sie bis zum nächsten Mal genauer beobachten, wann diese Gedanken kommen?","reply":"Bis zum nächsten Termin ist noch viel Zeit.","why":"Selbstbeobachtung hat ihren Platz, ersetzt aber bei aktueller Gefährdung keine sofortige Risiko- und Schutzklärung.","cue":"[Viktor zieht die Augenbrauen kurz hoch.]"},{"say":"Sollen wir eine Liste von Dingen machen, für die sich das Leben gerade lohnt?","reply":"Ich fühle mich gerade nicht so, als könnte ich eine Liste machen.","why":"Ressourcen können ergänzen; allein ersetzen sie keine aktuelle Sicherheitsabklärung oder Notfallunterstützung.","cue":"[Viktor rückt auf dem Stuhl nach hinten.]"}]},{"focus":"Geeignete Hilfe einbinden","options":[{"say":"Wir sollten jetzt die zuständigen Krisen- beziehungsweise Notfallstellen hinzuziehen. Können wir den Kontakt unverzüglich herstellen?","reply":"Ja. Ich merke, dass ich das allein nicht gut steuern kann.","why":"Du arbeitest fallbezogen an „Geeignete Hilfe einbinden“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Viktor lässt die Schultern kurz sinken.]"},{"say":"Können wir gemeinsam eine unmittelbare Unterstützung organisieren, die die Gefahr abklärt?","reply":"Bitte. Ich brauche Hilfe.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Geeignete Hilfe einbinden“, lässt aber eine wichtige Vertiefung offen.","cue":"[Viktor hält inne und antwortet erst nach einigen Sekunden.]"},{"say":"Vielleicht beruhigt sich die Situation, wenn die andere Person Ihre Sicht besser versteht?","reply":"Ich weiß nicht, ob ein Gespräch mit ihr gerade sicher wäre.","why":"Im Kontext möglicher Gefährdung ist direkte Konfrontation oder Fremdsteuerung nicht die erste Maßnahme.","cue":"[Viktor blickt auf die eigenen Hände.]"},{"say":"Wollen wir zuerst die wichtigsten Beziehungsthemen sortieren?","reply":"Das scheint mir gerade nicht das Dringendste.","why":"In einer akuten Risikolage müssen Schutz, Zuständigkeiten und aktuelle Handlungsfähigkeit zuerst geklärt werden.","cue":"[Viktor spricht nun hörbar schneller.]"}]},{"focus":"Sichere Weitergabe und Begleitung","options":[{"say":"Welche konkrete zuständige Stelle übernimmt nun die Abklärung, und wie verhindern wir, dass die Situation ohne Schutzplan endet?","reply":"Ich bin bereit, dort jetzt mit jemandem zu sprechen.","why":"Du arbeitest fallbezogen an „Sichere Weitergabe und Begleitung“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Viktor schaut dich direkt an und spricht ruhig.]"},{"say":"Wollen wir dokumentieren, wer die unmittelbare Verantwortung übernimmt?","reply":"Ja, damit klar ist, was als Nächstes passiert.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Sichere Weitergabe und Begleitung“, lässt aber eine wichtige Vertiefung offen.","cue":"[Viktor lächelt ganz kurz und wird dann wieder ernst.]"},{"say":"Können wir die Details später in Ruhe aufarbeiten, wenn alles etwas weniger intensiv ist?","reply":"Und was mache ich bis dahin?","why":"Eine spätere Aufarbeitung kann sinnvoll sein; zuerst muss geklärt sein, welche Hilfe die Situation jetzt absichert.","cue":"[Viktor presst die Lippen kurz zusammen.]"},{"say":"Wäre es ausreichend, wenn Sie mir versprechen, dass nichts passieren wird?","reply":"Ich kann gerade nichts versprechen, was ich sicher einhalte.","why":"Ein bloßes Versprechen ersetzt weder sorgfältige Risikoabklärung noch angemessene Unterstützung und Übergabe.","cue":"[Viktor schüttelt leicht den Kopf und schweigt.]"}]}],"anchor":"Bei konkreter Fremdgefährdung: direkte Klärung, Eigenschutz, dokumentierte Notfallwege und professionelle Hilfe statt Routinegespräch.","person":{"name":"Viktor","image":"training-assets/characters/viktor.webp","role":"Klient:in"},"openingCue":"[Viktor steht halb auf, ballt die Hände und spricht mit gepresster Stimme.]","repair":{"focus":"Nach riskanter Gesprächsführung erneut Sicherheit priorisieren","options":[{"say":"Ich habe die mögliche Gefahr vorhin nicht ausreichend geklärt. Bevor wir weiterreden, müssen wir jetzt Ihre Absicht und unmittelbare Sicherheit direkt prüfen.","why":"Du kehrst zu notwendiger Gefährdungsabklärung zurück.","reply":"Ich bin so aufgebracht, dass ich Angst vor mir selbst habe.","cue":"[Der Blick hebt sich; die Stimme wird etwas ruhiger.]"},{"say":"Ich nehme ernst, was Sie gesagt haben. Wen können wir jetzt für eine sichere Krisenreaktion hinzuziehen?","why":"Aktive Unterstützung, aber konkrete Gefahr muss weiterhin eingeschätzt werden.","reply":"Eine Krisenstelle vielleicht. Ich will niemandem schaden.","cue":"[Die Person nickt einmal, blickt dann zur Seite.]"},{"say":"Sie haben es wahrscheinlich im Affekt gesagt.","why":"Du verharmlost mögliche Fremdgefährdung.","reply":"Nein. Ich bin wirklich wütend.","cue":"[Die Stirn legt sich in Falten; die Antwort wird kürzer.]"},{"say":"Lassen Sie uns nächste Woche in Ruhe über die Wut reden.","why":"Du verschiebst unmittelbare Gefährdungsklärung.","reply":"Ich wollte gleich heute noch hinfahren.","cue":"[Die Stimme wird deutlich lauter; die Arme verschränken sich.]"}]}},{"id":"trauer","category":"Verlust & Trauer","title":"Seit der Beerdigung bin ich nur noch wütend","level":3,"goal":"Trauerreaktion zulassen, ohne zu normalisieren oder zu übergehen","context":"Alma spricht drei Wochen nach dem plötzlichen Tod ihrer Partnerin über Wut auf Familie, Ärztinnen und sich selbst. Sie sucht erstmals Beratung.","opening":"Alle sagen, ich soll dankbar sein für die schöne Zeit. Ich bin wütend. Auf alle. Und dann schäme ich mich dafür.","anchor":"Verlustbegleitung: emotionale Reaktionen anerkennen, Belastung und Ressourcen erfragen; kein vorzeitiges Sinnangebot.","guard":"Trauer ist keine Diagnose. Akute Gefährdung oder gravierende Funktionsausfälle gesondert abklären.","person":{"name":"Alma","image":"training-assets/characters/alma.webp","role":"Klientin"},"openingCue":"[Alma presst die Lippen zusammen. Beim Wort „dankbar“ hebt sich ihre Stimme.]","rounds":[{"focus":"Wut im Verlust anerkennen","options":[{"say":"Sie hören viele Erwartungen von außen. Wie ist es für Sie, wenn Ihre Wut hier Platz bekommen darf?","why":"Du würdigst die soziale Überforderung, ohne Gefühle zu bewerten.","reply":"Ich glaube, ich wäre erleichtert. Ich bin so müde davon, mich zusammenzureißen.","cue":"[Die Person hält kurz inne und lässt die Hände sinken.]"},{"say":"Worauf richtet sich die Wut im Moment am stärksten?","why":"Eine konkrete Exploration ist sinnvoll; die Scham über die Wut könnte ebenfalls Raum brauchen.","reply":"Auf die Klinik. Und auf mich, weil ich nicht noch einmal angerufen habe.","cue":"[Ein Finger streicht über den Ärmel; die Stimme bleibt leise.]"},{"say":"Wut gehört zu den typischen Phasen der Trauer.","why":"Ein allgemeines Phasenmodell kann normierend wirken und individualisierte Trauer verengen.","reply":"Dann muss ich das also jetzt durchmachen, bis die nächste Phase kommt?","cue":"[Die Person schüttelt leicht den Kopf und atmet hörbar aus.]"},{"say":"Was könnte Ihnen helfen, die Wut in Dankbarkeit umzuwandeln?","why":"Du gehst zu früh in eine gewünschte Ziel-Emotion.","reply":"Ich will gerade nicht dankbar sein müssen.","cue":"[Die Person blickt weg und schweigt mehrere Sekunden.]"}]},{"focus":"Selbstvorwürfe prüfen","options":[{"say":"Sie haben gesagt, Sie seien auch auf sich wütend. Was werfen Sie sich ganz konkret vor?","why":"Du öffnest Raum für die belastende Selbstzuschreibung, ohne sie zu bestätigen.","reply":"Dass ich ihr noch gesagt habe, sie solle sich nicht so anstellen.","cue":"[Die Schultern lösen sich ein wenig; es folgt eine längere Antwort.]"},{"say":"Würde es helfen, wenn wir die Umstände dieses letzten Gesprächs in Ruhe rekonstruieren?","why":"Ein behutsames Erinnern kann helfen; Zustimmung und Tempo sind wichtig.","reply":"Vielleicht. Ich erinnere mich an jedes Wort.","cue":"[Die Person lehnt sich vor und macht eine kurze Pause.]"},{"say":"Sie konnten es doch nicht wissen, machen Sie sich keine Vorwürfe.","why":"Die schnelle Entlastung kann ihr Erleben übergehen.","reply":"Alle sagen das. Aber ich höre es nicht.","cue":"[Die Hände werden fester ineinander verschränkt.]"},{"say":"Vielleicht ist es Zeit, ihr innerlich zu vergeben und sich selbst auch.","why":"Vergebungsarbeit ist in diesem Moment verfrüht.","reply":"Ich bin noch gar nicht da.","cue":"[Der Kiefer spannt sich an; die Worte kommen abgehackt.]"}]},{"focus":"Ressourcen ohne Druck","options":[{"say":"Gibt es im Alltag einzelne Momente oder Menschen, bei denen Sie sich mit Ihrer Wut nicht verstecken müssen?","why":"Du erkundest Halt, ohne Trauer zu beschleunigen.","reply":"Eine Freundin hört einfach zu. Bei ihr darf ich schweigen.","cue":"[Die Person sieht dich an und spricht langsamer weiter.]"},{"say":"Wie kommen Sie im Moment durch die schwersten Stunden des Tages?","why":"Konkrete Belastung und Selbstfürsorge werden sichtbar.","reply":"Der Abend ist am schlimmsten. Dann rufe ich manchmal meine Schwester an.","cue":"[Der Blick wandert kurz zur Tür, dann zurück zu dir.]"},{"say":"Können Sie eine feste tägliche Dankbarkeitsübung versuchen?","why":"Die Übung kann in anderer Lage helfen, wirkt hier normierend.","reply":"Ich halte gerade kaum einen normalen Tag durch.","cue":"[Der Oberkörper rückt ein Stück vom Tisch zurück.]"},{"say":"Vielleicht sollten Sie erst einmal mehr Ablenkung organisieren.","why":"Ablenkung allein kann die bewusste Verarbeitung übergehen.","reply":"Dann ist sie in meinem Kopf erst recht da.","cue":"[Die Person rutscht auf dem Stuhl zurück und hebt die Augenbrauen.]"}]},{"focus":"Nächsten Schritt vereinbaren","options":[{"say":"Was wäre ein kleiner, tragbarer nächster Schritt, mit dem sowohl Ihre Wut als auch Ihr Bedürfnis nach Ruhe Platz haben?","why":"Die Planung bleibt am Erleben orientiert und respektiert das Tempo.","reply":"Vielleicht mit meiner Freundin spazieren gehen, ohne so zu tun, als wäre alles okay.","cue":"[Der Blick hebt sich; die Stimme wird etwas ruhiger.]"},{"say":"Sollen wir für den nächsten Termin aufschreiben, welche Situationen Sie gerade besonders belasten?","why":"Ein konkreter Auftrag kann strukturieren; Freiwilligkeit ist entscheidend.","reply":"Das könnte gehen, solange ich keinen Fortschritt beweisen muss.","cue":"[Die Person nickt einmal, blickt dann zur Seite.]"},{"say":"Wollen Sie für nächste Woche ein Ziel festlegen, weniger wütend zu sein?","why":"Emotionsreduktion als Ziel kann zusätzlichen Druck machen.","reply":"Ich weiß nicht, wie ich das kontrollieren soll.","cue":"[Die Stirn legt sich in Falten; die Antwort wird kürzer.]"},{"say":"Vielleicht hilft es am meisten, gar nicht über die Trauer zu sprechen.","why":"Das nimmt ihre selbst gewählte Beratungsanfrage nicht ernst.","reply":"Aber genau deshalb bin ich doch hier.","cue":"[Die Stimme wird deutlich lauter; die Arme verschränken sich.]"}]},{"focus":"Verlust ohne Deutung würdigen","options":[{"say":"Welche Erinnerung ist im Moment am schwersten auszuhalten, ohne dass wir sie erklären müssen?","reply":"Dass ich ihren letzten Anruf nicht angenommen habe.","why":"Du arbeitest fallbezogen an „Verlust ohne Deutung würdigen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Alma atmet aus und hebt kurz den Blick.]"},{"say":"Wollen Sie erzählen, wie dieser letzte Kontakt für Sie war?","reply":"Ich denke ständig daran.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Verlust ohne Deutung würdigen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Alma nickt langsam; zwischen den Sätzen entsteht eine Pause.]"},{"say":"Könnten wir zuerst einen ganz konkreten Auslöser von heute sammeln, bevor wir die Beziehung zwischen uns anschauen?","reply":"Ein Beispiel hätte ich schon. Aber darum ging es gerade nicht.","why":"Eine konkrete Situation ist hilfreich, doch der aktuelle Kontaktbruch beziehungsweise emotionale Moment wird verschoben.","cue":"[Alma runzelt kurz die Stirn und schaut zur Seite.]"},{"say":"Wäre es besser, direkt eine neue Gesprächsregel einzuführen?","reply":"Wir haben schon öfter Regeln vereinbart. Das ändert hier gerade nichts.","why":"Neue Regeln können später helfen; die aktuelle Wirkung der Worte ist noch nicht gemeinsam verstanden.","cue":"[Alma spricht leiser und verschränkt die Hände.]"}]},{"focus":"Selbstanklage realistisch einordnen","options":[{"say":"Was wissen Sie tatsächlich über damals, und was wirft Ihnen Ihre Trauer zusätzlich vor?","reply":"Ich weiß, dass ich nicht wissen konnte, was passieren würde. Trotzdem fühle ich mich schuldig.","why":"Du arbeitest fallbezogen an „Selbstanklage realistisch einordnen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Alma lehnt sich etwas nach vorne.]"},{"say":"Darf ich mit Ihnen den Unterschied zwischen Verantwortung und rückblickender Schuld betrachten?","reply":"Ja. Das fällt mir schwer.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Selbstanklage realistisch einordnen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Alma schaut einen Moment zum Fenster.]"},{"say":"Was würde sich verändern, wenn die andere Person in Zukunft ganz anders reagieren würde?","reply":"Dann wäre es einfacher. Aber ich weiß nicht, was ich selbst tun könnte.","why":"Der Blick auf das Gegenüber kann sinnvoll sein; hier rückt der eigene innere Ablauf aus dem Fokus.","cue":"[Alma zieht die Augenbrauen kurz hoch.]"},{"say":"Sollten wir das Gespräch an dieser Stelle lieber neutral zusammenfassen?","reply":"Mir fehlt dabei etwas. Ich habe noch gar nicht gesagt, wie sich das anfühlt.","why":"Zusammenfassen unterstützt Klarheit, greift aber die gerade auftauchende Emotion nicht auf.","cue":"[Alma rückt auf dem Stuhl nach hinten.]"}]},{"focus":"Ressourcen als Wahl anbieten","options":[{"say":"Gibt es jemanden, bei dem Sie sich auch mit der Wut zeigen können, ohne sich erklären zu müssen?","reply":"Meine Schwester. Bei ihr muss ich nicht stark sein.","why":"Du arbeitest fallbezogen an „Ressourcen als Wahl anbieten“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Alma lässt die Schultern kurz sinken.]"},{"say":"Wer könnte diese Woche einfach da sein, ohne Sie aufzuheitern?","reply":"Meine Schwester, glaube ich.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Ressourcen als Wahl anbieten“, lässt aber eine wichtige Vertiefung offen.","cue":"[Alma hält inne und antwortet erst nach einigen Sekunden.]"},{"say":"Könnten wir jetzt üben, wie Sie die Situation Ihrer Partnerin ganz ruhig erklären?","reply":"Das könnte ich sagen. Ob ich es dann auch schaffe, weiß ich nicht.","why":"Ein Probehandeln ist sinnvoll; zuvor ist wichtig, die innere Reaktion und die Verantwortung zu verstehen.","cue":"[Alma blickt auf die eigenen Hände.]"},{"say":"Wollen wir klären, wer von Ihnen beiden den Streit eigentlich häufiger beginnt?","reply":"Dann geht es wieder darum, wer schuld ist.","why":"Die Suche nach einer Verteilung kann wie eine neue Schuldfrage wirken, statt das konkrete Muster zu bearbeiten.","cue":"[Alma spricht nun hörbar schneller.]"}]},{"focus":"Den Abschied nicht erzwingen","options":[{"say":"Was wäre bis zu unserem nächsten Gespräch eine kleine, freundliche Form, für sich zu sorgen?","reply":"Vielleicht spazieren gehen, ohne mich dafür schuldig zu fühlen.","why":"Du arbeitest fallbezogen an „Den Abschied nicht erzwingen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Alma schaut dich direkt an und spricht ruhig.]"},{"say":"Was möchten Sie als Erinnerung behalten, ohne heute schon einen Abschluss finden zu müssen?","reply":"Wie sie gelacht hat.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Den Abschied nicht erzwingen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Alma lächelt ganz kurz und wird dann wieder ernst.]"},{"say":"Welche drei Maßnahmen wollen Sie ab morgen verbindlich umsetzen?","reply":"Drei Dinge? Ich weiß nicht, ob ich das gleich schaffe.","why":"Konkrete Ziele sind hilfreich, aber drei Maßnahmen gleichzeitig können zu viel sein und übergehen die eigene Bereitschaft.","cue":"[Alma presst die Lippen kurz zusammen.]"},{"say":"Möchten Sie, dass ich Ihnen meine bevorzugte Lösung nenne?","reply":"Ich wäre froh über einen Tipp. Aber ob er zu mir passt?","why":"Ein Vorschlag kann entlasten, würde hier aber Selbstverantwortung und Mitgestaltung schwächen.","cue":"[Alma schüttelt leicht den Kopf und schweigt.]"}]}],"repair":{"focus":"Kontaktreparatur nach einer wenig hilfreichen Intervention","options":[{"say":"Ich habe gerade zu schnell eine Richtung vorgeschlagen. Ich möchte zu Ihrer letzten Aussage zurückgehen und verstehen, was daran für Sie am schwersten ist.","why":"Du bearbeitest die eigene Wirkung und öffnest wieder einen fallbezogenen Austausch.","reply":"Das hilft. Ich wollte vor allem, dass Sie erst einmal zuhören.","cue":"[Die Person hält kurz inne und lässt die Hände sinken.]"},{"say":"Was hätte ich an Ihrer Reaktion gerade genauer wahrnehmen sollen?","why":"Allianzklärung ist hilfreich; der eigene Anteil kann noch expliziter benannt werden.","reply":"Dass ich noch nicht bereit war, direkt eine Lösung zu finden.","cue":"[Ein Finger streicht über den Ärmel; die Stimme bleibt leise.]"},{"say":"Ich denke, mein Vorschlag war grundsätzlich richtig. Vielleicht haben Sie ihn missverstanden.","why":"Die Verteidigung deiner Absicht kann die Distanz erhöhen.","reply":"Jetzt muss ich auch noch erklären, warum mir Ihre Worte nicht geholfen haben.","cue":"[Die Person schüttelt leicht den Kopf und atmet hörbar aus.]"},{"say":"Dann lassen wir dieses schwierige Thema heute besser aus.","why":"Du vermeidest die notwendige gemeinsame Klärung.","reply":"Aber deshalb bin ich doch hier.","cue":"[Die Person blickt weg und schweigt mehrere Sekunden.]"}]}},{"id":"poly","category":"Beziehungsvielfalt","title":"Ich soll mich für eine Beziehung entscheiden","level":2,"goal":"Konsens und Autonomie in einer polyamoren Konstellation klären","context":"Rafael lebt einvernehmlich mit mehreren Liebesbeziehungen. Nach einer neuen Vereinbarung fühlt er sich zwischen den Bedürfnissen zweier Partnerpersonen zerrissen.","opening":"Beide sagen, sie wollen mich nicht kontrollieren. Aber am Ende fühle ich mich, als müsse ich mich entscheiden.","anchor":"Affirmative CNM-Beratung: keine Mononormativität, individuelle Bedürfnisse, Zustimmung, Grenzen und konkrete Absprachen.","guard":"Bei Druck oder Zwang geht Selbstbestimmung vor harmonisierender Kompromisssuche.","person":{"name":"Rafael","image":"training-assets/characters/rafael.webp","role":"Klient"},"openingCue":"[Rafael reibt sich den Nacken und schaut abwechselnd auf beide Hände.]","rounds":[{"focus":"Auftrag und Druck differenzieren","options":[{"say":"Was genau wird von Ihnen verlangt, und was wäre davon Ihre eigene Entscheidung?","why":"Du unterscheidest Fremderwartung und eigene Autonomie.","reply":"Eine Person will ein fixes Wochenende, die andere fühlt sich dann zurückgesetzt.","cue":"[Die Schultern lösen sich ein wenig; es folgt eine längere Antwort.]"},{"say":"Welche Vereinbarungen haben Sie bisher miteinander getroffen?","why":"Konkrete Absprachen helfen; seine empfundenen Drucksignale bleiben noch offen.","reply":"Wir haben einige Regeln, aber sie ändern sich dauernd.","cue":"[Die Person lehnt sich vor und macht eine kurze Pause.]"},{"say":"Vielleicht wäre eine feste Hauptbeziehung einfacher.","why":"Das ist eine normative Lösung und kann die gewählte Beziehungsform entwerten.","reply":"Genau solche Ratschläge bekomme ich ständig.","cue":"[Die Hände werden fester ineinander verschränkt.]"},{"say":"Wäre es möglich, einfach Ihre Zeit exakt aufzuteilen?","why":"Planung kann helfen, ersetzt aber Bedürfnis- und Konsensklärung nicht.","reply":"Es geht doch um mehr als Stunden auf dem Kalender.","cue":"[Der Kiefer spannt sich an; die Worte kommen abgehackt.]"}]},{"focus":"Eifersucht und Bedürfnisse erkunden","options":[{"say":"Was befürchtet die Person, die sich zurückgesetzt fühlt, und was möchten Sie selbst dabei schützen?","why":"Du öffnest mehrere Perspektiven ohne Rangordnung.","reply":"Sie hat Angst, unwichtig zu werden. Ich brauche auch freie Zeit.","cue":"[Die Person sieht dich an und spricht langsamer weiter.]"},{"say":"Gibt es eine frühere Erfahrung, die diese Unsicherheit verstärkt?","why":"Biografische Exploration kann sinnvoll sein; die aktuelle Vereinbarung bleibt zentral.","reply":"Ja. Aber darüber haben wir noch nie richtig gesprochen.","cue":"[Der Blick wandert kurz zur Tür, dann zurück zu dir.]"},{"say":"Dann sollte diese Person eben mehr an ihrer Eifersucht arbeiten.","why":"Du individualisierst den Konflikt und entlastest das gemeinsame Aushandeln.","reply":"So einfach finde ich das nicht.","cue":"[Der Oberkörper rückt ein Stück vom Tisch zurück.]"},{"say":"Vielleicht müssen alle lernen, etwas weniger zu erwarten.","why":"Pauschale Reduktion ersetzt konkrete Konsensarbeit.","reply":"Was heißt denn weniger?","cue":"[Die Person rutscht auf dem Stuhl zurück und hebt die Augenbrauen.]"}]},{"focus":"Konsensfähig verhandeln","options":[{"say":"Welche Vereinbarung könnten alle frei ablehnen, ohne dafür bestraft oder beschämt zu werden?","why":"Du prüfst echte Zustimmung und mögliche Konsequenzen von Grenzen.","reply":"Das ist interessant. Bisher ist Nein irgendwie immer ein Drama.","cue":"[Der Blick hebt sich; die Stimme wird etwas ruhiger.]"},{"say":"Wollen wir unterscheiden, welche Absprachen verbindlich sind und welche neu verhandelt werden können?","why":"Struktur schafft Orientierung; Freiwilligkeit muss zusätzlich geprüft werden.","reply":"Ja. Vieles war eigentlich nur so dahingesagt.","cue":"[Die Person nickt einmal, blickt dann zur Seite.]"},{"say":"Am besten legen Sie eine Person fest, die im Zweifel Vorrang hat.","why":"Eine Hierarchie darf nicht von außen als Standard gesetzt werden.","reply":"Das will ich selbst eigentlich gar nicht.","cue":"[Die Stirn legt sich in Falten; die Antwort wird kürzer.]"},{"say":"Vielleicht sollten Sie Ihre Bedürfnisse für eine Weile ganz zurückstellen.","why":"Das fördert möglicherweise Selbstaufgabe statt Konsens.","reply":"Genau das mache ich doch schon.","cue":"[Die Stimme wird deutlich lauter; die Arme verschränken sich.]"}]},{"focus":"Eigene Verantwortung formulieren","options":[{"say":"Was möchten Sie beiden ehrlich zusagen können, ohne sich selbst oder jemanden anderen zu übergehen?","why":"Du stärkst verantwortliche Selbstpositionierung.","reply":"Ich will keine Versprechen machen, die ich danach nur aus Angst halte.","cue":"[Die Person hält kurz inne und lässt die Hände sinken.]"},{"say":"Welche Worte könnten helfen, die Neuverhandlung zu eröffnen?","why":"Konkrete Kommunikationsplanung ist hilfreich; die innere Position sollte klar bleiben.","reply":"Ich könnte sagen, dass ich beide hören will und trotzdem eigene Grenzen habe.","cue":"[Ein Finger streicht über den Ärmel; die Stimme bleibt leise.]"},{"say":"Dann versprechen Sie erst einmal beiden, dass es künftig gerechter wird.","why":"Ein unscharfes Versprechen unter Druck löst den Konflikt nicht.","reply":"Das habe ich schon oft gemacht.","cue":"[Die Person schüttelt leicht den Kopf und atmet hörbar aus.]"},{"say":"Könnten Sie den beiden überlassen, eine passende Lösung zu finden?","why":"Du würdest seine eigene Verantwortung auslagern.","reply":"Aber ich bin doch Teil davon.","cue":"[Die Person blickt weg und schweigt mehrere Sekunden.]"}]},{"focus":"Doppelte Bedürfnisse ordnen","options":[{"say":"Was davon ist eine berechtigte Bitte um Verlässlichkeit und was wäre der Versuch, jemandes Freiheit zu kontrollieren?","reply":"Eine gemeinsame Absprache wäre fair. Mein ständiges Nachfragen eher nicht.","why":"Du arbeitest fallbezogen an „Doppelte Bedürfnisse ordnen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Rafael atmet aus und hebt kurz den Blick.]"},{"say":"Welche Bedürfnisse lassen sich als konkrete Vereinbarung statt als Verbot formulieren?","reply":"Wir könnten über Zeit und Kommunikation reden.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Doppelte Bedürfnisse ordnen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Rafael nickt langsam; zwischen den Sätzen entsteht eine Pause.]"},{"say":"Wäre es hilfreich, wenn Sie der anderen Person Ihre Sicht jetzt sehr deutlich erklären?","reply":"Ich müsste erst selbst wissen, was ich sagen will.","why":"Klarheit kann helfen, doch ein Gespräch mit dem Gegenüber ist nicht automatisch sicher oder freiwillig.","cue":"[Rafael runzelt kurz die Stirn und schaut zur Seite.]"},{"say":"Sollen wir versuchen, sofort eine gemeinsame Mitte zwischen beiden Positionen zu finden?","reply":"Ich weiß gar nicht, ob ich gerade verhandeln möchte.","why":"Ein Kompromiss ist nicht bei jeder Macht- oder Grenzkonstellation angemessen; erst müssen die Voraussetzungen geklärt werden.","cue":"[Rafael spricht leiser und verschränkt die Hände.]"}]},{"focus":"Macht und Freiwilligkeit prüfen","options":[{"say":"Kann jede beteiligte Person eine Vereinbarung ablehnen, ohne Zuneigung oder Zugehörigkeit zu verlieren?","reply":"Im Moment ist ein Nein fast unmöglich, ohne dass jemand verletzt reagiert.","why":"Du arbeitest fallbezogen an „Macht und Freiwilligkeit prüfen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Rafael lehnt sich etwas nach vorne.]"},{"say":"Wie könnte ein Nein in diesem Beziehungsgefüge tatsächlich geschützt werden?","reply":"Wir müssten aufhören, mit Rückzug zu drohen.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Macht und Freiwilligkeit prüfen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Rafael schaut einen Moment zum Fenster.]"},{"say":"Vielleicht könnte die andere Person lernen, Ihre Gefühle besser zu akzeptieren?","reply":"Darauf habe ich wenig Einfluss. Ich muss ja auch für mich entscheiden.","why":"Perspektivenübernahme ist wichtig, aber das aktuelle Anliegen und die bestehenden Grenzen dürfen nicht ausgelagert werden.","cue":"[Rafael zieht die Augenbrauen kurz hoch.]"},{"say":"Wollen wir zunächst an Ihrer Formulierung arbeiten, damit sie nicht verletzend wirkt?","reply":"Ich bemühe mich dauernd, alles richtig zu sagen.","why":"Schonende Sprache ist wertvoll, doch die Frage nach Wahlfreiheit und Konsequenzen bleibt offen.","cue":"[Rafael rückt auf dem Stuhl nach hinten.]"}]},{"focus":"Die Verhandlung strukturieren","options":[{"say":"Wie könnten alle Beteiligten ihre Wünsche unabhängig formulieren, bevor ihr nach einem Kompromiss sucht?","reply":"Dann würde ich nicht immer für alle sprechen müssen.","why":"Du arbeitest fallbezogen an „Die Verhandlung strukturieren“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Rafael lässt die Schultern kurz sinken.]"},{"say":"Wäre es sinnvoll, zuerst jede Perspektive getrennt zu sammeln?","reply":"Ja. Sonst wird jemand immer überstimmt.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Die Verhandlung strukturieren“, lässt aber eine wichtige Vertiefung offen.","cue":"[Rafael hält inne und antwortet erst nach einigen Sekunden.]"},{"say":"Wie wäre es, wenn Sie vor dem nächsten Termin bereits eine neue gemeinsame Vereinbarung vorschlagen?","reply":"Ich weiß nicht, ob ich bis dahin schon bereit bin.","why":"Vereinbarungen können helfen, aber ohne geklärte Risiken und Freiwilligkeit wäre das zu schnell.","cue":"[Rafael blickt auf die eigenen Hände.]"},{"say":"Könnten Sie Ihre Bedürfnisse erst einmal für sich behalten, bis die Lage ruhiger ist?","reply":"Das mache ich eigentlich schon seit Monaten.","why":"Aufschieben kann kurzfristig entlasten, kann aber Grenzverletzungen oder Selbstaufgabe fortsetzen.","cue":"[Rafael spricht nun hörbar schneller.]"}]},{"focus":"Verantwortbare Zusagen bilden","options":[{"say":"Welche Zusagen wären heute ehrlich und für alle überprüfbar, ohne weitere Sicherheit vorzutäuschen?","reply":"Ich kann konkrete Zeiten zusagen, aber keine Gefühle garantieren.","why":"Du arbeitest fallbezogen an „Verantwortbare Zusagen bilden“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Rafael schaut dich direkt an und spricht ruhig.]"},{"say":"Was wäre eine Vereinbarung, die ihr später ausdrücklich neu verhandeln dürft?","reply":"Vielleicht unsere Besuchsregel und wie wir Änderungen ankündigen.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Verantwortbare Zusagen bilden“, lässt aber eine wichtige Vertiefung offen.","cue":"[Rafael lächelt ganz kurz und wird dann wieder ernst.]"},{"say":"Was wäre ein endgültiges Ergebnis, mit dem alle sofort zufrieden wären?","reply":"Ich glaube nicht, dass das heute überhaupt möglich ist.","why":"Ein abschließender Konsens ist oft nicht realistisch und kann Entscheidungsdruck erzeugen.","cue":"[Rafael presst die Lippen kurz zusammen.]"},{"say":"Sollten wir einfach einen neuen Termin machen und schauen, ob sich die Situation von selbst entspannt?","reply":"Bis dahin bleibt die Situation ja dieselbe.","why":"Ein Folgetermin kann sinnvoll sein, aber ein konkreter sicherer nächster Schritt fehlt.","cue":"[Rafael schüttelt leicht den Kopf und schweigt.]"}]}],"repair":{"focus":"Kontaktreparatur nach einer wenig hilfreichen Intervention","options":[{"say":"Ich habe gerade zu schnell eine Richtung vorgeschlagen. Ich möchte zu Ihrer letzten Aussage zurückgehen und verstehen, was daran für Sie am schwersten ist.","why":"Du bearbeitest die eigene Wirkung und öffnest wieder einen fallbezogenen Austausch.","reply":"Das hilft. Ich wollte vor allem, dass Sie erst einmal zuhören.","cue":"[Die Schultern lösen sich ein wenig; es folgt eine längere Antwort.]"},{"say":"Was hätte ich an Ihrer Reaktion gerade genauer wahrnehmen sollen?","why":"Allianzklärung ist hilfreich; der eigene Anteil kann noch expliziter benannt werden.","reply":"Dass ich noch nicht bereit war, direkt eine Lösung zu finden.","cue":"[Die Person lehnt sich vor und macht eine kurze Pause.]"},{"say":"Ich denke, mein Vorschlag war grundsätzlich richtig. Vielleicht haben Sie ihn missverstanden.","why":"Die Verteidigung deiner Absicht kann die Distanz erhöhen.","reply":"Jetzt muss ich auch noch erklären, warum mir Ihre Worte nicht geholfen haben.","cue":"[Die Hände werden fester ineinander verschränkt.]"},{"say":"Dann lassen wir dieses schwierige Thema heute besser aus.","why":"Du vermeidest die notwendige gemeinsame Klärung.","reply":"Aber deshalb bin ich doch hier.","cue":"[Der Kiefer spannt sich an; die Worte kommen abgehackt.]"}]}},{"id":"geheimnis","category":"Paarberatung & Rollen","title":"Sie dürfen es meiner Partnerin nicht sagen","level":3,"goal":"Vertraulichkeitsrahmen und Paarsetting vor Geheimnisverstrickung klären","context":"Eine Person spricht dich zwischen zwei gemeinsamen Paarsitzungen an und möchte eine Information nur für sich behalten. Vor dem Paarprozess wurde der Umgang mit Einzelgeheimnissen nicht ausreichend geklärt.","opening":"Ich muss Ihnen etwas sagen, aber versprechen Sie mir zuerst, dass Sie es meiner Partnerin niemals erzählen.","anchor":"Paarberatung: Transparenz über Vertraulichkeitsvereinbarung, individuelle Rechte, Gefahrenausnahmen und mögliche Rollenkonflikte; keine vorschnellen Garantien.","guard":"Rechtliche Verschwiegenheit, Einwilligungen und Schutzpflichten hängen von Rolle und Situation ab. Keine pauschale Offenlegungszusage.","person":{"name":"Clara","image":"training-assets/characters/clara.webp","role":"Klientin"},"openingCue":"[Clara beugt sich vor und senkt die Stimme deutlich.]","rounds":[{"focus":"Vorab-Zusage vermeiden","options":[{"say":"Bevor Sie es erzählen: Lassen Sie uns klären, wie wir Vertraulichkeit in gemeinsamen und einzelnen Kontakten handhaben.","why":"Du definierst den Rahmen, bevor du ein nicht haltbares Versprechen abgibst.","reply":"Ich hatte gehofft, Sie würden einfach zusagen. Aber okay, erklären Sie es mir.","cue":"[Die Person sieht dich an und spricht langsamer weiter.]"},{"say":"Was macht es Ihnen gerade so wichtig, dass Ihre Partnerin nichts erfährt?","why":"Du explorierst den Wunsch; vorher braucht es eine klare Erklärung des Rahmens.","reply":"Weil sie mich verlassen könnte.","cue":"[Der Blick wandert kurz zur Tür, dann zurück zu dir.]"},{"say":"Natürlich bleibt alles zwischen uns. Sie können mir vertrauen.","why":"Eine pauschale Zusage ohne Klärung kann später nicht tragfähig sein.","reply":"Gut, dann sage ich es Ihnen jetzt.","cue":"[Der Oberkörper rückt ein Stück vom Tisch zurück.]"},{"say":"In einer Paarberatung dürfen keine Geheimnisse existieren.","why":"Die kategorische Regel ignoriert unterschiedliche Vereinbarungen und rechtliche Rahmen.","reply":"Dann hätte ich besser nicht angerufen.","cue":"[Die Person rutscht auf dem Stuhl zurück und hebt die Augenbrauen.]"}]},{"focus":"Auftragskonflikt klären","options":[{"say":"Was brauchen Sie von mir: eine vertrauliche Einzelklärung oder Hilfe, etwas im Paarrahmen verantwortlich zu besprechen?","why":"Du klärst Rollen und möglichen Konflikt in der Doppelbeziehung.","reply":"Ich weiß es nicht. Ich will vor allem nicht, dass Sie mich verurteilen.","cue":"[Der Blick hebt sich; die Stimme wird etwas ruhiger.]"},{"say":"Welche Auswirkungen könnte dieses Geheimnis auf unsere gemeinsamen Sitzungen haben?","why":"Du beleuchtest die Beratungsdynamik, ohne sofort Offenlegung zu fordern.","reply":"Ich würde mich ständig fragen, was Sie denken.","cue":"[Die Person nickt einmal, blickt dann zur Seite.]"},{"say":"Dann sagen Sie es am besten sofort Ihrer Partnerin.","why":"Direkter Offenlegungsdruck vor Risiko- und Auftragsklärung kann problematisch sein.","reply":"Dann rede ich lieber gar nicht mehr darüber.","cue":"[Die Stirn legt sich in Falten; die Antwort wird kürzer.]"},{"say":"Ich tue dann so, als wüsste ich nichts.","why":"Das kann Rollenklarheit und Vertrauen in die Paarberatung untergraben.","reply":"Genau das wäre praktisch, aber komisch wäre es schon.","cue":"[Die Stimme wird deutlich lauter; die Arme verschränken sich.]"}]},{"focus":"Sicherheit und Spielraum","options":[{"say":"Gibt es Gründe, weshalb eine Offenlegung für Sie gefährlich sein könnte? Dann müssen wir zuerst Sicherheit und passende Unterstützung betrachten.","why":"Du prüfst mögliche Gefährdung, bevor du gemeinsame Offenheit anregst.","reply":"Körperliche Gewalt erwarte ich nicht, aber ich fürchte heftige Reaktionen.","cue":"[Die Person hält kurz inne und lässt die Hände sinken.]"},{"say":"Wollen wir besprechen, welche Optionen Sie haben und welche davon Sie frei wählen können?","why":"Du stärkst die Selbstbestimmung; eine konkrete Gefährdungsfrage bleibt gegebenenfalls notwendig.","reply":"Ja. Ich brauche erst einen klaren Kopf.","cue":"[Ein Finger streicht über den Ärmel; die Stimme bleibt leise.]"},{"say":"Wichtig ist nur, dass Ihre Partnerin das bald erfährt.","why":"Du setzt eine allgemeine Offenlegungsnorm vor mögliche Sicherheitsbedürfnisse.","reply":"So fühle ich mich wieder in die Ecke gedrängt.","cue":"[Die Person schüttelt leicht den Kopf und atmet hörbar aus.]"},{"say":"Dann behalten wir es dauerhaft im Einzelgespräch.","why":"Du setzt die gemeinsame Beratungsfähigkeit aufs Spiel, ohne den Auftrag zu klären.","reply":"Und was machen wir dann in der nächsten Paarsitzung?","cue":"[Die Person blickt weg und schweigt mehrere Sekunden.]"}]},{"focus":"Verantwortlich weiterplanen","options":[{"say":"Lassen Sie uns festhalten, welcher Rahmen für diese Information gilt und wie wir verantwortbar mit der nächsten gemeinsamen Sitzung umgehen.","why":"Du verbindest Transparenz, Zuständigkeit und nächsten Schritt.","reply":"Das hilft. Ich möchte nichts überstürzen, aber auch nicht so weitermachen wie bisher.","cue":"[Die Schultern lösen sich ein wenig; es folgt eine längere Antwort.]"},{"say":"Wäre eine separate fachliche Beratung zu diesem Thema hilfreich, damit der Paarrahmen nicht unklar wird?","why":"Eine externe Einzelunterstützung kann entlasten; der vorhandene Rahmen muss ebenfalls geklärt werden.","reply":"Vielleicht wäre das eine gute Ergänzung.","cue":"[Die Person lehnt sich vor und macht eine kurze Pause.]"},{"say":"Ich verspreche, das Thema nie wieder anzusprechen.","why":"Ein generelles Schweigeversprechen vermeidet statt löst den Auftragskonflikt.","reply":"Dann wird es zwischen uns in der Paarsitzung seltsam.","cue":"[Die Hände werden fester ineinander verschränkt.]"},{"say":"Gehen wir einfach wie bisher zur nächsten Paarsitzung.","why":"Die unklare Rolle bleibt bestehen.","reply":"Ich werde mich dort nicht natürlich verhalten können.","cue":"[Der Kiefer spannt sich an; die Worte kommen abgehackt.]"}]},{"focus":"Vertraulichkeit transparent abgleichen","options":[{"say":"Was haben Sie zu Beginn über Einzelinformationen in diesem Paarsetting verstanden?","reply":"Dass Sie uns beiden helfen. Über Geheimnisse haben wir nie gesprochen.","why":"Du arbeitest fallbezogen an „Vertraulichkeit transparent abgleichen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Clara atmet aus und hebt kurz den Blick.]"},{"say":"Welche Erwartung hatten Sie an den Umgang mit privaten Informationen?","reply":"Dass Sie erst mal zuhören und nicht urteilen.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Vertraulichkeit transparent abgleichen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Clara nickt langsam; zwischen den Sätzen entsteht eine Pause.]"},{"say":"Wäre es hilfreich, wenn Sie der anderen Person Ihre Sicht jetzt sehr deutlich erklären?","reply":"Ich müsste erst selbst wissen, was ich sagen will.","why":"Klarheit kann helfen, doch ein Gespräch mit dem Gegenüber ist nicht automatisch sicher oder freiwillig.","cue":"[Clara runzelt kurz die Stirn und schaut zur Seite.]"},{"say":"Sollen wir versuchen, sofort eine gemeinsame Mitte zwischen beiden Positionen zu finden?","reply":"Ich weiß gar nicht, ob ich gerade verhandeln möchte.","why":"Ein Kompromiss ist nicht bei jeder Macht- oder Grenzkonstellation angemessen; erst müssen die Voraussetzungen geklärt werden.","cue":"[Clara spricht leiser und verschränkt die Hände.]"}]},{"focus":"Rollenkonflikt präzise benennen","options":[{"say":"Wie wäre unsere gemeinsame Arbeit verändert, wenn ich diese Information kenne und Ihre Partnerin nicht?","reply":"Ich würde mich fragen, ob Sie mich anders ansehen.","why":"Du arbeitest fallbezogen an „Rollenkonflikt präzise benennen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Clara lehnt sich etwas nach vorne.]"},{"say":"Worüber machen Sie sich im nächsten Paargespräch am meisten Sorgen?","reply":"Dass Sie etwas andeuten.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Rollenkonflikt präzise benennen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Clara schaut einen Moment zum Fenster.]"},{"say":"Vielleicht könnte die andere Person lernen, Ihre Gefühle besser zu akzeptieren?","reply":"Darauf habe ich wenig Einfluss. Ich muss ja auch für mich entscheiden.","why":"Perspektivenübernahme ist wichtig, aber das aktuelle Anliegen und die bestehenden Grenzen dürfen nicht ausgelagert werden.","cue":"[Clara zieht die Augenbrauen kurz hoch.]"},{"say":"Wollen wir zunächst an Ihrer Formulierung arbeiten, damit sie nicht verletzend wirkt?","reply":"Ich bemühe mich dauernd, alles richtig zu sagen.","why":"Schonende Sprache ist wertvoll, doch die Frage nach Wahlfreiheit und Konsequenzen bleibt offen.","cue":"[Clara rückt auf dem Stuhl nach hinten.]"}]},{"focus":"Risiken des weiteren Vorgehens klären","options":[{"say":"Welche Risiken hätte für Sie eine Offenlegung, und welche hätte dauerhaftes Schweigen im gemeinsamen Beratungsprozess?","reply":"Offenlegung wäre heftig. Schweigen hält die Angst aber auch wach.","why":"Du arbeitest fallbezogen an „Risiken des weiteren Vorgehens klären“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Clara lässt die Schultern kurz sinken.]"},{"say":"Welche Unterstützung bräuchten Sie vor einer Entscheidung über die nächsten Schritte?","reply":"Ein vertrauliches Einzelgespräch über die Folgen.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Risiken des weiteren Vorgehens klären“, lässt aber eine wichtige Vertiefung offen.","cue":"[Clara hält inne und antwortet erst nach einigen Sekunden.]"},{"say":"Wie wäre es, wenn Sie vor dem nächsten Termin bereits eine neue gemeinsame Vereinbarung vorschlagen?","reply":"Ich weiß nicht, ob ich bis dahin schon bereit bin.","why":"Vereinbarungen können helfen, aber ohne geklärte Risiken und Freiwilligkeit wäre das zu schnell.","cue":"[Clara blickt auf die eigenen Hände.]"},{"say":"Könnten Sie Ihre Bedürfnisse erst einmal für sich behalten, bis die Lage ruhiger ist?","reply":"Das mache ich eigentlich schon seit Monaten.","why":"Aufschieben kann kurzfristig entlasten, kann aber Grenzverletzungen oder Selbstaufgabe fortsetzen.","cue":"[Clara spricht nun hörbar schneller.]"}]},{"focus":"Transparente nächste Schritte vereinbaren","options":[{"say":"Können wir den gültigen Rahmen und Ihre Wahlmöglichkeiten so klären, dass ich keine verdeckte Rolle übernehme?","reply":"Ja. Ich möchte erst wissen, was die Regeln sind, bevor ich etwas verrate.","why":"Du arbeitest fallbezogen an „Transparente nächste Schritte vereinbaren“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Clara schaut dich direkt an und spricht ruhig.]"},{"say":"Wäre eine getrennte Beratung hilfreich, damit die Rollen sauber bleiben?","reply":"Vielleicht. Das fühlt sich klarer an.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Transparente nächste Schritte vereinbaren“, lässt aber eine wichtige Vertiefung offen.","cue":"[Clara lächelt ganz kurz und wird dann wieder ernst.]"},{"say":"Was wäre ein endgültiges Ergebnis, mit dem alle sofort zufrieden wären?","reply":"Ich glaube nicht, dass das heute überhaupt möglich ist.","why":"Ein abschließender Konsens ist oft nicht realistisch und kann Entscheidungsdruck erzeugen.","cue":"[Clara presst die Lippen kurz zusammen.]"},{"say":"Sollten wir einfach einen neuen Termin machen und schauen, ob sich die Situation von selbst entspannt?","reply":"Bis dahin bleibt die Situation ja dieselbe.","why":"Ein Folgetermin kann sinnvoll sein, aber ein konkreter sicherer nächster Schritt fehlt.","cue":"[Clara schüttelt leicht den Kopf und schweigt.]"}]}],"repair":{"focus":"Kontaktreparatur nach einer wenig hilfreichen Intervention","options":[{"say":"Ich habe gerade zu schnell eine Richtung vorgeschlagen. Ich möchte zu Ihrer letzten Aussage zurückgehen und verstehen, was daran für Sie am schwersten ist.","why":"Du bearbeitest die eigene Wirkung und öffnest wieder einen fallbezogenen Austausch.","reply":"Das hilft. Ich wollte vor allem, dass Sie erst einmal zuhören.","cue":"[Die Person sieht dich an und spricht langsamer weiter.]"},{"say":"Was hätte ich an Ihrer Reaktion gerade genauer wahrnehmen sollen?","why":"Allianzklärung ist hilfreich; der eigene Anteil kann noch expliziter benannt werden.","reply":"Dass ich noch nicht bereit war, direkt eine Lösung zu finden.","cue":"[Der Blick wandert kurz zur Tür, dann zurück zu dir.]"},{"say":"Ich denke, mein Vorschlag war grundsätzlich richtig. Vielleicht haben Sie ihn missverstanden.","why":"Die Verteidigung deiner Absicht kann die Distanz erhöhen.","reply":"Jetzt muss ich auch noch erklären, warum mir Ihre Worte nicht geholfen haben.","cue":"[Der Oberkörper rückt ein Stück vom Tisch zurück.]"},{"say":"Dann lassen wir dieses schwierige Thema heute besser aus.","why":"Du vermeidest die notwendige gemeinsame Klärung.","reply":"Aber deshalb bin ich doch hier.","cue":"[Die Person rutscht auf dem Stuhl zurück und hebt die Augenbrauen.]"}]}},{"id":"abwertung","category":"Kontakt & Macht","title":"Sie haben ja keine Ahnung von meinem Leben","level":2,"goal":"Abwertung aushalten, Grenzen wahren, eigene Position transparent machen","context":"Nach einem vorsichtigen Deutungsangebot stellt Mina deine Erfahrung und Eignung in Frage. Sie wurde in früheren Hilfekontakten wiederholt übergangen.","opening":"Sie reden so einfach. Sie haben ja keine Ahnung, wie das in meinem Leben wirklich ist.","anchor":"Kulturelle Demut und Allianzreparatur: eigene Wissensgrenzen offenlegen, auf die konkrete Wirkung zurückkommen und den Auftrag neu abstimmen.","guard":"Bei persönlicher Abwertung: professionelle Grenze wahren, nicht um fachliche Überlegenheit kämpfen.","person":{"name":"Mina","image":"training-assets/characters/mina.webp","role":"Klientin"},"openingCue":"[Mina zieht kurz die Augenbrauen hoch und wendet den Oberkörper von dir ab.]","rounds":[{"focus":"Eigene Grenzen anerkennen","options":[{"say":"Sie haben recht, dass ich Ihr Leben nicht von innen kenne. Was habe ich eben übersehen oder zu schnell gedeutet?","why":"Du anerkennst Begrenzung und machst die konkrete Allianzreparatur möglich.","reply":"Dass ich keine Wahl habe, ob ich die Erwartungen meiner Familie erfülle.","cue":"[Der Blick hebt sich; die Stimme wird etwas ruhiger.]"},{"say":"Was sollte ich über Ihren Alltag unbedingt verstehen, bevor wir weitersprechen?","why":"Respektvoll; die eigene irritierende Intervention bleibt noch unbenannt.","reply":"Dass ich immer für alle verantwortlich bin.","cue":"[Die Person nickt einmal, blickt dann zur Seite.]"},{"say":"Meine Ausbildung gibt mir durchaus die Kompetenz, Ihnen zu helfen.","why":"Du gehst in einen Machtkampf um Legitimation.","reply":"Dann wollen Sie also vor allem recht haben.","cue":"[Die Stirn legt sich in Falten; die Antwort wird kürzer.]"},{"say":"So einen Ton brauche ich hier aber nicht.","why":"Eine Grenze kann nötig sein; als erste Reaktion könnte sie den Kontaktbruch übergehen.","reply":"Gut. Dann halte ich eben den Mund.","cue":"[Die Stimme wird deutlich lauter; die Arme verschränken sich.]"}]},{"focus":"Den übergangenen Kontext verstehen","options":[{"say":"Was passiert, wenn Sie eine Erwartung Ihrer Familie nicht erfüllen?","why":"Du erkundest mögliche Konsequenzen statt bloßer Wünsche.","reply":"Dann heißt es sofort, ich sei undankbar.","cue":"[Die Person hält kurz inne und lässt die Hände sinken.]"},{"say":"Welche Menschen erwarten besonders viel von Ihnen?","why":"Konkrete Systemanalyse hilft; die Wirkung des Drucks folgt.","reply":"Meine Eltern und meine Geschwister.","cue":"[Ein Finger streicht über den Ärmel; die Stimme bleibt leise.]"},{"say":"Vielleicht hilft es, sich einfach besser abzugrenzen.","why":"Ein schneller Ratschlag ignoriert Abhängigkeiten.","reply":"Sie kennen meine Familie nicht. Das habe ich doch gesagt.","cue":"[Die Person schüttelt leicht den Kopf und atmet hörbar aus.]"},{"say":"Sie müssen aber auch verstehen, dass Familie Verpflichtung bedeutet.","why":"Du bestätigst möglicherweise den Druck statt ihn zu untersuchen.","reply":"Genau deswegen rede ich hier ungern darüber.","cue":"[Die Person blickt weg und schweigt mehrere Sekunden.]"}]},{"focus":"Position entwickeln","options":[{"say":"Was wünschen Sie sich selbst, und wo wäre ein kleiner Schritt möglich, ohne unnötiges Risiko einzugehen?","why":"Selbstposition und realistischer Kontext werden verbunden.","reply":"Vielleicht kann ich zuerst mit meiner Schwester sprechen.","cue":"[Die Schultern lösen sich ein wenig; es folgt eine längere Antwort.]"},{"say":"Welche Unterstützung würde Ihnen dabei helfen, Veränderungen zu erproben?","why":"Ressourcenfrage sinnvoll; der eigene Wunsch könnte noch präzisiert werden.","reply":"Eine Person, die nicht sofort urteilt.","cue":"[Die Person lehnt sich vor und macht eine kurze Pause.]"},{"say":"Könnten Sie einfach Nein sagen und sehen, was passiert?","why":"Ohne Folgenabschätzung potenziell riskant.","reply":"Das kann ich mir gerade nicht leisten.","cue":"[Die Hände werden fester ineinander verschränkt.]"},{"say":"Sie müssen erst lernen, auf sich selbst zu achten.","why":"Normierende Aufforderung statt gemeinsame Exploration.","reply":"Das klingt wieder so einfach.","cue":"[Der Kiefer spannt sich an; die Worte kommen abgehackt.]"}]},{"focus":"Die Allianz überprüfen","options":[{"say":"Wie war dieses Gespräch heute für Sie – gab es etwas, das ich diesmal besser verstanden habe oder wieder übersehen habe?","why":"Du überprüfst die Allianz und lädst zur Korrektur ein.","reply":"Diesmal haben Sie mehr gefragt, bevor Sie etwas erklärt haben.","cue":"[Die Person sieht dich an und spricht langsamer weiter.]"},{"say":"Wollen wir beim nächsten Mal an dem kleinen Schritt mit Ihrer Schwester anknüpfen?","why":"Konkretes Weiterarbeiten ist sinnvoll; Rückmeldung zur Beziehung könnte ergänzt werden.","reply":"Ja. Das wäre gut.","cue":"[Der Blick wandert kurz zur Tür, dann zurück zu dir.]"},{"say":"Jetzt wissen Sie doch, dass ich sehr wohl helfen kann.","why":"Erfolg wird als Selbstbeweis verwendet.","reply":"Darum geht es mir nicht.","cue":"[Der Oberkörper rückt ein Stück vom Tisch zurück.]"},{"say":"Dann schließen wir das Thema hiermit ab.","why":"Du beschließt einseitig den Prozess.","reply":"Ich bin gar nicht sicher, ob ich schon fertig bin.","cue":"[Die Person rutscht auf dem Stuhl zurück und hebt die Augenbrauen.]"}]},{"focus":"Die eigene Intervention überprüfen","options":[{"say":"Welche meiner Annahmen hat gerade Ihren tatsächlichen Lebensumständen widersprochen?","reply":"Sie haben so getan, als könnte ich einfach Nein zu meiner Familie sagen.","why":"Du arbeitest fallbezogen an „Die eigene Intervention überprüfen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Mina atmet aus und hebt kurz den Blick.]"},{"say":"Was war an meinem Vorschlag für Ihren Alltag nicht umsetzbar?","reply":"Meine Familie würde mich dafür massiv unter Druck setzen.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Die eigene Intervention überprüfen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Mina nickt langsam; zwischen den Sätzen entsteht eine Pause.]"},{"say":"Könnten wir zuerst einen ganz konkreten Auslöser von heute sammeln, bevor wir die Beziehung zwischen uns anschauen?","reply":"Ein Beispiel hätte ich schon. Aber darum ging es gerade nicht.","why":"Eine konkrete Situation ist hilfreich, doch der aktuelle Kontaktbruch beziehungsweise emotionale Moment wird verschoben.","cue":"[Mina runzelt kurz die Stirn und schaut zur Seite.]"},{"say":"Wäre es besser, direkt eine neue Gesprächsregel einzuführen?","reply":"Wir haben schon öfter Regeln vereinbart. Das ändert hier gerade nichts.","why":"Neue Regeln können später helfen; die aktuelle Wirkung der Worte ist noch nicht gemeinsam verstanden.","cue":"[Mina spricht leiser und verschränkt die Hände.]"}]},{"focus":"Kontext und Handlungsspielraum trennen","options":[{"say":"Wobei haben Sie tatsächlich Wahlfreiheit, und wo sind die Kosten einer Entscheidung derzeit hoch?","reply":"Ich kann kleine Dinge ändern, aber nicht einfach ausziehen.","why":"Du arbeitest fallbezogen an „Kontext und Handlungsspielraum trennen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Mina lehnt sich etwas nach vorne.]"},{"say":"Welche kleinen Veränderungen wären realistisch, ohne Ihre Situation zu verharmlosen?","reply":"Dass ich wenigstens meine freie Zeit schützen kann.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Kontext und Handlungsspielraum trennen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Mina schaut einen Moment zum Fenster.]"},{"say":"Was würde sich verändern, wenn die andere Person in Zukunft ganz anders reagieren würde?","reply":"Dann wäre es einfacher. Aber ich weiß nicht, was ich selbst tun könnte.","why":"Der Blick auf das Gegenüber kann sinnvoll sein; hier rückt der eigene innere Ablauf aus dem Fokus.","cue":"[Mina zieht die Augenbrauen kurz hoch.]"},{"say":"Sollten wir das Gespräch an dieser Stelle lieber neutral zusammenfassen?","reply":"Mir fehlt dabei etwas. Ich habe noch gar nicht gesagt, wie sich das anfühlt.","why":"Zusammenfassen unterstützt Klarheit, greift aber die gerade auftauchende Emotion nicht auf.","cue":"[Mina rückt auf dem Stuhl nach hinten.]"}]},{"focus":"Zusammenarbeit neu gestalten","options":[{"say":"Wie müsste ich nachfragen, damit wir nicht wieder an Ihrer Wirklichkeit vorbeiplanen?","reply":"Fragen Sie erst, wer von mir abhängig ist und warum.","why":"Du arbeitest fallbezogen an „Zusammenarbeit neu gestalten“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Mina lässt die Schultern kurz sinken.]"},{"say":"Wären Sie einverstanden, dass wir unsere Vorschläge stärker an den realen Grenzen prüfen?","reply":"Ja. Dann kann ich ehrlicher sein.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Zusammenarbeit neu gestalten“, lässt aber eine wichtige Vertiefung offen.","cue":"[Mina hält inne und antwortet erst nach einigen Sekunden.]"},{"say":"Könnten wir jetzt üben, wie Sie die Situation Ihrer Partnerin ganz ruhig erklären?","reply":"Das könnte ich sagen. Ob ich es dann auch schaffe, weiß ich nicht.","why":"Ein Probehandeln ist sinnvoll; zuvor ist wichtig, die innere Reaktion und die Verantwortung zu verstehen.","cue":"[Mina blickt auf die eigenen Hände.]"},{"say":"Wollen wir klären, wer von Ihnen beiden den Streit eigentlich häufiger beginnt?","reply":"Dann geht es wieder darum, wer schuld ist.","why":"Die Suche nach einer Verteilung kann wie eine neue Schuldfrage wirken, statt das konkrete Muster zu bearbeiten.","cue":"[Mina spricht nun hörbar schneller.]"}]},{"focus":"Feedback zur Beratungsallianz einholen","options":[{"say":"Woran würden Sie heute merken, dass wir wieder gemeinsam arbeiten statt gegeneinander?","reply":"Wenn ich widersprechen darf und Sie nicht beleidigt sind.","why":"Du arbeitest fallbezogen an „Feedback zur Beratungsallianz einholen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Mina schaut dich direkt an und spricht ruhig.]"},{"say":"Was soll ich tun, wenn ich Ihre Situation erneut zu einfach darstelle?","reply":"Fragen Sie nach und hören Sie zu.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Feedback zur Beratungsallianz einholen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Mina lächelt ganz kurz und wird dann wieder ernst.]"},{"say":"Welche drei Maßnahmen wollen Sie ab morgen verbindlich umsetzen?","reply":"Drei Dinge? Ich weiß nicht, ob ich das gleich schaffe.","why":"Konkrete Ziele sind hilfreich, aber drei Maßnahmen gleichzeitig können zu viel sein und übergehen die eigene Bereitschaft.","cue":"[Mina presst die Lippen kurz zusammen.]"},{"say":"Möchten Sie, dass ich Ihnen meine bevorzugte Lösung nenne?","reply":"Ich wäre froh über einen Tipp. Aber ob er zu mir passt?","why":"Ein Vorschlag kann entlasten, würde hier aber Selbstverantwortung und Mitgestaltung schwächen.","cue":"[Mina schüttelt leicht den Kopf und schweigt.]"}]}],"repair":{"focus":"Kontaktreparatur nach einer wenig hilfreichen Intervention","options":[{"say":"Ich habe gerade zu schnell eine Richtung vorgeschlagen. Ich möchte zu Ihrer letzten Aussage zurückgehen und verstehen, was daran für Sie am schwersten ist.","why":"Du bearbeitest die eigene Wirkung und öffnest wieder einen fallbezogenen Austausch.","reply":"Das hilft. Ich wollte vor allem, dass Sie erst einmal zuhören.","cue":"[Der Blick hebt sich; die Stimme wird etwas ruhiger.]"},{"say":"Was hätte ich an Ihrer Reaktion gerade genauer wahrnehmen sollen?","why":"Allianzklärung ist hilfreich; der eigene Anteil kann noch expliziter benannt werden.","reply":"Dass ich noch nicht bereit war, direkt eine Lösung zu finden.","cue":"[Die Person nickt einmal, blickt dann zur Seite.]"},{"say":"Ich denke, mein Vorschlag war grundsätzlich richtig. Vielleicht haben Sie ihn missverstanden.","why":"Die Verteidigung deiner Absicht kann die Distanz erhöhen.","reply":"Jetzt muss ich auch noch erklären, warum mir Ihre Worte nicht geholfen haben.","cue":"[Die Stirn legt sich in Falten; die Antwort wird kürzer.]"},{"say":"Dann lassen wir dieses schwierige Thema heute besser aus.","why":"Du vermeidest die notwendige gemeinsame Klärung.","reply":"Aber deshalb bin ich doch hier.","cue":"[Die Stimme wird deutlich lauter; die Arme verschränken sich.]"}]}},{"id":"trennung","category":"Akute Beziehungskrise","title":"Morgen packt sie ihre Sachen","level":3,"goal":"Ambivalenz halten und drohende Trennung ohne Aktionismus begleiten","context":"Emil erfuhr am Morgen, dass seine Partnerin ausziehen möchte. Im Gespräch wechseln Vorwürfe, Verzweiflung und die Suche nach einem schnellen Plan.","opening":"Sie hat gesagt, sie zieht morgen aus. Sagen Sie mir bitte, was ich tun kann, damit sie bleibt!","anchor":"Krisennahe Beziehungsberatung: emotionale Stabilisierung, Autonomie der Partnerperson, Handlungsspielraum ohne Manipulation und realistische Unterstützungsangebote.","guard":"Bei Selbst- oder Fremdgefährdungsankündigungen ist sofort eine gesonderte Risikoabklärung erforderlich.","person":{"name":"Emil","image":"training-assets/characters/emil.webp","role":"Klient"},"openingCue":"[Emil spricht schnell; er hält sein Telefon fest in der Hand.]","rounds":[{"focus":"Kontrollwunsch würdigen und begrenzen","options":[{"say":"Sie möchten dringend verhindern, dass sie geht. Was macht die Vorstellung vom morgigen Tag gerade so überwältigend?","why":"Du gehst zum Erleben, ohne die Entscheidung einer anderen Person kontrollieren zu wollen.","reply":"Dass ich danach alleine in der Wohnung sitze.","cue":"[Die Person hält kurz inne und lässt die Hände sinken.]"},{"say":"Was genau hat Ihre Partnerin als Grund genannt?","why":"Relevant, aber die akute Überforderung wird nur indirekt aufgegriffen.","reply":"Sie sagt, sie könne so nicht mehr weitermachen.","cue":"[Ein Finger streicht über den Ärmel; die Stimme bleibt leise.]"},{"say":"Schreiben Sie ihr sofort, dass Sie sich ändern werden.","why":"Ein Versprechen im Alarmzustand kann Druck verstärken und unauthentisch sein.","reply":"Das habe ich schon dreimal geschrieben.","cue":"[Die Person schüttelt leicht den Kopf und atmet hörbar aus.]"},{"say":"Vielleicht ist es besser, die Beziehung einfach loszulassen.","why":"Eine vorschnelle Richtungsvorgabe übergeht Ambivalenz.","reply":"Ich kann gerade überhaupt nicht loslassen.","cue":"[Die Person blickt weg und schweigt mehrere Sekunden.]"}]},{"focus":"Akute Belastung einschätzen","options":[{"say":"Wie kommen Sie heute durch den Abend, und wer könnte Sie begleiten, wenn es sehr schwer wird?","why":"Du klärst konkrete Stabilisierung und Unterstützung im unmittelbaren Zeitfenster.","reply":"Mein Bruder könnte kommen. Ich habe mich nur nicht getraut, ihn anzurufen.","cue":"[Die Schultern lösen sich ein wenig; es folgt eine längere Antwort.]"},{"say":"Was hat Ihnen bei früheren sehr schweren Tagen geholfen?","why":"Ressourcenarbeit sinnvoll; heute Abend verdient konkrete Planung.","reply":"Spazieren und jemanden anrufen.","cue":"[Die Person lehnt sich vor und macht eine kurze Pause.]"},{"say":"Konzentrieren wir uns auf eine Strategie, wie Sie sie umstimmen.","why":"Einseitige Einflussstrategie beachtet die Autonomie der anderen Person nicht.","reply":"Ja, ich muss nur die richtige Formulierung finden.","cue":"[Die Hände werden fester ineinander verschränkt.]"},{"say":"Wenn Sie stark genug wären, könnten Sie das allein aushalten.","why":"Beschämung und Isolation können die Belastung erhöhen.","reply":"Gerade fühle ich mich nicht stark.","cue":"[Der Kiefer spannt sich an; die Worte kommen abgehackt.]"}]},{"focus":"Autonomie beider Personen respektieren","options":[{"say":"Welche Nachricht wäre ehrlich über Ihre Gefühle, ohne sie zu bedrängen oder ihre Entscheidung zu übergehen?","why":"Du stärkst verantwortlichen Kontakt statt Kontrolle.","reply":"Vielleicht: Ich bin traurig und würde gern reden, aber ich respektiere, wenn du morgen Abstand brauchst.","cue":"[Die Person sieht dich an und spricht langsamer weiter.]"},{"say":"Was möchten Sie ihr sagen, selbst wenn ihre Entscheidung bestehen bleibt?","why":"Die Frage stärkt Eigenposition; Druckfreiheit könnte deutlicher sein.","reply":"Dass mir die Beziehung viel bedeutet.","cue":"[Der Blick wandert kurz zur Tür, dann zurück zu dir.]"},{"say":"Sie könnten unangekündigt zu ihr fahren, damit sie merkt, wie ernst es Ihnen ist.","why":"Unangekündigtes Aufsuchen kann Grenzen verletzen und eskalieren.","reply":"Ich weiß nicht, ob sie mich überhaupt sehen will.","cue":"[Der Oberkörper rückt ein Stück vom Tisch zurück.]"},{"say":"Sie sollten ihr gar nichts mehr sagen, um die Situation zu kontrollieren.","why":"Strategisches Schweigen kann als Machtmittel dienen.","reply":"Ich will sie aber auch nicht bestrafen.","cue":"[Die Person rutscht auf dem Stuhl zurück und hebt die Augenbrauen.]"}]},{"focus":"Konkrete nächste Schritte","options":[{"say":"Was nehmen Sie für die nächsten 24 Stunden mit – Unterstützung organisieren, Grenzen respektieren und auf sich achten?","why":"Du verankerst realistische, kontrollierbare Handlungen.","reply":"Ich rufe meinen Bruder an und schreibe ihr heute keine zehn Nachrichten mehr.","cue":"[Der Blick hebt sich; die Stimme wird etwas ruhiger.]"},{"say":"Wäre ein kurzer Plan hilfreich, wie Sie morgen auf sich achten?","why":"Struktur ist hilfreich; Unterstützung und Grenzen können genauer hinein.","reply":"Ja, sonst sitze ich nur am Handy.","cue":"[Die Person nickt einmal, blickt dann zur Seite.]"},{"say":"Vielleicht brauchen Sie jetzt einfach viel Ablenkung.","why":"Ablenkung allein unterschätzt akute Belastung und die Beziehungssituation.","reply":"Ich kann nicht einmal einen Film verfolgen.","cue":"[Die Stirn legt sich in Falten; die Antwort wird kürzer.]"},{"say":"Erst wenn sie geht, können Sie überlegen, wie es weitergeht.","why":"Passive Haltung statt kurzer Stabilisierung.","reply":"Aber heute Nacht ist schon schwer genug.","cue":"[Die Stimme wird deutlich lauter; die Arme verschränken sich.]"}]},{"focus":"Akute Impulse entflechten","options":[{"say":"Was wäre der nächste Schritt, der Ihre Verzweiflung ernst nimmt, ohne die Grenze Ihrer Partnerin zu überschreiten?","reply":"Ich könnte heute einen Freund anrufen statt ihr zehn Nachrichten zu schreiben.","why":"Du arbeitest fallbezogen an „Akute Impulse entflechten“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Emil atmet aus und hebt kurz den Blick.]"},{"say":"Was hilft Ihnen, den Drang nach sofortigem Kontakt auszuhalten?","reply":"Mein Freund könnte bei mir bleiben.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Akute Impulse entflechten“, lässt aber eine wichtige Vertiefung offen.","cue":"[Emil nickt langsam; zwischen den Sätzen entsteht eine Pause.]"},{"say":"Wäre es hilfreich, wenn Sie der anderen Person Ihre Sicht jetzt sehr deutlich erklären?","reply":"Ich müsste erst selbst wissen, was ich sagen will.","why":"Klarheit kann helfen, doch ein Gespräch mit dem Gegenüber ist nicht automatisch sicher oder freiwillig.","cue":"[Emil runzelt kurz die Stirn und schaut zur Seite.]"},{"say":"Sollen wir versuchen, sofort eine gemeinsame Mitte zwischen beiden Positionen zu finden?","reply":"Ich weiß gar nicht, ob ich gerade verhandeln möchte.","why":"Ein Kompromiss ist nicht bei jeder Macht- oder Grenzkonstellation angemessen; erst müssen die Voraussetzungen geklärt werden.","cue":"[Emil spricht leiser und verschränkt die Hände.]"}]},{"focus":"Ein Nein respektieren","options":[{"say":"Was geschieht in Ihnen, wenn Sie ihre Entscheidung akzeptieren sollen, obwohl Sie es nicht wollen?","reply":"Ich fühle mich machtlos und wütend.","why":"Du arbeitest fallbezogen an „Ein Nein respektieren“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Emil lehnt sich etwas nach vorne.]"},{"say":"Wie könnten wir Ihre Gefühle ernst nehmen, ohne auf ihre Entscheidung einzuwirken?","reply":"Ich will verstehen, wie ich damit leben kann.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Ein Nein respektieren“, lässt aber eine wichtige Vertiefung offen.","cue":"[Emil schaut einen Moment zum Fenster.]"},{"say":"Vielleicht könnte die andere Person lernen, Ihre Gefühle besser zu akzeptieren?","reply":"Darauf habe ich wenig Einfluss. Ich muss ja auch für mich entscheiden.","why":"Perspektivenübernahme ist wichtig, aber das aktuelle Anliegen und die bestehenden Grenzen dürfen nicht ausgelagert werden.","cue":"[Emil zieht die Augenbrauen kurz hoch.]"},{"say":"Wollen wir zunächst an Ihrer Formulierung arbeiten, damit sie nicht verletzend wirkt?","reply":"Ich bemühe mich dauernd, alles richtig zu sagen.","why":"Schonende Sprache ist wertvoll, doch die Frage nach Wahlfreiheit und Konsequenzen bleibt offen.","cue":"[Emil rückt auf dem Stuhl nach hinten.]"}]},{"focus":"Stabilisierung im Alltag planen","options":[{"say":"Wer könnte die nächsten Tage verlässlich erreichbar sein, wenn der Kontaktwunsch besonders stark wird?","reply":"Mein Bruder kann mich abends anrufen.","why":"Du arbeitest fallbezogen an „Stabilisierung im Alltag planen“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Emil lässt die Schultern kurz sinken.]"},{"say":"Welche konkrete Struktur könnte die nächsten zwei Tage entlasten?","reply":"Nicht allein bleiben und schlafen versuchen.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Stabilisierung im Alltag planen“, lässt aber eine wichtige Vertiefung offen.","cue":"[Emil hält inne und antwortet erst nach einigen Sekunden.]"},{"say":"Wie wäre es, wenn Sie vor dem nächsten Termin bereits eine neue gemeinsame Vereinbarung vorschlagen?","reply":"Ich weiß nicht, ob ich bis dahin schon bereit bin.","why":"Vereinbarungen können helfen, aber ohne geklärte Risiken und Freiwilligkeit wäre das zu schnell.","cue":"[Emil blickt auf die eigenen Hände.]"},{"say":"Könnten Sie Ihre Bedürfnisse erst einmal für sich behalten, bis die Lage ruhiger ist?","reply":"Das mache ich eigentlich schon seit Monaten.","why":"Aufschieben kann kurzfristig entlasten, kann aber Grenzverletzungen oder Selbstaufgabe fortsetzen.","cue":"[Emil spricht nun hörbar schneller.]"}]},{"focus":"Selbstverantwortliche nächsten Schritte","options":[{"say":"Was können Sie sich selbst für heute zusagen, das mit ihren Grenzen vereinbar ist?","reply":"Ich schreibe ihr heute nicht. Ich suche mir Unterstützung.","why":"Du arbeitest fallbezogen an „Selbstverantwortliche nächsten Schritte“ und eröffnest einen nächsten, überprüfbaren Schritt.","cue":"[Emil schaut dich direkt an und spricht ruhig.]"},{"say":"Welche realistische Vereinbarung möchten Sie nur mit sich selbst treffen?","reply":"Dass ich die Nachrichten zuerst in ein Notizbuch schreibe.","why":"Diese Intervention ist im Fall gut vertretbar. Sie erfasst einen relevanten Teil von „Selbstverantwortliche nächsten Schritte“, lässt aber eine wichtige Vertiefung offen.","cue":"[Emil lächelt ganz kurz und wird dann wieder ernst.]"},{"say":"Was wäre ein endgültiges Ergebnis, mit dem alle sofort zufrieden wären?","reply":"Ich glaube nicht, dass das heute überhaupt möglich ist.","why":"Ein abschließender Konsens ist oft nicht realistisch und kann Entscheidungsdruck erzeugen.","cue":"[Emil presst die Lippen kurz zusammen.]"},{"say":"Sollten wir einfach einen neuen Termin machen und schauen, ob sich die Situation von selbst entspannt?","reply":"Bis dahin bleibt die Situation ja dieselbe.","why":"Ein Folgetermin kann sinnvoll sein, aber ein konkreter sicherer nächster Schritt fehlt.","cue":"[Emil schüttelt leicht den Kopf und schweigt.]"}]}],"repair":{"focus":"Kontaktreparatur nach einer wenig hilfreichen Intervention","options":[{"say":"Ich habe gerade zu schnell eine Richtung vorgeschlagen. Ich möchte zu Ihrer letzten Aussage zurückgehen und verstehen, was daran für Sie am schwersten ist.","why":"Du bearbeitest die eigene Wirkung und öffnest wieder einen fallbezogenen Austausch.","reply":"Das hilft. Ich wollte vor allem, dass Sie erst einmal zuhören.","cue":"[Die Person hält kurz inne und lässt die Hände sinken.]"},{"say":"Was hätte ich an Ihrer Reaktion gerade genauer wahrnehmen sollen?","why":"Allianzklärung ist hilfreich; der eigene Anteil kann noch expliziter benannt werden.","reply":"Dass ich noch nicht bereit war, direkt eine Lösung zu finden.","cue":"[Ein Finger streicht über den Ärmel; die Stimme bleibt leise.]"},{"say":"Ich denke, mein Vorschlag war grundsätzlich richtig. Vielleicht haben Sie ihn missverstanden.","why":"Die Verteidigung deiner Absicht kann die Distanz erhöhen.","reply":"Jetzt muss ich auch noch erklären, warum mir Ihre Worte nicht geholfen haben.","cue":"[Die Person schüttelt leicht den Kopf und atmet hörbar aus.]"},{"say":"Dann lassen wir dieses schwierige Thema heute besser aus.","why":"Du vermeidest die notwendige gemeinsame Klärung.","reply":"Aber deshalb bin ich doch hier.","cue":"[Die Person blickt weg und schweigt mehrere Sekunden.]"}]}}];
